import { useEffect, useRef, useState } from "react";
import { supabase } from "./supabase";

/* =========================================================
   ROLE
========================================================= */

const ROLE_ADMIN = "admin";
const ROLE_DISPECER = "dispecer";
const ROLE_RIDIC = "ridic";
const ROLE_DKV = "dkv_lichkov";
const ROLE_DKV_ADMIN = "dkv_lichkov_admin";
const ROLE_OPTIONS = [
  [ROLE_RIDIC, "Řidič"],
  [ROLE_DISPECER, "Dispečer"],
  [ROLE_DKV, "DKV Lichkov"],
  [ROLE_DKV_ADMIN, "DKV Lichkov admin"],
  [ROLE_ADMIN, "Administrátor"],
];

function normalizeRole(value) {
  const role = String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  if (role === "admin" || role === "administrator") return ROLE_ADMIN;
  if (role === "dispecer" || role === "dispatcher") return ROLE_DISPECER;
  if (role === "ridic" || role === "driver") return ROLE_RIDIC;
  if (role === ROLE_DKV || role === "dkv lichkov") return ROLE_DKV;
  if (role === ROLE_DKV_ADMIN || role === "dkv lichkov admin") return ROLE_DKV_ADMIN;

  return "";
}

function getAssignedRoles(value) {
  const selected = Array.isArray(value)
    ? value
    : value && typeof value === "object"
      ? (Array.isArray(value.roles) && value.roles.length ? value.roles : [value.role])
      : [value];
  return [...new Set(selected.map(normalizeRole).filter(Boolean))];
}

function hasRole(value, target) {
  return getAssignedRoles(value).includes(target);
}

// Zachováme původní jednosloupcovou roli pro existující databázová pravidla.
function getPrimaryRole(roles) {
  const selected = getAssignedRoles(roles);
  return [ROLE_ADMIN, ROLE_DISPECER, ROLE_RIDIC, ROLE_DKV_ADMIN, ROLE_DKV]
    .find((item) => selected.includes(item)) || ROLE_RIDIC;
}

function canViewDkv(role) {
  return [ROLE_ADMIN, ROLE_DKV_ADMIN, ROLE_DKV]
    .some((item) => hasRole(role, item));
}

function canEditDkv(role) {
  return hasRole(role, ROLE_ADMIN) || hasRole(role, ROLE_DKV_ADMIN);
}

function canManageVehicles(role) {
  return hasRole(role, ROLE_ADMIN) || hasRole(role, ROLE_DISPECER);
}

function canManageReports(role) {
  return hasRole(role, ROLE_ADMIN) || hasRole(role, ROLE_DISPECER);
}

function canManageUsers(role) {
  return hasRole(role, ROLE_ADMIN);
}

function canUseReports(role) {
  return [ROLE_ADMIN, ROLE_DISPECER, ROLE_RIDIC]
    .some((item) => hasRole(role, item));
}

function canManageNews(role) {
  return hasRole(role, ROLE_ADMIN) || hasRole(role, ROLE_DISPECER);
}

function canViewWorkshop(role) {
  return hasRole(role, ROLE_ADMIN) || hasRole(role, ROLE_DISPECER);
}

function canEditWorkshop(role) {
  return hasRole(role, ROLE_ADMIN) || hasRole(role, ROLE_DISPECER);
}

function canViewBudget(role) {
  return [ROLE_ADMIN, ROLE_DISPECER, ROLE_DKV, ROLE_DKV_ADMIN]
    .some((item) => hasRole(role, item));
}

function canEditBudget(role) {
  return hasRole(role, ROLE_ADMIN);
}

function getRoleName(role) {
  const names = getAssignedRoles(role)
    .map((item) => ROLE_OPTIONS.find(([key]) => key === item)?.[1])
    .filter(Boolean);
  return names.length ? names.join(" · ") : "Neznámá role";
}

/* =========================================================
   LOGIN
========================================================= */

function Login({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleLogin(e) {
    e.preventDefault();

    setError("");
    setLoading(true);

    const { data, error } =
      await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });

    if (error) {
      setError("Nesprávný e-mail nebo heslo.");
      setLoading(false);
      return;
    }

    if (data?.user) {
      onLogin(data.user);
    }

    setLoading(false);
  }

  return (
    <div className="login-page">
      <div className="login-box">
        <div className="login-logo"><img src="/cm-logo.png" alt="CM" /></div>

        <h1>Czech Mobility</h1>
        <p>VDP systém</p>

        <form onSubmit={handleLogin}>
          <label>E-mail</label>

          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="vas@email.cz"
            required
          />

          <label>Heslo</label>

          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="••••••••"
            required
          />

          {error && <div className="login-error">{error}</div>}

          <button type="submit" disabled={loading}>
            {loading ? "Přihlašování..." : "Přihlásit se"}
          </button>
        </form>
      </div>
    </div>
  );
}

/* =========================================================
   REGISTRACE
========================================================= */

function Register({ onRegistered }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [password2, setPassword2] = useState("");

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleRegister(e) {
    e.preventDefault();

    setError("");
    setSuccess("");

    const cleanEmail = email.trim().toLowerCase();
    const cleanName = name.trim();

    if (password.length < 6) {
      setError("Heslo musí mít alespoň 6 znaků.");
      return;
    }

    if (password !== password2) {
      setError("Hesla se neshodují.");
      return;
    }

    setLoading(true);

    const { data: invite, error: inviteError } =
      await supabase
        .from("user_invites")
        .select("id, email, jmeno, role, roles, used")
        .eq("email", cleanEmail)
        .eq("used", false)
        .maybeSingle();

    if (inviteError) {
      setError(inviteError.message);
      setLoading(false);
      return;
    }

    if (!invite) {
      setError("Tento e-mail nebyl pozván administrátorem.");
      setLoading(false);
      return;
    }

    const { data, error } =
      await supabase.auth.signUp({
        email: cleanEmail,
        password,
      });

    if (error) {
      setError(error.message);
      setLoading(false);
      return;
    }

    if (!data?.user) {
      setError("Účet se nepodařilo vytvořit.");
      setLoading(false);
      return;
    }

    const inviteRoles = getAssignedRoles(invite);

    const { error: profileError } =
      await supabase.from("profiles").upsert(
        {
          id: data.user.id,
          jmeno: invite.jmeno || cleanName,
          role: getPrimaryRole(inviteRoles),
          roles: inviteRoles,
        },
        { onConflict: "id" }
      );

    if (profileError) {
      setError(profileError.message);
      setLoading(false);
      return;
    }

    await supabase
      .from("user_invites")
      .update({ used: true })
      .eq("id", invite.id);

    setSuccess(
      "Registrace byla úspěšná. Nyní se můžeš přihlásit."
    );

    setLoading(false);

    setTimeout(() => {
      onRegistered();
    }, 1500);
  }

  return (
    <div className="login-page">
      <div className="login-box">
        <div className="login-logo"><img src="/cm-logo.png" alt="CM" /></div>

        <h1>Registrace</h1>

        <p>
          Zaregistruj se pomocí e-mailu,
          který ti přidělil administrátor.
        </p>

        <form onSubmit={handleRegister}>
          <label>Jméno</label>

          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Tvoje jméno"
            required
          />

          <label>E-mail</label>

          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="vas@email.cz"
            required
          />

          <label>Heslo</label>

          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Min. 6 znaků"
            required
          />

          <label>Heslo znovu</label>

          <input
            type="password"
            value={password2}
            onChange={(e) => setPassword2(e.target.value)}
            placeholder="Zopakuj heslo"
            required
          />

          {error && <div className="login-error">{error}</div>}

          {success && <div className="success-box">{success}</div>}

          <button type="submit" disabled={loading}>
            {loading ? "Registrace..." : "Zaregistrovat se"}
          </button>
        </form>

        <button
          type="button"
          className="register-back"
          onClick={onRegistered}
        >
          Zpět na přihlášení
        </button>
      </div>
    </div>
  );
}

/* =========================================================
   PROVOZOVNY
========================================================= */

function useProvozovny() {
  const [provozovny, setProvozovny] = useState([]);
  const [loading, setLoading] = useState(true);

  async function loadProvozovny() {
    setLoading(true);

    const { data, error } = await supabase
      .from("provozovny")
      .select("id, nazev, kod")
      .order("nazev", { ascending: true });

    if (!error) {
      setProvozovny(data || []);
    } else {
      console.error(error);
      setProvozovny([]);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadProvozovny();
  }, []);

  return {
    provozovny,
    loading,
    reload: loadProvozovny,
  };
}

function getCourseDayLabel(value) {
  if (value === "PD") return "Pracovní den";
  if (value === "VIKEND") return "Víkend";
  if (value === "NE") return "Neděle";
  if (value === "DENNE") return "Každý den";
  return "Bez omezení dne";
}

function getCourseVariantLabel(value) {
  if (value === "PRAZDNINY") return "Prázdniny";
  if (value === "BEZNY") return "Běžný provoz";
  return "";
}

const MAIN_PROVOZOVNA_CODES = [
  "WRO",
  "370",
  "400",
  "BUK",
  "BRE",
  "BRN",
  "KAM", // Kameniště
  "OLO", // Olomouc
];

function normalizeProvozovnaName(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ł/g, "l")
    .replace(/Ł/g, "l")
    .toLowerCase()
    .trim();
}

function isMainProvozovna(provozovna) {
  const code = String(provozovna?.kod || "")
    .toUpperCase()
    .trim();
  const name = normalizeProvozovnaName(provozovna?.nazev);

  return (
    MAIN_PROVOZOVNA_CODES.includes(code) ||
    name === "370" ||
    name === "400" ||
    name === "breclavsko" ||
    name.startsWith("brno") ||
    name === "bukovec" ||
    name.includes("wroclaw") ||
    name.includes("breslau") ||
    name.includes("kameniste") ||
    name.includes("olomouc")
  );
}

function getMainProvozovny(provozovny = []) {
  return provozovny
    .filter(isMainProvozovna)
    .sort((a, b) => {
      const aCode = String(a?.kod || "").toUpperCase().trim();
      const bCode = String(b?.kod || "").toUpperCase().trim();
      const aIndex = MAIN_PROVOZOVNA_CODES.indexOf(aCode);
      const bIndex = MAIN_PROVOZOVNA_CODES.indexOf(bCode);

      if (aIndex >= 0 && bIndex >= 0) return aIndex - bIndex;
      if (aIndex >= 0) return -1;
      if (bIndex >= 0) return 1;

      return String(a?.nazev || "").localeCompare(
        String(b?.nazev || ""),
        "cs",
        { sensitivity: "base" }
      );
    });
}

function ProvozovnaSelect({
  value,
  onChange,
  provozovny,
  label = "Provozovna",
  required = false,
}) {
  const visibleProvozovny = getMainProvozovny(provozovny);

  return (
    <div>
      <label>{label}</label>

      <select
        value={value || ""}
        onChange={(e) => onChange(e.target.value)}
        required={required}
      >
        <option value="">Vyber provozovnu</option>

        {visibleProvozovny.map((provozovna) => (
          <option
            key={provozovna.id}
            value={provozovna.id}
          >
            {provozovna.nazev}
            {provozovna.kod
              ? ` (${provozovna.kod})`
              : ""}
          </option>
        ))}
      </select>
    </div>
  );
}

/* =========================================================
   SPRÁVA UŽIVATELŮ
========================================================= */

function RoleCheckboxes({ roles, onChange, label }) {
  const selected = getAssignedRoles(roles);
  return (
    <fieldset className="role-checkboxes">
      <legend>{label}</legend>
      {ROLE_OPTIONS.map(([key, name]) => (
        <label key={key}>
          <input
            type="checkbox"
            checked={selected.includes(key)}
            disabled={selected.length === 1 && selected.includes(key)}
            onChange={(event) => onChange(event.target.checked
              ? [...selected, key]
              : selected.filter((item) => item !== key))}
          />
          {name}
        </label>
      ))}
    </fieldset>
  );
}

function AdminUsers() {
  const [users, setUsers] = useState([]);
  const [invites, setInvites] = useState([]);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [showForm, setShowForm] = useState(false);
  const [filterRole, setFilterRole] = useState("Vše");

  const emptyForm = {
    jmeno: "",
    email: "",
    roles: [ROLE_RIDIC],
  };

  const [form, setForm] = useState(emptyForm);

  async function loadUsers() {
    const { data, error } = await supabase
      .from("profiles")
      .select("id, jmeno, role, roles, created_at")
      .order("created_at", { ascending: false });

    if (error) {
      setError(error.message);
      setUsers([]);
    } else {
      setUsers(data || []);
    }
  }

  async function loadInvites() {
    const { data, error } = await supabase
      .from("user_invites")
      .select("id, email, jmeno, role, roles, used, created_at")
      .order("created_at", { ascending: false });

    if (!error) {
      setInvites(data || []);
    }
  }

  async function loadAll() {
    setLoading(true);
    setError("");

    await Promise.all([
      loadUsers(),
      loadInvites(),
    ]);

    setLoading(false);
  }

  useEffect(() => {
    loadAll();
  }, []);

  async function createInvite(e) {
    e.preventDefault();

    setSaving(true);
    setError("");
    setSuccess("");

    const email = form.email.trim().toLowerCase();
    const name = form.jmeno.trim();

    if (!name || !email) {
      setError("Vyplň jméno a e-mail.");
      setSaving(false);
      return;
    }

    const { data: existingInvite } =
      await supabase
        .from("user_invites")
        .select("id")
        .eq("email", email)
        .eq("used", false)
        .maybeSingle();

    if (existingInvite) {
      setError(
        "Pro tento e-mail už existuje aktivní pozvánka."
      );
      setSaving(false);
      return;
    }

    const { data: existingProfile } =
      await supabase
        .from("profiles")
        .select("id")
        .eq("jmeno", name)
        .maybeSingle();

    if (existingProfile) {
      setError("Uživatel s tímto jménem už existuje.");
      setSaving(false);
      return;
    }

    const { error } = await supabase
      .from("user_invites")
      .insert({
        email,
        jmeno: name,
        role: getPrimaryRole(form.roles),
        roles: getAssignedRoles(form.roles),
        used: false,
      });

    if (error) {
      setError(error.message);
      setSaving(false);
      return;
    }

    setSuccess(`Pozvánka pro ${name} byla vytvořena.`);
    setForm(emptyForm);
    setShowForm(false);

    await loadInvites();

    setSaving(false);
  }

  async function changeRoles(id, roles) {
    setError("");
    setSuccess("");

    const next = getAssignedRoles(roles);
    setUsers((current) => current.map((item) => item.id === id
      ? { ...item, role: getPrimaryRole(next), roles: next }
      : item));

    const { error } = await supabase
      .from("profiles")
      .update({ role: getPrimaryRole(next), roles: next })
      .eq("id", id);

    if (error) {
      setError(error.message);
      await loadUsers();
      return;
    }

    setSuccess("Role uživatele byly změněny.");

    await loadUsers();
  }

  async function deleteInvite(id) {
    if (!window.confirm("Opravdu chceš tuto pozvánku zrušit?")) {
      return;
    }

    const { error } = await supabase
      .from("user_invites")
      .delete()
      .eq("id", id);

    if (error) {
      setError(error.message);
      return;
    }

    setSuccess("Pozvánka byla zrušena.");

    await loadInvites();
  }

  const filteredUsers = users.filter((user) => {
    return (
      filterRole === "Vše" ||
      hasRole(user, filterRole)
    );
  });

  const pendingInvites = invites.filter(
    (invite) => !invite.used
  );

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Správa uživatelů</h1>
          <p>Správa účtů a rolí</p>
        </div>

        <div className="profile-badge">POUZE ADMIN</div>
      </div>

      <div className="admin-user-stats">
        <div className="admin-user-stat">
          <span>Celkem uživatelů</span>
          <strong>{users.length}</strong>
        </div>

        <div className="admin-user-stat">
          <span>Administrátoři</span>
          <strong>
            {users.filter((u) => hasRole(u, ROLE_ADMIN)).length}
          </strong>
        </div>

        <div className="admin-user-stat">
          <span>Dispečeři</span>
          <strong>
            {users.filter((u) => hasRole(u, ROLE_DISPECER)).length}
          </strong>
        </div>

        <div className="admin-user-stat">
          <span>Řidiči</span>
          <strong>
            {users.filter((u) => hasRole(u, ROLE_RIDIC)).length}
          </strong>
        </div>
        <div className="admin-user-stat">
          <span>DKV Lichkov</span>
          <strong>{users.filter((u) => hasRole(u, ROLE_DKV)).length}</strong>
        </div>
        <div className="admin-user-stat">
          <span>DKV Lichkov admin</span>
          <strong>{users.filter((u) => hasRole(u, ROLE_DKV_ADMIN)).length}</strong>
        </div>
      </div>

      {error && (
        <div className="error-box">
          <strong>Chyba:</strong>
          <br />
          {error}
        </div>
      )}

      {success && <div className="success-box">{success}</div>}

      <div className="panel">
        <div className="users-toolbar">
          <div>
            <h2>Uživatelé</h2>
            <p className="muted">
              Registrovaní uživatelé systému.
            </p>
          </div>

          <button
            type="button"
            className="primary-button"
            onClick={() => setShowForm(!showForm)}
          >
            {showForm ? "✕ Zavřít" : "➕ Přidat uživatele"}
          </button>
        </div>

        {showForm && (
          <div className="user-create-box">
            <h3>➕ Přidat uživatele</h3>

            <form onSubmit={createInvite}>
              <div className="form-grid">
                <div>
                  <label>Jméno</label>

                  <input
                    value={form.jmeno}
                    onChange={(e) =>
                      setForm({
                        ...form,
                        jmeno: e.target.value,
                      })
                    }
                    required
                  />
                </div>

                <div>
                  <label>E-mail</label>

                  <input
                    type="email"
                    value={form.email}
                    onChange={(e) =>
                      setForm({
                        ...form,
                        email: e.target.value,
                      })
                    }
                    required
                  />
                </div>

                <RoleCheckboxes
                  label="Role (lze vybrat více)"
                  roles={form.roles}
                  onChange={(roles) => setForm({ ...form, roles })}
                />
              </div>

              <div className="form-buttons">
                <button
                  type="submit"
                  className="primary-button"
                  disabled={saving}
                >
                  {saving
                    ? "Vytváření..."
                    : "✓ Vytvořit pozvánku"}
                </button>
              </div>
            </form>
          </div>
        )}

        <div className="user-filter">
          <select
            value={filterRole}
            onChange={(e) => setFilterRole(e.target.value)}
          >
            <option value="Vše">Vše</option>
            <option value={ROLE_ADMIN}>Administrátoři</option>
            <option value={ROLE_DISPECER}>Dispečeři</option>
            <option value={ROLE_DKV}>DKV Lichkov</option>
            <option value={ROLE_DKV_ADMIN}>DKV Lichkov admin</option>
            <option value={ROLE_RIDIC}>Řidiči</option>
          </select>
        </div>

        {loading && (
          <div className="empty">Načítání uživatelů...</div>
        )}

        {!loading && filteredUsers.length === 0 && (
          <div className="empty">Žádní uživatelé.</div>
        )}

        {!loading && filteredUsers.length > 0 && (
          <div className="users-list">
            {filteredUsers.map((user) => (
              <div className="user-card" key={user.id}>
                <div className="user-card-avatar">
                  {(user.jmeno || "U")
                    .charAt(0)
                    .toUpperCase()}
                </div>

                <div className="user-card-main">
                  <strong>{user.jmeno || "Bez jména"}</strong>
                  <small>{user.id}</small>
                </div>

                <div>
                  <small>Role</small>
                  <strong>{getRoleName(user)}</strong>
                </div>

                <div>
                  <small>Vytvořeno</small>

                  <strong>
                    {user.created_at
                      ? new Date(
                          user.created_at
                        ).toLocaleDateString("cs-CZ")
                      : "-"}
                  </strong>
                </div>

                <RoleCheckboxes
                  label={`Upravit role: ${user.jmeno || "uživatel"}`}
                  roles={getAssignedRoles(user)}
                  onChange={(roles) => changeRoles(user.id, roles)}
                />
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="panel">
        <h2>Čekající registrace</h2>

        {pendingInvites.length === 0 ? (
          <div className="empty">
            Žádné čekající registrace.
          </div>
        ) : (
          <div className="users-list">
            {pendingInvites.map((invite) => (
              <div className="user-card" key={invite.id}>
                <div className="user-card-avatar pending-avatar">
                  {(invite.jmeno || "U")
                    .charAt(0)
                    .toUpperCase()}
                </div>

                <div className="user-card-main">
                  <strong>{invite.jmeno}</strong>
                  <small>{invite.email}</small>
                </div>

                <div>
                  <small>Role</small>
                  <strong>{getRoleName(invite)}</strong>
                </div>

                <span className="pending-label">
                  Čeká na registraci
                </span>

                <button
                  type="button"
                  className="delete-button"
                  onClick={() => deleteInvite(invite.id)}
                >
                  🗑️ Zrušit
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* =========================================================
   STAVY VOZŮ
========================================================= */

const vehicleStatusColors = {
  "PROVOZNÍ": "#caffca",
  "V DÍLNĚ / V OPRAVĚ": "#ffca97",
  "DOČASNĚ ODSTAVEN": "#eaeaea",
  "DEFINITIVNĚ ODSTAVEN": "#cacaca",
  "DLOUHODOBĚ ODSTAVEN": "#cacaca",
  "SEŠROTOVÁN": "#ffcaca",
  "PRODÁN / PŘEDÁN JINÉMU DOPRAVCI": "#ffcaff",
  "DOSUD NEZAŘAZEN DO PROVOZU": "#cacaff",
  "SLUŽEBNÍ": "#ffffca",
  "RETRO": "#caffff",
};

function VehicleStatus({ status }) {
  const color =
    vehicleStatusColors[status] || "#eaeaea";

  return (
    <span
      className="status vehicle-status"
      style={{
        background: color,
        color: "#172033",
      }}
    >
      {status || "-"}
    </span>
  );
}

// Značky bereme přímo z databázového sloupce vyrobce.
// Sjednotíme rozdíly ve velikosti písmen a nadbytečných mezerách.
const vehicleSortCollator = new Intl.Collator("cs", {
  sensitivity: "base",
  numeric: true,
});

function normalizeVehicleBrand(value) {
  return String(value ?? "").trim().replace(/\s+/g, " ");
}

function getVehicleBrandOptions(vehicles) {
  const brands = [];

  for (const vehicle of vehicles) {
    const brand = normalizeVehicleBrand(vehicle.vyrobce);
    if (!brand) continue;

    const existing = brands.find(
      (item) => vehicleSortCollator.compare(item.value, brand) === 0
    );

    if (existing) existing.count += 1;
    else brands.push({ value: brand, count: 1 });
  }

  return brands.sort((a, b) => vehicleSortCollator.compare(a.value, b.value));
}

function compareVehicleNumbers(a, b, direction = 1) {
  const aNumber = a.cislo == null || a.cislo === "" ? NaN : Number(a.cislo);
  const bNumber = b.cislo == null || b.cislo === "" ? NaN : Number(b.cislo);
  if (!Number.isFinite(aNumber)) return Number.isFinite(bNumber) ? 1 : 0;
  if (!Number.isFinite(bNumber)) return -1;
  return direction * (aNumber - bNumber);
}

function compareVehicleText(a, b, direction = 1) {
  const left = normalizeVehicleBrand(a);
  const right = normalizeVehicleBrand(b);
  // Nevyplněné údaje patří vždy na konec, i při řazení Z–A.
  if (!left) return right ? 1 : 0;
  if (!right) return -1;
  return direction * vehicleSortCollator.compare(left, right);
}

function sortVehicleList(vehicles, sortBy) {
  return [...vehicles].sort((a, b) => {
    if (sortBy === "brand_asc" || sortBy === "brand_desc") {
      const direction = sortBy === "brand_asc" ? 1 : -1;
      return (
        compareVehicleText(a.vyrobce, b.vyrobce, direction) ||
        compareVehicleText(a.typ, b.typ) ||
        compareVehicleNumbers(a, b)
      );
    }

    return compareVehicleNumbers(a, b, sortBy === "number_desc" ? -1 : 1);
  });
}

function VehicleBrandSorting({ idPrefix, brands, selectedBrand, onBrandChange, sortBy, onSortChange }) {
  return (
    <div className="provozovna-bar vehicle-list-controls">
      <div>
        <label htmlFor={`${idPrefix}-brand`}>Značka vozu</label>
        <select id={`${idPrefix}-brand`} value={selectedBrand} onChange={(event) => onBrandChange(event.target.value)}>
          <option value="">Všechny značky</option>
          {brands.map((brand) => (
            <option key={brand.value} value={brand.value}>
              {brand.value} ({brand.count})
            </option>
          ))}
        </select>
      </div>
      <div>
        <label htmlFor={`${idPrefix}-sort`}>Seřadit vozy podle</label>
        <select id={`${idPrefix}-sort`} value={sortBy} onChange={(event) => onSortChange(event.target.value)}>
          <option value="number_asc">Čísla vozu (vzestupně)</option>
          <option value="number_desc">Čísla vozu (sestupně)</option>
          <option value="brand_asc">Značky (A–Z), pak typu</option>
          <option value="brand_desc">Značky (Z–A), pak typu</option>
        </select>
      </div>
    </div>
  );
}

/* =========================================================
   VOZIDLO - FORMULÁŘ
========================================================= */

const emptyVehicle = {
  cislo: "",
  vyrobce: "",
  typ: "",
  spz: "",
  rok: "",
  stk: "",
  barevne_schema: "",
  stav: "PROVOZNÍ",
  provozovna_id: "",
};

function VehicleForm({
  initialData,
  onSave,
  onCancel,
  saving,
  provozovny,
}) {
  const [form, setForm] = useState(
    initialData || emptyVehicle
  );

  useEffect(() => {
    setForm(initialData || emptyVehicle);
  }, [initialData]);

  function change(name, value) {
    setForm((old) => ({
      ...old,
      [name]: value,
    }));
  }

  function submit(e) {
    e.preventDefault();
    onSave(form);
  }

  return (
    <div className="crud-form">
      <h3>
        {initialData ? "✏️ Upravit vůz" : "➕ Přidat vůz"}
      </h3>

      <form onSubmit={submit}>
        <div className="form-grid">
          <div>
            <label>Číslo vozu</label>

            <input
              type="number"
              value={form.cislo}
              onChange={(e) => change("cislo", e.target.value)}
              required
            />
          </div>

          <div>
            <label>Výrobce</label>

            <input
              value={form.vyrobce}
              onChange={(e) =>
                change("vyrobce", e.target.value)
              }
              required
            />
          </div>

          <div>
            <label>Typ</label>

            <input
              value={form.typ}
              onChange={(e) => change("typ", e.target.value)}
              required
            />
          </div>

          <div>
            <label>SPZ</label>

            <input
              value={form.spz}
              onChange={(e) => change("spz", e.target.value)}
            />
          </div>

          <div>
            <label>Rok</label>

            <input
              type="number"
              value={form.rok}
              onChange={(e) => change("rok", e.target.value)}
            />
          </div>

          <div>
            <label>STK – platnost do</label>

            <input
              type="date"
              value={form.stk || ""}
              onChange={(e) => change("stk", e.target.value)}
            />
          </div>

          <div>
            <label>Barevné schéma</label>

            <input
              value={form.barevne_schema}
              onChange={(e) =>
                change(
                  "barevne_schema",
                  e.target.value
                )
              }
            />
          </div>

          <div>
            <label>Stav</label>

            <select
              value={form.stav}
              onChange={(e) => change("stav", e.target.value)}
            >
              <option>PROVOZNÍ</option>
              <option>V DÍLNĚ / V OPRAVĚ</option>
              <option>DOČASNĚ ODSTAVEN</option>
              <option>DLOUHODOBĚ ODSTAVEN</option>
              <option>SEŠROTOVÁN</option>
              <option>
                PRODÁN / PŘEDÁN JINÉMU DOPRAVCI
              </option>
              <option>
                DOSUD NEZAŘAZEN DO PROVOZU
              </option>
              <option>SLUŽEBNÍ</option>
              <option>RETRO</option>
            </select>
          </div>

          <ProvozovnaSelect
            value={form.provozovna_id}
            onChange={(value) =>
              change("provozovna_id", value)
            }
            provozovny={provozovny}
            required
          />
        </div>

        <div className="form-buttons">
          <button
            type="submit"
            className="primary-button"
            disabled={saving}
          >
            {saving ? "Ukládání..." : "✓ Uložit"}
          </button>

          <button
            type="button"
            className="secondary-button"
            onClick={onCancel}
          >
            Zrušit
          </button>
        </div>
      </form>
    </div>
  );
}

/* =========================================================
   ADMINISTRACE VOZŮ
========================================================= */

function AdminVehicles() {
  const [vehicles, setVehicles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);

  const [search, setSearch] = useState("");
  const [selectedProvozovna, setSelectedProvozovna] =
    useState("");
  const [selectedBrand, setSelectedBrand] = useState("");
  const [sortBy, setSortBy] = useState("number_asc");

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const { provozovny } = useProvozovny();

  async function loadVehicles() {
    setLoading(true);

    const { data, error } = await supabase
      .from("vozy")
      .select("*")
      .order("cislo", { ascending: true });

    if (error) {
      setError(error.message);
      setVehicles([]);
    } else {
      setVehicles(data || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadVehicles();
  }, []);

  function getProvozovnaName(id) {
    return (
      provozovny.find((p) => Number(p.id) === Number(id))
        ?.nazev || "-"
    );
  }

  async function saveVehicle(form) {
    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      cislo:
        form.cislo === ""
          ? null
          : Number(form.cislo),

      vyrobce: form.vyrobce.trim(),
      typ: form.typ.trim(),
      spz: form.spz.trim() || null,

      rok:
        form.rok === ""
          ? null
          : Number(form.rok),

      stk: form.stk || null,

      barevne_schema:
        form.barevne_schema.trim() || null,

      stav: form.stav || null,

      provozovna_id:
        form.provozovna_id === ""
          ? null
          : Number(form.provozovna_id),
    };

    let result;

    if (editing) {
      result = await supabase
        .from("vozy")
        .update(payload)
        .eq("id", editing.id);
    } else {
      result = await supabase
        .from("vozy")
        .insert(payload);
    }

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editing ? "Vůz byl upraven." : "Vůz byl přidán."
    );

    setShowForm(false);
    setEditing(null);

    await loadVehicles();

    setSaving(false);
  }

  async function deleteVehicle(vehicle) {
    if (
      !window.confirm(
        `Opravdu chceš smazat vůz č. ${vehicle.cislo}?`
      )
    ) {
      return;
    }

    const { error } = await supabase
      .from("vozy")
      .delete()
      .eq("id", vehicle.id);

    if (error) {
      setError(error.message);
      return;
    }

    setSuccess("Vůz byl smazán.");

    await loadVehicles();
  }

  const vehiclesInProvozovna = vehicles.filter(
    (vehicle) =>
      !selectedProvozovna ||
      Number(vehicle.provozovna_id) === Number(selectedProvozovna)
  );
  const brands = getVehicleBrandOptions(vehiclesInProvozovna);

  const filtered = sortVehicleList(vehiclesInProvozovna.filter((vehicle) => {
    if (
      selectedBrand &&
      vehicleSortCollator.compare(normalizeVehicleBrand(vehicle.vyrobce), selectedBrand) !== 0
    ) {
      return false;
    }

    const text = [
      vehicle.cislo,
      vehicle.vyrobce,
      vehicle.typ,
      vehicle.spz,
      vehicle.rok,
      vehicle.barevne_schema,
      vehicle.stav,
      getProvozovnaName(vehicle.provozovna_id),
    ]
      .filter(
        (x) =>
          x !== null &&
          x !== undefined
      )
      .join(" ")
      .toLowerCase();

    return text.includes(search.trim().toLowerCase());
  }), sortBy);

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Administrace vozů</h1>
          <p>Přidávání, úprava a mazání vozů</p>
        </div>

        <div className="profile-badge">
          {filtered.length} VOZŮ
        </div>
      </div>

      {error && (
        <div className="error-box">
          <strong>Chyba:</strong>
          <br />
          {error}
        </div>
      )}

      {success && (
        <div className="success-box">
          {success}
        </div>
      )}

      <div className="panel">
        <div className="provozovna-bar">
          <ProvozovnaSelect
            value={selectedProvozovna}
            onChange={(value) => {
              setSelectedProvozovna(value);
              setSelectedBrand("");
            }}
            provozovny={provozovny}
            label="Zobrazit provozovnu"
          />

          <button
            className="secondary-button"
            type="button"
            onClick={() => {
              setSelectedProvozovna("");
              setSelectedBrand("");
            }}
          >
            Všechny provozovny
          </button>
        </div>

        <VehicleBrandSorting
          idPrefix="admin-vehicles"
          brands={brands}
          selectedBrand={selectedBrand}
          onBrandChange={setSelectedBrand}
          sortBy={sortBy}
          onSortChange={setSortBy}
        />

        <div className="users-toolbar">
          <div>
            <h2>Vozový park</h2>
            <p className="muted">
              Správa vozidel Czech Mobility.
            </p>
          </div>

          <button
            type="button"
            className="primary-button"
            onClick={() => {
              setEditing(null);
              setShowForm(!showForm);
            }}
          >
            {showForm ? "✕ Zavřít" : "➕ Přidat vůz"}
          </button>
        </div>

        {showForm && (
          <VehicleForm
            initialData={editing}
            onSave={saveVehicle}
            onCancel={() => {
              setShowForm(false);
              setEditing(null);
            }}
            saving={saving}
            provozovny={provozovny}
          />
        )}

        <input
          className="search"
          type="text"
          placeholder="🔎 Hledat vůz..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        {loading && (
          <div className="empty">Načítání vozů...</div>
        )}

        {!loading && filtered.length === 0 && (
          <div className="empty">Žádné vozy.</div>
        )}

        {!loading && filtered.length > 0 && (
          <div className="admin-vehicles-list">
            {filtered.map((vehicle) => (
              <div
                className="admin-vehicle-card"
                key={vehicle.id}
              >
                <div className="vehicle-number">
                  {vehicle.cislo}
                </div>

                <div className="vehicle-main">
                  <strong>
                    {vehicle.vyrobce} {vehicle.typ}
                  </strong>

                  <small>
                    SPZ: {vehicle.spz || "-"} • Rok:{" "}
                    {vehicle.rok || "-"}
                  </small>

                  <small>
                    Provozovna:{" "}
                    {getProvozovnaName(
                      vehicle.provozovna_id
                    )}
                  </small>

                  <small>
                    Schéma:{" "}
                    {vehicle.barevne_schema || "-"}
                  </small>

                  <small>
                    STK do:{" "}
                    {vehicle.stk
                      ? formatStkForDisplay(vehicle.stk)
                      : "-"}
                  </small>
                </div>

                <VehicleStatus status={vehicle.stav} />

                <div className="vehicle-actions">
                  <button
                    className="secondary-button"
                    type="button"
                    onClick={() => {
                      setEditing({
                        ...vehicle,
                        cislo:
                          vehicle.cislo ?? "",
                        rok:
                          vehicle.rok ?? "",
                        stk: normalizeStkForInput(vehicle.stk),
                        provozovna_id:
                          vehicle.provozovna_id ?? "",
                        spz: vehicle.spz || "",
                        barevne_schema:
                          vehicle.barevne_schema || "",
                      });

                      setShowForm(true);
                    }}
                  >
                    ✏️ Upravit
                  </button>

                  <button
                    className="delete-button"
                    type="button"
                    onClick={() =>
                      deleteVehicle(vehicle)
                    }
                  >
                    🗑️ Smazat
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* =========================================================
   DETAIL VOZU
========================================================= */

const vehicleDetailFields = [
  ["vyrobce", "Výrobce"],
  ["typ", "Typ"],
  ["spz", "SPZ"],
  ["rok", "Rok výroby"],
  ["stav", "Stav"],
  ["barevne_schema", "Nátěr"],
  ["reklamy", "Reklamy"],
  ["vybaveni", "Vybavení"],
  ["prevodovka", "Převodovka"],
  ["rozlozeni_dveri", "Rozložení dveří"],
  ["stk", "STK"],
  ["palubni_deska", "Palubní deska"],
  ["informacni_system", "Informační systém"],
  ["ridic_1", "Řidič 1"],
  ["ridic_2", "Řidič 2"],
];

function normalizeStkForInput(value) {
  if (!value) return "";

  const raw = String(value).trim();

  // PostgreSQL date -> HTML input[type=date]
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    return raw;
  }

  // Legacy MM/YYYY -> first day of month, until user sets exact day.
  const monthYear = raw.match(/^(0?[1-9]|1[0-2])\/(\d{4})$/);
  if (monthYear) {
    return `${monthYear[2]}-${String(monthYear[1]).padStart(2, "0")}-01`;
  }

  // Legacy DD.MM.YYYY
  const czDate = raw.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (czDate) {
    return `${czDate[3]}-${String(czDate[2]).padStart(2, "0")}-${String(
      czDate[1]
    ).padStart(2, "0")}`;
  }

  return "";
}

function formatStkForDisplay(value) {
  if (!value) return "";

  const normalized = normalizeStkForInput(value);
  const iso = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);

  if (iso) {
    return `${iso[3]}.${iso[2]}.${iso[1]}`;
  }

  return String(value);
}

function stkInputToDate(value) {
  if (!value) return null;

  const normalized = normalizeStkForInput(value);

  if (/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
    return normalized;
  }

  return null;
}

function localDateIso(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getStkStatus(value) {
  const normalized = normalizeStkForInput(value);
  if (!normalized) return null;

  const target = new Date(`${normalized}T00:00:00`);
  if (Number.isNaN(target.getTime())) return null;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const diffDays = Math.ceil(
    (target.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)
  );

  if (diffDays < 0) {
    return {
      type: "expired",
      text: `STK propadla před ${Math.abs(diffDays)} dny`,
    };
  }

  if (diffDays === 0) {
    return { type: "soon", text: "STK končí dnes" };
  }

  if (diffDays <= 30) {
    return {
      type: "soon",
      text: `STK končí za ${diffDays} dní`,
    };
  }

  return { type: "ok", text: `STK platí ještě ${diffDays} dní` };
}


function vehicleDraftKey(vehicleId) {
  return `cm-vehicle-edit-draft-${vehicleId}`;
}

function readVehicleDraft(vehicleId) {
  if (typeof window === "undefined" || !vehicleId) return null;

  try {
    const raw = window.localStorage.getItem(vehicleDraftKey(vehicleId));
    if (!raw) return null;

    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch (error) {
    console.warn("VEHICLE DRAFT READ ERROR:", error);
    return null;
  }
}

function clearVehicleDraft(vehicleId) {
  if (typeof window === "undefined" || !vehicleId) return;

  try {
    window.localStorage.removeItem(vehicleDraftKey(vehicleId));
  } catch (error) {
    console.warn("VEHICLE DRAFT CLEAR ERROR:", error);
  }
}

function VehicleDetail({ vehicle, role, onBack, onSaved }) {
  const editable = canManageVehicles(role);
  const initialDraft = readVehicleDraft(vehicle.id);

  const [editing, setEditing] = useState(
    Boolean(initialDraft?.form)
  );
  const [form, setForm] = useState(() => ({
    ...vehicle,
    ...(initialDraft?.form || {}),
    stk: normalizeStkForInput(
      initialDraft?.form?.stk ?? vehicle.stk
    ),
  }));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [history, setHistory] = useState([]);

  useEffect(() => {
    const draft = readVehicleDraft(vehicle.id);

    if (draft?.form) {
      setForm({
        ...vehicle,
        ...draft.form,
        stk: normalizeStkForInput(
          draft.form.stk ?? vehicle.stk
        ),
      });
      setEditing(true);
    } else {
      setForm({
        ...vehicle,
        stk: normalizeStkForInput(vehicle.stk),
      });
      setEditing(false);
    }

    setError("");
    setSuccess("");
  }, [vehicle.id]);

  useEffect(() => {
    if (!editing || !vehicle.id || typeof window === "undefined") {
      return;
    }

    try {
      window.localStorage.setItem(
        vehicleDraftKey(vehicle.id),
        JSON.stringify({
          form,
          updated_at: new Date().toISOString(),
        })
      );
    } catch (draftError) {
      console.warn("VEHICLE DRAFT SAVE ERROR:", draftError);
    }
  }, [editing, form, vehicle.id]);

  useEffect(() => {
    supabase.from("vehicle_history")
      .select("id, typ, popis, created_at")
      .eq("vuz_id", vehicle.id)
      .order("created_at", { ascending: false })
      .limit(30)
      .then(({ data }) => setHistory(data || []));
  }, [vehicle.id]);

  function change(name, value) {
    setForm((old) => ({
      ...old,
      [name]: value,
    }));
  }

  function startEditing() {
    setError("");
    setSuccess("");
    setEditing(true);
  }

  function cancelEditing() {
    clearVehicleDraft(vehicle.id);
    setForm({
      ...vehicle,
      stk: normalizeStkForInput(vehicle.stk),
    });
    setEditing(false);
    setError("");
    setSuccess("");
  }

 async function save() {
  setSaving(true);
  setError("");
  setSuccess("");

  const payload = {};

  vehicleDetailFields.forEach(([field]) => {
    let value = form[field];

    if (field === "rok") {
      value =
        value === "" || value == null
          ? null
          : Number(value);
    } else if (field === "stk") {
      value = stkInputToDate(value);
    } else if (value === "") {
      value = null;
    }

    payload[field] = value;
  });

  const { data, error: saveError } = await supabase
    .from("vozy")
    .update(payload)
    .eq("id", vehicle.id)
    .select("*")
    .single();

  if (saveError) {
    console.error("Chyba při ukládání vozu:", saveError);
    setError(saveError.message);
    setSaving(false);
    return;
  }

  const updatedVehicle = {
    ...data,
    stk: normalizeStkForInput(data?.stk),
  };

  clearVehicleDraft(vehicle.id);
  setForm(updatedVehicle);
  setEditing(false);
  setSuccess("Údaje vozu byly uloženy.");
  setSaving(false);

  if (onSaved) {
    onSaved(updatedVehicle);
  }
}

  return (
    <div>
      <div className="topbar">
        <div>
          <button
            type="button"
            className="secondary-button"
            onClick={onBack}
            style={{ marginBottom: 12 }}
          >
            ← Zpět na vozy
          </button>

          <h1>Vůz {vehicle.cislo ?? "-"}</h1>

          <p>
            {vehicle.vyrobce || "-"}{" "}
            {vehicle.typ || ""}
          </p>
        </div>

        {editable && (
          <div style={{ display: "flex", gap: 10 }}>
            <button
              type="button"
              className="primary-button"
              onClick={editing ? cancelEditing : startEditing}
              disabled={saving}
            >
              {editing ? "Zrušit úpravy" : "✏️ Upravit vůz"}
            </button>

            {editing && (
              <button
                type="button"
                className="primary-button"
                onClick={save}
                disabled={saving}
              >
                {saving ? "Ukládám..." : "💾 Uložit"}
              </button>
            )}
          </div>
        )}
      </div>

      {error && (
        <div className="error-box" style={{ marginBottom: 16 }}>
          <strong>Chyba:</strong>
          <br />
          {error}
        </div>
      )}

      {success && (
        <div className="success-box" style={{ marginBottom: 16 }}>
          {success}
        </div>
      )}

      {editing && (
        <div className="vehicle-draft-info">
          <span>●</span>
          Rozepsané změny se průběžně ukládají v tomto prohlížeči.
          Přepnutí záložky je nesmaže.
        </div>
      )}

      <div className="panel">
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
            gap: 16,
          }}
        >
          {vehicleDetailFields.map(([field, label]) => (
            <div
              key={field}
              className="vehicle-detail-field-card"
              style={{
                padding: 16,
                border: "1px solid #e5e7eb",
                borderRadius: 12,
                background: "#fff",
              }}
            >
              <div
                className="vehicle-detail-field-label"
                style={{
                  fontSize: 12,
                  fontWeight: 700,
                  color: "#6b7280",
                  marginBottom: 7,
                }}
              >
                {label}
              </div>

              {editing && editable ? (
                field === "stav" ? (
                  <select
                    className="form-input"
                    value={form[field] ?? ""}
                    onChange={(e) => change(field, e.target.value)}
                  >
                    <option value="">—</option>
                    {Object.keys(vehicleStatusColors).map((status) => (
                      <option key={status} value={status}>
                        {status}
                      </option>
                    ))}
                  </select>
                ) : (
                  <>
                    <input
                      className="form-input"
                      type={
                        field === "stk"
                          ? "date"
                          : field === "rok"
                          ? "number"
                          : "text"
                      }
                      value={form[field] ?? ""}
                      onChange={(e) => change(field, e.target.value)}
                      placeholder={label}
                    />
                  </>
                )
              ) : (
                <>
                  <div style={{ fontWeight: 600 }}>
                    {form[field] === null ||
                    form[field] === undefined ||
                    form[field] === ""
                      ? "—"
                      : field === "stk"
                      ? formatStkForDisplay(form[field])
                      : String(form[field])}
                  </div>

                  {field === "stk" &&
                    form[field] &&
                    getStkStatus(form[field]) && (
                      <div
                        className={`stk-status-note ${getStkStatus(form[field]).type}`}
                      >
                        {getStkStatus(form[field]).text}
                      </div>
                    )}
                </>
              )}
            </div>
          ))}
        </div>

        <div className="vehicle-extra-panel">
          <h2>Historie vozu</h2>
          {history.length === 0 ? <div className="empty">Zatím bez historie.</div> : (
            <div className="simple-list">{history.map((item) => (
              <div className="simple-list-item" key={item.id}>
                <div><strong>{item.typ}</strong><div>{item.popis}</div></div>
                <small>{item.created_at ? new Date(item.created_at).toLocaleString("cs-CZ") : "-"}</small>
              </div>
            ))}</div>
          )}
        </div>

        <div
          className="vehicle-detail-note"
          style={{
            marginTop: 18,
            padding: 14,
            borderRadius: 10,
            background: "#f8fafc",
            color: "#64748b",
            fontSize: 13,
          }}
        >
          Detail je společný pro všechny vozy. Kliknutím na jiný vůz
          se vždy načtou údaje právě toho konkrétního záznamu z tabulky
          <strong> vozy</strong>.
        </div>
      </div>
    </div>
  );
}

/* =========================================================
   VEŘEJNÝ SEZNAM VOZŮ
========================================================= */

function Vehicles({ role, initialVehicleId = null, onVehicleOpened }) {
  const [vehicles, setVehicles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");
  const [selectedProvozovna, setSelectedProvozovna] =
    useState("");
  const [selectedBrand, setSelectedBrand] = useState("");
  const [sortBy, setSortBy] = useState("number_asc");
  const [selectedVehicleId, setSelectedVehicleId] =
    useState(null);

  const { provozovny } = useProvozovny();

  async function loadVehicles() {
    setLoading(true);
    setError("");

    // Načítáme celý záznam vozu, aby detailní údaje
    // (reklamy, vybavení, dveře, STK atd.) zůstaly dostupné i po refreshi.
    const { data, error } = await supabase
      .from("vozy")
      .select("*")
      .order("cislo", { ascending: true });

    if (error) {
      console.error("VOZY ERROR:", error);
      setError(error.message || "Nepodařilo se načíst vozy.");
      setVehicles([]);
    } else {
      setVehicles(Array.isArray(data) ? data : []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadVehicles();
  }, []);

  useEffect(() => {
    if (!initialVehicleId) return;

    setSelectedVehicleId(initialVehicleId);

    if (onVehicleOpened) {
      onVehicleOpened();
    }
  }, [initialVehicleId]);

  const selectedVehicle = vehicles.find(
    (vehicle) => String(vehicle.id) === String(selectedVehicleId)
  );

  if (selectedVehicle) {
    return (
      <VehicleDetail
        vehicle={selectedVehicle}
        role={role}
        onBack={() => setSelectedVehicleId(null)}
        onSaved={(updated) => {
          setVehicles((old) =>
            old.map((vehicle) =>
              vehicle.id === updated.id ? updated : vehicle
            )
          );
        }}
      />
    );
  }

  const query = search.trim().toLowerCase();

  const vehiclesInProvozovna = vehicles.filter(
    (vehicle) =>
      !selectedProvozovna ||
      Number(vehicle.provozovna_id) === Number(selectedProvozovna)
  );
  const brands = getVehicleBrandOptions(vehiclesInProvozovna);

  const filtered = sortVehicleList(vehiclesInProvozovna.filter((vehicle) => {
    if (
      selectedBrand &&
      vehicleSortCollator.compare(normalizeVehicleBrand(vehicle.vyrobce), selectedBrand) !== 0
    ) {
      return false;
    }

    if (!query) return true;

    const text = [
      vehicle.cislo,
      vehicle.vyrobce,
      vehicle.typ,
      vehicle.spz,
      vehicle.rok,
      vehicle.barevne_schema,
      vehicle.stav,
    ]
      .filter((value) => value !== null && value !== undefined)
      .join(" ")
      .toLowerCase();

    return text.includes(query);
  }), sortBy);

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Vozy</h1>
          <p>Vozový park Czech Mobility</p>
        </div>

        <div className="profile-badge">
          {filtered.length} VOZŮ
        </div>
      </div>

      <div className="panel">
        <div className="provozovna-bar">
          <ProvozovnaSelect
            value={selectedProvozovna}
            onChange={(value) => {
              setSelectedProvozovna(value);
              setSelectedBrand("");
            }}
            provozovny={provozovny}
            label="Provozovna"
          />

          <button
            className="secondary-button"
            type="button"
            onClick={() => {
              setSelectedProvozovna("");
              setSelectedBrand("");
            }}
          >
            Všechny provozovny
          </button>
        </div>

        <VehicleBrandSorting
          idPrefix="vehicles"
          brands={brands}
          selectedBrand={selectedBrand}
          onBrandChange={setSelectedBrand}
          sortBy={sortBy}
          onSortChange={setSortBy}
        />

        <input
          className="search"
          type="text"
          placeholder="🔎 Hledat vůz..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        {loading && (
          <div className="empty">Načítání vozů...</div>
        )}

        {!loading && error && (
          <div className="error-box">
            <strong>Chyba při načítání vozů:</strong>
            <br />
            {error}
            <br /><br />
            <button
              type="button"
              className="secondary-button"
              onClick={loadVehicles}
            >
              Zkusit znovu
            </button>
          </div>
        )}

        {!loading && !error && filtered.length > 0 && (
          <>
            <div className="vehicle-header">
              <span>Číslo</span>
              <span>Výrobce</span>
              <span>Typ</span>
              <span>SPZ</span>
              <span>Rok</span>
              <span>Stav</span>
            </div>

            {filtered.map((vehicle) => (
              <div
                key={vehicle.id}
                className="vehicle-row vehicle-row-clickable"
                role="button"
                tabIndex={0}
                onClick={() => setSelectedVehicleId(vehicle.id)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setSelectedVehicleId(vehicle.id);
                  }
                }}
                title={`Otevřít detail vozu ${vehicle.cislo ?? "-"}`}
              >
                <strong>{vehicle.cislo ?? "-"}</strong>
                <span>{vehicle.vyrobce ?? "-"}</span>
                <span>{vehicle.typ ?? "-"}</span>
                <span>{vehicle.spz ?? "-"}</span>
                <span>{vehicle.rok ?? "-"}</span>
                <span>
                  <VehicleStatus status={vehicle.stav} />
                </span>
              </div>
            ))}
          </>
        )}

        {!loading && !error && filtered.length === 0 && (
          <div className="empty">
            {vehicles.length === 0
              ? "Tabulka vozy neobsahuje žádné záznamy."
              : "Žádné vozy neodpovídají hledání."}
          </div>
        )}
      </div>
    </div>
  );
}

/* =========================================================
   VÝKAZY
========================================================= */

const emptyReport = {
  uzivatel_id: "",
  provozovna_id: "",
  datum: "",
  linka: "",
  smer: "",
  vuz: "",
  zacatek: "",
  konec: "",
};

/* =========================================================
   FORMULÁŘ VÝKAZU
========================================================= */

function ReportForm({
  initialData,
  users,
  currentUserId,
  onSave,
  onCancel,
  saving,
  adminMode,
  provozovny,
}) {
  const [form, setForm] = useState(
    initialData || {
      ...emptyReport,
      uzivatel_id: currentUserId,
    }
  );

  const [vozy, setVozy] = useState([]);

  useEffect(() => {
    setForm(
      initialData || {
        ...emptyReport,
        uzivatel_id: currentUserId,
      }
    );
  }, [initialData, currentUserId]);

  useEffect(() => {
    async function loadVozy() {
      if (!form.provozovna_id) {
        setVozy([]);
        return;
      }

      const { data, error } = await supabase
        .from("vozy")
        .select(
          "id, cislo, vyrobce, typ, spz"
        )
        .eq(
          "provozovna_id",
          Number(form.provozovna_id)
        )
        .order("cislo", {
          ascending: true,
        });

      if (error) {
        console.error(error);
        setVozy([]);
      } else {
        setVozy(data || []);
      }
    }

    loadVozy();
  }, [form.provozovna_id]);

  function change(name, value) {
    setForm((old) => {
      const next = {
        ...old,
        [name]: value,
      };

      if (name === "provozovna_id") {
        next.vuz = "";
      }

      return next;
    });
  }

  function submit(e) {
    e.preventDefault();

    if (!form.provozovna_id) {
      alert("Vyber provozovnu.");
      return;
    }

    if (!form.vuz) {
      alert("Vyber vůz.");
      return;
    }

    onSave(form);
  }

  return (
    <div className="crud-form">
      <h3>
        {initialData
          ? "✏️ Upravit výkaz"
          : "➕ Přidat výkaz"}
      </h3>

      <form onSubmit={submit}>
        <div className="form-grid">
          {adminMode && (
            <div>
              <label>Řidič</label>

              <select
                value={form.uzivatel_id}
                onChange={(e) =>
                  change(
                    "uzivatel_id",
                    e.target.value
                  )
                }
                required
              >
                <option value="">
                  Vyber řidiče
                </option>

                {users.map((user) => (
                  <option
                    key={user.id}
                    value={user.id}
                  >
                    {user.jmeno || user.id} —{" "}
                    {getRoleName(user)}
                  </option>
                ))}
              </select>
            </div>
          )}

          <ProvozovnaSelect
            value={form.provozovna_id}
            onChange={(value) =>
              change("provozovna_id", value)
            }
            provozovny={provozovny}
            required
          />

          <div>
            <label>Vůz</label>

            <select
              value={form.vuz || ""}
              onChange={(e) =>
                change("vuz", e.target.value)
              }
              disabled={!form.provozovna_id}
              required
            >
              <option value="">
                {!form.provozovna_id
                  ? "Nejdříve vyber provozovnu"
                  : "Vyber vůz"}
              </option>

              {vozy.map((vehicle) => (
                <option
                  key={vehicle.id}
                  value={String(vehicle.cislo)}
                >
                  {vehicle.cislo} –{" "}
                  {vehicle.vyrobce}{" "}
                  {vehicle.typ}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label>Datum</label>

            <input
              type="date"
              value={form.datum || ""}
              onChange={(e) =>
                change("datum", e.target.value)
              }
              required
            />
          </div>

          <div>
            <label>Linka</label>

            <input
              value={form.linka || ""}
              onChange={(e) =>
                change("linka", e.target.value)
              }
              placeholder="Např. 12"
              required
            />
          </div>

          <div>
            <label>Směr</label>

            <input
              value={form.smer || ""}
              onChange={(e) =>
                change("smer", e.target.value)
              }
              placeholder="Např. Terminál → Břeclavsko"
              required
            />
          </div>

          <div>
            <label>Začátek</label>

            <input
              type="time"
              value={form.zacatek || ""}
              onChange={(e) =>
                change("zacatek", e.target.value)
              }
              required
            />
          </div>

          <div>
            <label>Konec</label>

            <input
              type="time"
              value={form.konec || ""}
              onChange={(e) =>
                change("konec", e.target.value)
              }
              required
            />
          </div>
        </div>

        <div className="form-buttons">
          <button
            type="submit"
            className="primary-button"
            disabled={saving}
          >
            {saving ? "Ukládání..." : "✓ Uložit výkaz"}
          </button>

          <button
            type="button"
            className="secondary-button"
            onClick={onCancel}
          >
            Zrušit
          </button>
        </div>
      </form>
    </div>
  );
}

/* =========================================================
   KARTA VÝKAZU
========================================================= */

function ReportCard({
  report,
  userName,
  provozovnaName,
  onEdit,
  onDelete,
}) {
  return (
    <div className="report-card">
      <div className="report-date">
        <strong>
          {report.datum
            ? new Date(
                `${report.datum}T00:00:00`
              ).toLocaleDateString("cs-CZ")
            : "-"}
        </strong>

        {userName && <small>{userName}</small>}
      </div>

      <div>
        <small>Provozovna</small>
        <strong>{provozovnaName || "-"}</strong>
      </div>

      <div>
        <small>Linka</small>
        <strong>{report.linka || "-"}</strong>
      </div>

      <div>
        <small>Vůz</small>
        <strong>{report.vuz || "-"}</strong>
      </div>

      <div>
        <small>Čas</small>
        <strong>
          {report.zacatek || "-"} –{" "}
          {report.konec || "-"}
        </strong>
      </div>

      {(onEdit || onDelete) && (
        <div className="report-actions">
          {onEdit && (
            <button
              className="secondary-button"
              type="button"
              onClick={onEdit}
            >
              ✏️
            </button>
          )}

          {onDelete && (
            <button
              className="delete-button"
              type="button"
              onClick={onDelete}
            >
              🗑️
            </button>
          )}
        </div>
      )}
    </div>
  );
}

/* =========================================================
   MOJE VÝKAZY
========================================================= */

function MyReports({ user }) {
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);

  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [saving, setSaving] = useState(false);

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const { provozovny } = useProvozovny();

  async function loadReports() {
    setLoading(true);

    const { data, error } = await supabase
      .from("vykazy")
      .select(
        "id, uzivatel_id, provozovna_id, datum, linka, smer, vuz, zacatek, konec"
      )
      .eq("uzivatel_id", user.id)
      .order("datum", { ascending: false })
      .order("zacatek", { ascending: false });

    if (error) {
      setError(error.message);
      setReports([]);
    } else {
      setReports(data || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadReports();
  }, [user.id]);

  function getProvozovnaName(id) {
    return (
      provozovny.find(
        (p) => Number(p.id) === Number(id)
      )?.nazev || "-"
    );
  }

  async function saveReport(form) {
    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      uzivatel_id: user.id,
      provozovna_id: Number(form.provozovna_id),
      datum: form.datum,
      linka: form.linka.trim(),
      smer: form.smer.trim(),
      vuz: form.vuz.trim(),
      zacatek: form.zacatek,
      konec: form.konec,
    };

    let result;

    if (editing) {
      result = await supabase
        .from("vykazy")
        .update(payload)
        .eq("id", editing.id)
        .eq("uzivatel_id", user.id);
    } else {
      result = await supabase
        .from("vykazy")
        .insert(payload);
    }

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editing
        ? "Výkaz byl upraven."
        : "Výkaz byl přidán."
    );

    setEditing(null);
    setShowForm(false);

    await loadReports();

    setSaving(false);
  }

  async function deleteReport(report) {
    if (
      !window.confirm(
        "Opravdu chceš tento výkaz smazat?"
      )
    ) {
      return;
    }

    const { error } = await supabase
      .from("vykazy")
      .delete()
      .eq("id", report.id)
      .eq("uzivatel_id", user.id);

    if (error) {
      setError(error.message);
      return;
    }

    setSuccess("Výkaz byl smazán.");

    await loadReports();
  }

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Moje výkazy</h1>
          <p>Výkazy přihlášeného uživatele</p>
        </div>
      </div>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      <div className="panel">
        <div className="users-toolbar">
          <div>
            <h2>Moje výkazy</h2>

            <p className="muted">
              Při přidání nejdříve vybereš provozovnu a potom
              pouze vůz z této provozovny.
            </p>
          </div>

          <button
            className="primary-button"
            type="button"
            onClick={() => {
              setEditing(null);
              setShowForm(!showForm);
            }}
          >
            {showForm ? "✕ Zavřít" : "➕ Přidat výkaz"}
          </button>
        </div>

        {showForm && (
          <ReportForm
            currentUserId={user.id}
            initialData={editing}
            users={[]}
            adminMode={false}
            onSave={saveReport}
            onCancel={() => {
              setShowForm(false);
              setEditing(null);
            }}
            saving={saving}
            provozovny={provozovny}
          />
        )}

        {loading && (
          <div className="empty">
            Načítání výkazů...
          </div>
        )}

        {!loading && reports.length === 0 && (
          <div className="empty">
            Zatím žádné výkazy.
          </div>
        )}

        {!loading && reports.length > 0 && (
          <div className="reports-list">
            {reports.map((report) => (
              <ReportCard
                key={report.id}
                report={report}
                provozovnaName={getProvozovnaName(
                  report.provozovna_id
                )}
                onEdit={() => {
                  setEditing(report);
                  setShowForm(true);
                }}
                onDelete={() => deleteReport(report)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* =========================================================
   SPRÁVA VÝKAZŮ
========================================================= */

function DkvFinancialReport() {
  const [budget, setBudget] = useState(0);
  const [orders, setOrders] = useState([]);
  const [jobs, setJobs] = useState([]);
  const [month, setMonth] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  async function loadReport() {
    setLoading(true);
    try {
      const [budgetResult, orderResult, jobResult] = await Promise.all([
        supabase.from("dkv_lichkov_rozpocet").select("castka").eq("id", 1).maybeSingle(),
        supabase.from("dkv_lichkov_objednavky")
          .select("id,cislo_objednavky,datum,popis,castka_kc,stav"),
        supabase.from("dkv_lichkov_prijmy")
          .select("id,cislo_zakazky,datum,popis,prijem_kc,stav"),
      ]);
      const loadError = budgetResult.error || orderResult.error || jobResult.error;
      if (loadError) throw loadError;
      setBudget(Number(budgetResult.data?.castka || 0));
      setOrders(orderResult.data || []);
      setJobs(jobResult.data || []);
      setError("");
    } catch (loadError) {
      setError(getDkvSaveError(loadError));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadReport();
    const channel = supabase.channel("dkv-financial-report-live");
    for (const table of ["dkv_lichkov_rozpocet", "dkv_lichkov_objednavky", "dkv_lichkov_prijmy"]) {
      channel.on("postgres_changes", { event: "*", schema: "public", table }, loadReport);
    }
    channel.subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  const matchesMonth = (record) => !month || String(record.datum || "").startsWith(month);
  const periodOrders = orders.filter(matchesMonth);
  const periodJobs = jobs.filter(matchesMonth);
  const periodTotals = getDkvBudgetTotals(0, periodOrders, periodJobs);
  const allTotals = getDkvBudgetTotals(budget, orders, jobs);
  const entries = getDkvFinancialEntries(periodOrders, periodJobs)
    .sort((a, b) => String(b.date).localeCompare(String(a.date)) || a.id.localeCompare(b.id));
  const formatMoney = (amount) => `${Math.abs(Number(amount)).toLocaleString("cs-CZ", { maximumFractionDigits: 2 })} Kč`;

  return (
    <section className="standard-page budget-page dkv-financial-report">
      <header className="standard-page-head">
        <div><span className="page-eyebrow">VÝKAZY DKV LICHKOV</span><h1>Finanční výkaz DKV</h1>
          <p>Objednávky se vykazují jako výdaj, splněné a již uhrazené zakázky jako příjem. Zrušené objednávky a rozpracované zakázky se nezapočítávají.</p>
        </div>
      </header>
      <div className="panel dkv-report-filter">
        <label htmlFor="dkv-report-month">Období</label>
        <input id="dkv-report-month" type="month" value={month} onChange={(event) => setMonth(event.target.value)} />
        {month && <button type="button" className="secondary-button" onClick={() => setMonth("")}>Všechna období</button>}
        <button type="button" className="secondary-button" onClick={loadReport} disabled={loading}>Obnovit výkaz</button>
      </div>
      {error && <div className="error-box" role="alert">{error}</div>}
      {loading ? <div className="panel empty">Načítám výkaz DKV…</div> : error ? null : <>
        <div className="budget-summary-grid dkv-budget-summary">
          <div className="budget-summary-card"><span>Výdaje za období</span><strong>− {formatMoney(periodTotals.expenses)}</strong></div>
          <div className="budget-summary-card"><span>Příjmy za období</span><strong>+ {formatMoney(periodTotals.income)}</strong></div>
          <div className="budget-summary-card"><span>Rozdíl za období</span><strong>{periodTotals.remaining < 0 ? "−" : "+"} {formatMoney(periodTotals.remaining)}</strong></div>
          <div className="budget-summary-card"><span>Aktuálně zbývá v rozpočtu</span><strong className={allTotals.remaining < 0 ? "negative" : ""}>{allTotals.remaining < 0 ? "− " : ""}{formatMoney(allTotals.remaining)}</strong></div>
        </div>
        <div className="panel">
          <h2>Položky výkazu ({entries.length})</h2>
          <p className="muted">Základní rozpočet DKV: {formatMoney(budget)}. Aktuální zůstatek se počítá ze všech období.</p>
          {entries.length === 0 ? <div className="empty">V tomto období nejsou započítané objednávky ani splněné zakázky.</div> : <div className="budget-order-list">
            {entries.map((entry) => <div className="budget-order-row" key={entry.id}>
              <div><strong>{entry.kind}: {entry.title}</strong><small>{entry.date ? new Date(`${entry.date}T12:00:00`).toLocaleDateString("cs-CZ") : "—"} · {entry.status}{entry.description ? ` · ${entry.description}` : ""}</small></div>
              <strong>{entry.amount < 0 ? "−" : "+"} {formatMoney(entry.amount)}</strong>
            </div>)}
          </div>}
        </div>
      </>}
    </section>
  );
}

function AdminReports({ role }) {
  const [reports, setReports] = useState([]);
  const [users, setUsers] = useState([]);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);

  const [search, setSearch] = useState("");
  const [selectedProvozovna, setSelectedProvozovna] =
    useState("");

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const { provozovny } = useProvozovny();

  async function loadData() {
    setLoading(true);
    setError("");

    const [reportsResult, usersResult] =
      await Promise.all([
        supabase
          .from("vykazy")
          .select(
            "id, uzivatel_id, provozovna_id, datum, linka, smer, vuz, zacatek, konec"
          )
          .order("datum", { ascending: false })
          .order("zacatek", { ascending: false }),

        supabase
          .from("profiles")
          .select("id, jmeno, role, roles")
          .order("jmeno", { ascending: true }),
      ]);

    if (reportsResult.error) {
      setError(reportsResult.error.message);
    } else {
      setReports(reportsResult.data || []);
    }

    if (usersResult.error) {
      setError(usersResult.error.message);
    } else {
      setUsers(usersResult.data || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadData();
  }, []);

  function getUserName(id) {
    return (
      users.find((u) => u.id === id)?.jmeno ||
      "Neznámý uživatel"
    );
  }

  function getProvozovnaName(id) {
    return (
      provozovny.find(
        (p) => Number(p.id) === Number(id)
      )?.nazev || "-"
    );
  }

  async function saveReport(form) {
    setSaving(true);
    setError("");
    setSuccess("");

    if (!form.uzivatel_id) {
      setError("Vyber řidiče.");
      setSaving(false);
      return;
    }

    if (!form.provozovna_id) {
      setError("Vyber provozovnu.");
      setSaving(false);
      return;
    }

    if (!form.vuz) {
      setError("Vyber vůz.");
      setSaving(false);
      return;
    }

    const payload = {
      uzivatel_id: form.uzivatel_id,
      provozovna_id: Number(form.provozovna_id),
      datum: form.datum,
      linka: form.linka.trim(),
      smer: form.smer.trim(),
      vuz: form.vuz.trim(),
      zacatek: form.zacatek,
      konec: form.konec,
    };

    let result;

    if (editing) {
      result = await supabase
        .from("vykazy")
        .update(payload)
        .eq("id", editing.id);
    } else {
      result = await supabase
        .from("vykazy")
        .insert(payload);
    }

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editing
        ? "Výkaz byl upraven."
        : "Výkaz byl přidán."
    );

    setShowForm(false);
    setEditing(null);

    await loadData();

    setSaving(false);
  }

  async function deleteReport(report) {
    if (
      !window.confirm(
        "Opravdu chceš tento výkaz smazat?"
      )
    ) {
      return;
    }

    const { error } = await supabase
      .from("vykazy")
      .delete()
      .eq("id", report.id);

    if (error) {
      setError(error.message);
      return;
    }

    setSuccess("Výkaz byl smazán.");

    await loadData();
  }

  const filtered = reports.filter((report) => {
    if (
      selectedProvozovna &&
      Number(report.provozovna_id) !==
        Number(selectedProvozovna)
    ) {
      return false;
    }

    const text = [
      report.datum,
      report.linka,
      report.smer,
      report.vuz,
      report.zacatek,
      report.konec,
      getUserName(report.uzivatel_id),
      getProvozovnaName(report.provozovna_id),
    ]
      .filter(
        (x) =>
          x !== null &&
          x !== undefined
      )
      .join(" ")
      .toLowerCase();

    return text.includes(search.toLowerCase());
  });

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Správa výkazů</h1>
          <p>Administrace výkazů řidičů</p>
        </div>

        <div className="profile-badge">
          {filtered.length} VÝKAZŮ
        </div>
      </div>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      <div className="panel">
        <div className="provozovna-bar">
          <ProvozovnaSelect
            value={selectedProvozovna}
            onChange={setSelectedProvozovna}
            provozovny={provozovny}
            label="Zobrazit výkazy provozovny"
          />

          <button
            className="secondary-button"
            type="button"
            onClick={() => setSelectedProvozovna("")}
          >
            Všechny provozovny
          </button>
        </div>

        <div className="users-toolbar">
          <div>
            <h2>Výkazy řidičů</h2>

            <p className="muted">
              Přidávání, úprava a mazání výkazů.
            </p>
          </div>

          <button
            className="primary-button"
            type="button"
            onClick={() => {
              setEditing(null);
              setShowForm(!showForm);
            }}
          >
            {showForm ? "✕ Zavřít" : "➕ Přidat výkaz"}
          </button>
        </div>

        {showForm && (
          <ReportForm
            initialData={editing}
            users={users}
            currentUserId=""
            adminMode={true}
            onSave={saveReport}
            onCancel={() => {
              setShowForm(false);
              setEditing(null);
            }}
            saving={saving}
            provozovny={provozovny}
          />
        )}

        <input
          className="search"
          type="text"
          placeholder="🔎 Hledat výkaz..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        {loading && (
          <div className="empty">
            Načítání výkazů...
          </div>
        )}

        {!loading && filtered.length === 0 && (
          <div className="empty">
            Žádné výkazy.
          </div>
        )}

        {!loading && filtered.length > 0 && (
          <div className="reports-list">
            {filtered.map((report) => (
              <ReportCard
                key={report.id}
                report={report}
                userName={getUserName(
                  report.uzivatel_id
                )}
                provozovnaName={getProvozovnaName(
                  report.provozovna_id
                )}
                onEdit={() => {
                  setEditing(report);
                  setShowForm(true);
                }}
                onDelete={() =>
                  deleteReport(report)
                }
              />
            ))}
          </div>
        )}
      </div>
      {canViewDkv(role) && <DkvFinancialReport />}
    </div>
  );
}

/* =========================================================
   NOVINKY
========================================================= */

function News({ user, profile, role }) {
  const [news, setNews] = useState([]);
  const [confirmations, setConfirmations] = useState([]);
  const [profiles, setProfiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [selectedNews, setSelectedNews] = useState(null);

  const canManage = canManageNews(role);
  const isDriver = hasRole(role, ROLE_RIDIC);

  const emptyForm = {
    nadpis: "",
    obsah: "",
    dulezitost: "Běžná",
  };

  const [form, setForm] = useState(emptyForm);

  async function loadNews() {
    setLoading(true);
    setError("");

    const { data, error } = await supabase
      .from("novinky")
      .select(`
        id,
        nadpis,
        obsah,
        dulezitost,
        autor_id,
        created_at
      `)
      .order("created_at", { ascending: false });

    if (error) {
      console.error("NOVINKY ERROR:", error);
      setError(error.message);
      setNews([]);
      setLoading(false);
      return;
    }

    setNews(data || []);

    const newsIds = (data || []).map((item) => item.id);

    if (newsIds.length > 0) {
      const { data: confirmationData, error: confirmationError } =
        await supabase
          .from("novinky_potvrzeni")
          .select("id, novinka_id, uzivatel_id, potvrzeno_at")
          .in("novinka_id", newsIds);

      if (confirmationError) {
        console.error(
          "NOVINKY POTVRZENI ERROR:",
          confirmationError
        );
      }

      setConfirmations(confirmationData || []);
    } else {
      setConfirmations([]);
    }

    if (canManage) {
      const { data: profileData, error: profileError } =
        await supabase
          .from("profiles")
          .select("id, jmeno, role, roles")
          .order("jmeno", { ascending: true });

      if (profileError) {
        console.error(
          "NOVINKY PROFILES ERROR:",
          profileError
        );
      }

      setProfiles(profileData || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadNews();
  }, [canManage]);

  function openCreate() {
    setEditing(null);
    setForm(emptyForm);
    setError("");
    setSuccess("");
    setShowForm(true);
  }

  function openEdit(item) {
    setEditing(item);
    setForm({
      nadpis: item.nadpis || "",
      obsah: item.obsah || "",
      dulezitost: item.dulezitost || "Běžná",
    });
    setError("");
    setSuccess("");
    setShowForm(true);
  }

  function handleChange(e) {
    const { name, value } = e.target;

    setForm((previous) => ({
      ...previous,
      [name]: value,
    }));
  }

  async function saveNews(e) {
    e.preventDefault();

    const nadpis = form.nadpis.trim();
    const obsah = form.obsah.trim();

    if (!nadpis || !obsah) {
      setError("Vyplň nadpis a text novinky.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      nadpis,
      obsah,
      dulezitost: form.dulezitost,
    };

    let result;

    if (editing) {
      result = await supabase
        .from("novinky")
        .update(payload)
        .eq("id", editing.id);
    } else {
      result = await supabase
        .from("novinky")
        .insert({
          ...payload,
          autor_id: user.id,
        });
    }

    if (result.error) {
      console.error("SAVE NOVINKA ERROR:", result.error);
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editing
        ? "Novinka byla upravena."
        : "Novinka byla zveřejněna."
    );

    setForm(emptyForm);
    setEditing(null);
    setShowForm(false);

    await loadNews();
    setSaving(false);
  }

  async function deleteNews(id) {
    if (
      !window.confirm(
        "Opravdu chceš tuto novinku smazat?"
      )
    ) {
      return;
    }

    setError("");

    const { error } = await supabase
      .from("novinky")
      .delete()
      .eq("id", id);

    if (error) {
      console.error("DELETE NOVINKA ERROR:", error);
      setError(error.message);
      return;
    }

    if (selectedNews?.id === id) {
      setSelectedNews(null);
    }

    await loadNews();
  }

  async function confirmNews(item) {
    if (!user?.id) return;

    setError("");
    setSuccess("");

    const alreadyConfirmed = confirmations.some(
      (confirmation) =>
        confirmation.novinka_id === item.id &&
        confirmation.uzivatel_id === user.id
    );

    if (alreadyConfirmed) {
      return;
    }

    const { error } = await supabase
      .from("novinky_potvrzeni")
      .insert({
        novinka_id: item.id,
        uzivatel_id: user.id,
      });

    if (error) {
      if (error.code === "23505") {
        await loadNews();
        return;
      }

      console.error(
        "CONFIRM NOVINKA ERROR:",
        error
      );
      setError(error.message);
      return;
    }

    setSuccess("Novinka byla potvrzena jako přečtená.");
    await loadNews();
  }

  function isConfirmed(item) {
    return confirmations.some(
      (confirmation) =>
        confirmation.novinka_id === item.id &&
        confirmation.uzivatel_id === user?.id
    );
  }

  function getAuthorName(authorId) {
    const author = profiles.find(
      (profileItem) => profileItem.id === authorId
    );

    return author?.jmeno || "Uživatel";
  }

  function getConfirmationCount(item) {
    return confirmations.filter(
      (confirmation) =>
        confirmation.novinka_id === item.id
    ).length;
  }

  function getDriverProfiles() {
    return profiles.filter(
      (profileItem) =>
        hasRole(profileItem, ROLE_RIDIC)
    );
  }

  function formatDate(value) {
    if (!value) return "";

    return new Date(value).toLocaleString(
      "cs-CZ",
      {
        dateStyle: "short",
        timeStyle: "short",
      }
    );
  }

  return (
    <div className="news-page">
      <div className="topbar">
        <div>
          <h1>Novinky</h1>
          <p>
            Důležité informace pro řidiče a vedení Czech Mobility
          </p>
        </div>

        {canManage && (
          <button
            className="primary-button"
            onClick={openCreate}
          >
            + Nová novinka
          </button>
        )}
      </div>

      {error && (
        <div className="error-box">
          {error}
        </div>
      )}

      {success && (
        <div className="success-box">
          {success}
        </div>
      )}

      {showForm && canManage && (
        <div className="panel news-form-panel">
          <div className="panel-header">
            <div>
              <h2>
                {editing
                  ? "Upravit novinku"
                  : "Vytvořit novinku"}
              </h2>
              <p>
                Novinka se po zveřejnění zobrazí všem
                přihlášeným uživatelům.
              </p>
            </div>

            <button
              type="button"
              className="secondary-button"
              onClick={() => {
                setShowForm(false);
                setEditing(null);
                setForm(emptyForm);
              }}
            >
              Zavřít
            </button>
          </div>

          <form
            className="news-form"
            onSubmit={saveNews}
          >
            <div className="form-group">
              <label>Nadpis</label>
              <input
                name="nadpis"
                value={form.nadpis}
                onChange={handleChange}
                placeholder="Např. Změna pravidel výprav"
                maxLength={160}
              />
            </div>

            <div className="form-group">
              <label>Důležitost</label>
              <select
                name="dulezitost"
                value={form.dulezitost}
                onChange={handleChange}
              >
                <option value="Běžná">Běžná</option>
                <option value="Důležitá">Důležitá</option>
                <option value="Urgentní">Urgentní</option>
              </select>
            </div>

            <div className="form-group">
              <label>Text novinky</label>
              <textarea
                name="obsah"
                value={form.obsah}
                onChange={handleChange}
                placeholder="Napiš text novinky..."
                rows={8}
              />
            </div>

            <div className="news-form-actions">
              <button
                type="submit"
                className="primary-button"
                disabled={saving}
              >
                {saving
                  ? "Ukládání..."
                  : editing
                    ? "Uložit změny"
                    : "Zveřejnit novinku"}
              </button>
            </div>
          </form>
        </div>
      )}

      {loading ? (
        <div className="panel">
          <div className="loading-inline">
            Načítání novinek...
          </div>
        </div>
      ) : news.length === 0 ? (
        <div className="panel empty-state">
          <div className="empty-icon">📰</div>
          <h2>Zatím nejsou žádné novinky</h2>
          <p>
            Jakmile bude zveřejněna první novinka,
            zobrazí se zde.
          </p>
        </div>
      ) : (
        <div className="news-list">
          {news.map((item) => {
            const confirmed =
              isDriver && isConfirmed(item);
            const confirmationCount =
              getConfirmationCount(item);
            const driverCount =
              getDriverProfiles().length;

            return (
              <article
                className={
                  `news-card ${
                    confirmed
                      ? "news-card-confirmed"
                      : ""
                  }`
                }
                key={item.id}
              >
                <div className="news-card-top">
                  <div>
                    <span
                      className={
                        `news-priority ${
                          item.dulezitost === "Urgentní"
                            ? "urgent"
                            : item.dulezitost === "Důležitá"
                              ? "important"
                              : ""
                        }`
                      }
                    >
                      {item.dulezitost || "Běžná"}
                    </span>

                    <h2>{item.nadpis}</h2>

                    <div className="news-meta">
                      {formatDate(item.created_at)}
                      {canManage &&
                        item.autor_id && (
                          <>
                            {" • "}
                            Autor:{" "}
                            {getAuthorName(
                              item.autor_id
                            )}
                          </>
                        )}
                    </div>
                  </div>

                  <div
                    className={
                      confirmed
                        ? "news-status confirmed"
                        : isDriver
                          ? "news-status pending"
                          : "news-status confirmed"
                    }
                  >
                    {isDriver
                      ? confirmed
                        ? "✓ Přečteno"
                        : "● Nepotvrzeno"
                      : "ℹ Pro řidiče"}
                  </div>
                </div>

                <div className="news-content">
                  {item.obsah}
                </div>

                <div className="news-card-actions">
                  {isDriver && !confirmed && (
                    <button
                      className="primary-button"
                      onClick={() =>
                        confirmNews(item)
                      }
                    >
                      ✓ Potvrdit přečtení
                    </button>
                  )}

                  {isDriver && confirmed && (
                    <span className="confirmed-text">
                      ✓ Tuto novinku jsi potvrdil
                    </span>
                  )}

                  {canManage && (
                    <>
                      <button
                        className="secondary-button"
                        onClick={() =>
                          setSelectedNews(
                            selectedNews?.id === item.id
                              ? null
                              : item
                          )
                        }
                      >
                        {selectedNews?.id === item.id
                          ? "Skrýt potvrzení"
                          : `Potvrzení ${confirmationCount}/${driverCount}`}
                      </button>

                      <button
                        className="secondary-button"
                        onClick={() =>
                          openEdit(item)
                        }
                      >
                        ✎ Upravit
                      </button>

                      <button
                        className="secondary-button danger-button"
                        onClick={() =>
                          deleteNews(item.id)
                        }
                      >
                        🗑 Smazat
                      </button>
                    </>
                  )}
                </div>

                {canManage &&
                  selectedNews?.id === item.id && (
                    <div className="news-confirmation-panel">
                      <h3>Potvrzení přečtení</h3>

                      {getDriverProfiles().length ===
                      0 ? (
                        <p>
                          Zatím není evidován žádný řidič.
                        </p>
                      ) : (
                        <div className="news-driver-list">
                          {getDriverProfiles().map(
                            (driver) => {
                              const confirmedByDriver =
                                confirmations.some(
                                  (confirmation) =>
                                    confirmation.novinka_id ===
                                      item.id &&
                                    confirmation.uzivatel_id ===
                                      driver.id
                                );

                              return (
                                <div
                                  className="news-driver-row"
                                  key={driver.id}
                                >
                                  <span>
                                    {driver.jmeno ||
                                      "Bez jména"}
                                  </span>

                                  <strong
                                    className={
                                      confirmedByDriver
                                        ? "driver-confirmed"
                                        : "driver-not-confirmed"
                                    }
                                  >
                                    {confirmedByDriver
                                      ? "✓ Potvrzeno"
                                      : "✕ Nepotvrzeno"}
                                  </strong>
                                </div>
                              );
                            }
                          )}
                        </div>
                      )}
                    </div>
                  )}
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}


/* =========================================================
   ŽÁDOST O PŘIDĚLENÍ VOZIDLA
========================================================= */

function VehicleRequest({ user, profile }) {
  const [vehicles, setVehicles] = useState([]);
  const [selectedVehicleId, setSelectedVehicleId] = useState("");
  const [note, setNote] = useState("");
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function loadVehicles() {
    const { data, error: vehiclesError } = await supabase
      .from("vozy")
      .select("id, cislo, vyrobce, typ, spz, rok, stav")
      .order("cislo", { ascending: true });

    if (vehiclesError) {
      setError(`Vozy se nepodařilo načíst: ${vehiclesError.message}`);
      setVehicles([]);
      return;
    }

    setVehicles(data || []);
  }

  async function loadMyRequests() {
    if (!user?.id) {
      setRequests([]);
      return;
    }

    const { data, error: requestsError } = await supabase
      .from("zadosti_vozidla")
      .select("id, vuz_id, poznamka, stav, created_at")
      .eq("uzivatel_id", user.id)
      .order("created_at", { ascending: false });

    if (requestsError) {
      setError(`Žádosti se nepodařilo načíst: ${requestsError.message}`);
      setRequests([]);
      return;
    }

    setRequests(data || []);
  }

  useEffect(() => {
    let active = true;

    async function load() {
      setLoading(true);
      setError("");
      await Promise.all([loadVehicles(), loadMyRequests()]);
      if (active) setLoading(false);
    }

    load();
    return () => {
      active = false;
    };
  }, [user?.id]);

  async function submitRequest(e) {
    e.preventDefault();
    setError("");
    setSuccess("");

    if (!user?.id) {
      setError("Nejsi přihlášený uživatel.");
      return;
    }

    if (!selectedVehicleId) {
      setError("Vyber vozidlo.");
      return;
    }

    if (!note.trim()) {
      setError("Napiš důvod nebo poznámku k žádosti.");
      return;
    }

    const duplicate = requests.find((r) =>
      Number(r.vuz_id) === Number(selectedVehicleId) &&
      ["ČEKÁ NA VYŘÍZENÍ", "SCHVÁLENO"].includes(r.stav)
    );
    if (duplicate) {
      setError("Na tento vůz už máš aktivní žádost nebo je ti už přidělen.");
      return;
    }

    setSaving(true);

    const { error: insertError } = await supabase
      .from("zadosti_vozidla")
      .insert({
        uzivatel_id: user.id,
        vuz_id: Number(selectedVehicleId),
        poznamka: note.trim(),
        stav: "ČEKÁ NA VYŘÍZENÍ",
      });

    setSaving(false);

    if (insertError) {
      setError(`Žádost se nepodařilo uložit: ${insertError.message}`);
      return;
    }

    setSelectedVehicleId("");
    setNote("");
    setSuccess("Žádost byla úspěšně odeslána.");
    await loadMyRequests();
  }

  function getVehicle(id) {
    return vehicles.find((vehicle) => Number(vehicle.id) === Number(id));
  }

  const selectedVehicle = selectedVehicleId
    ? getVehicle(selectedVehicleId)
    : null;

  return (
    <div className="request-page">
      <div className="request-hero">
        <div>
          <div className="request-eyebrow">VOZOVÝ PARK</div>
          <h1>Žádost o přidělení vozidla</h1>
          <p>
            Vyber konkrétní vůz a stručně napiš, k čemu ho potřebuješ.
          </p>
        </div>

        <div className="request-user">
          <span className="request-user-dot" />
          <div>
            <strong>{profile?.jmeno || user?.email || "Uživatel"}</strong>
            <small>Nová žádost o přidělení</small>
          </div>
        </div>
      </div>

      {error && (
        <div className="request-alert request-alert-error">
          <span className="request-alert-icon">!</span>
          <div>
            <strong>Žádost se nepodařilo dokončit</strong>
            <div>{error}</div>
          </div>
        </div>
      )}

      {success && (
        <div className="request-alert request-alert-success">
          <span className="request-alert-icon">✓</span>
          <div>
            <strong>Hotovo</strong>
            <div>{success}</div>
          </div>
        </div>
      )}

      <div className="request-layout">
        <section className="request-card request-card-main">
          <div className="request-card-heading">
            <div>
              <span className="request-step">1</span>
              <div>
                <h2>Vyber vozidlo</h2>
                <p>Vyber vůz ze seznamu aktuálně evidovaného vozového parku.</p>
              </div>
            </div>
          </div>

          {loading ? (
            <div className="request-loading">
              <div className="request-spinner" />
              <span>Načítám vozidla…</span>
            </div>
          ) : (
            <form onSubmit={submitRequest}>
              <div className="request-field">
                <label htmlFor="vehicle-request-select">Vozidlo</label>
                <div className="request-select-wrap">
                  <select
                    id="vehicle-request-select"
                    className="request-select"
                    value={selectedVehicleId}
                    onChange={(e) => setSelectedVehicleId(e.target.value)}
                    required
                  >
                    <option value="">Vyber vůz…</option>
                    {vehicles.map((vehicle) => (
                      <option key={vehicle.id} value={vehicle.id}>
                        {vehicle.cislo} — {vehicle.vyrobce || "Neznámý výrobce"}{" "}
                        {vehicle.typ || ""}
                        {vehicle.spz ? ` · ${vehicle.spz}` : ""}
                      </option>
                    ))}
                  </select>
                  <span className="request-select-arrow">⌄</span>
                </div>
              </div>

              {selectedVehicle && (
                <div className="request-vehicle-preview">
                  <div className="request-vehicle-icon">🚌</div>
                  <div className="request-vehicle-info">
                    <div className="request-vehicle-number">
                      Vůz {selectedVehicle.cislo}
                    </div>
                    <div className="request-vehicle-name">
                      {selectedVehicle.vyrobce || "—"}{" "}
                      {selectedVehicle.typ || "—"}
                    </div>
                    <div className="request-vehicle-meta">
                      {selectedVehicle.rok
                        ? `Rok ${selectedVehicle.rok}`
                        : "Rok neuveden"}
                      {selectedVehicle.spz
                        ? ` · SPZ ${selectedVehicle.spz}`
                        : ""}
                    </div>
                  </div>
                  <div className="request-vehicle-status">
                    <span>{selectedVehicle.stav || "—"}</span>
                  </div>
                </div>
              )}

              <div className="request-card-heading request-card-heading-spaced">
                <div>
                  <span className="request-step">2</span>
                  <div>
                    <h2>Dodatek</h2>
                    <p>
                      Napiš dodatek k přidělení vozidla
                    </p>
                  </div>
                </div>
              </div>

              <div className="request-field">
                <label htmlFor="vehicle-request-note">Dodatek</label>
                <textarea
                  id="vehicle-request-note"
                  className="request-textarea"
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  placeholder="Napiš dodatek k přidělení vozidla"
                  rows={7}
                  required
                />
                <div className="request-helper">např. šel by tuning?</div>
                <div className="request-hint">
                  Čím konkrétněji žádost popíšeš, tím snadněji ji dispečer vyřídí.
                </div>
              </div>

              <div className="request-submit-row">
                <button
                  className="request-submit-button"
                  type="submit"
                  disabled={saving || loading}
                >
                  <span>{saving ? "Odesílám…" : "Odeslat žádost"}</span>
                  {!saving && <span className="request-submit-arrow">→</span>}
                </button>
              </div>
            </form>
          )}
        </section>

        <aside className="request-card request-card-side">
          <div className="request-card-heading">
            <div>
              <div>
                <h2>Moje žádosti</h2>
                <p>Stav dříve odeslaných žádostí.</p>
              </div>
            </div>
          </div>

          {requests.length === 0 ? (
            <div className="request-empty-state">
              <div className="request-empty-icon">📋</div>
              <strong>Zatím žádná žádost</strong>
              <span>Odeslané žádosti se zobrazí zde.</span>
            </div>
          ) : (
            <div className="request-history">
              {requests.map((request) => {
                const vehicle = getVehicle(request.vuz_id);

                return (
                  <article className="request-history-item" key={request.id}>
                    <div className="request-history-top">
                      <div>
                        <strong>
                          Vůz {vehicle?.cislo ?? request.vuz_id}
                        </strong>
                        <small>
                          {request.created_at
                            ? new Date(request.created_at).toLocaleString("cs-CZ")
                            : "—"}
                        </small>
                      </div>

                      <span className="request-history-status">
                        {request.stav || "ČEKÁ NA VYŘÍZENÍ"}
                      </span>
                    </div>

                    <div className="request-history-note">
                      {request.poznamka || "Bez poznámky"}
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </aside>
      </div>
    </div>
  );
}


/* =========================================================
   SPRÁVA ŽÁDOSTÍ O PŘIDĚLENÍ VOZIDLA
========================================================= */

function AdminVehicleRequests() {
  const [requests, setRequests] = useState([]);
  const [profiles, setProfiles] = useState({});
  const [vehicles, setVehicles] = useState({});
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function loadRequests() {
    setLoading(true);
    setError("");

    const { data, error: requestsError } = await supabase
      .from("zadosti_vozidla")
      .select("id, uzivatel_id, vuz_id, poznamka, stav, created_at")
      .order("created_at", { ascending: false });

    if (requestsError) {
      setError(requestsError.message);
      setRequests([]);
      setLoading(false);
      return;
    }

    const rows = data || [];
    setRequests(rows);

    const userIds = [...new Set(rows.map((r) => r.uzivatel_id).filter(Boolean))];
    const vehicleIds = [...new Set(rows.map((r) => r.vuz_id).filter(Boolean))];

    const [{ data: userRows }, { data: vehicleRows }] = await Promise.all([
      userIds.length
        ? supabase.from("profiles").select("id, jmeno").in("id", userIds)
        : Promise.resolve({ data: [] }),
      vehicleIds.length
        ? supabase.from("vozy").select("id, cislo, vyrobce, typ, spz").in("id", vehicleIds)
        : Promise.resolve({ data: [] }),
    ]);

    setProfiles(
      Object.fromEntries((userRows || []).map((u) => [u.id, u]))
    );
    setVehicles(
      Object.fromEntries((vehicleRows || []).map((v) => [v.id, v]))
    );
    setLoading(false);
  }

  useEffect(() => {
    loadRequests();
  }, []);

  async function changeStatus(id, stav) {
    setSavingId(id);
    setError("");
    setSuccess("");

    const request = requests.find((item) => item.id === id);

    if (!request) {
      setError("Žádost se nepodařilo najít.");
      setSavingId(null);
      return;
    }

    // Při schválení žádosti automaticky přidělíme žadatele k vozu.
    // Pokud už je Řidič 1 obsazený, použije se Řidič 2.
    const applicant = profiles[request.uzivatel_id];
    const driverName = applicant?.jmeno?.trim();

    // Při schválení žádosti automaticky přidělíme žadatele k vozu.
    if (stav === "SCHVÁLENO") {
      if (!driverName) {
        setError("U žadatele není vyplněné jméno, proto ho nelze přidělit k vozu.");
        setSavingId(null);
        return;
      }

      const { data: vehicleRow, error: vehicleLoadError } = await supabase
        .from("vozy")
        .select("id, cislo, ridic_1, ridic_2, ridic_1_pridelen_at, ridic_2_pridelen_at")
        .eq("id", request.vuz_id)
        .single();

      if (vehicleLoadError || !vehicleRow) {
        setError(
          vehicleLoadError?.message || "Vůz se nepodařilo načíst."
        );
        setSavingId(null);
        return;
      }

      const driver1 = (vehicleRow.ridic_1 || "").trim();
      const driver2 = (vehicleRow.ridic_2 || "").trim();
      const alreadyAssigned =
        driver1.toLowerCase() === driverName.toLowerCase() ||
        driver2.toLowerCase() === driverName.toLowerCase();

      if (!alreadyAssigned) {
        let vehiclePayload = null;

        if (!driver1) {
          vehiclePayload = { ridic_1: driverName, ridic_1_pridelen_at: new Date().toISOString() };
        } else if (!driver2) {
          vehiclePayload = { ridic_2: driverName, ridic_2_pridelen_at: new Date().toISOString() };
        } else {
          setError(
            `Vůz ${vehicleRow.cislo ?? ""} už má přidělené dva řidiče (${driver1} a ${driver2}).`
          );
          setSavingId(null);
          return;
        }

        const { error: vehicleUpdateError } = await supabase
          .from("vozy")
          .update(vehiclePayload)
          .eq("id", request.vuz_id);

        if (vehicleUpdateError) {
          setError(vehicleUpdateError.message);
          setSavingId(null);
          return;
        }
      }
    }

    // Když byla žádost schválená a následně ji změníme na jiný stav
    // (např. ZAMÍTNUTO), odebereme tohoto žadatele z vozu.
    if (
      request.stav === "SCHVÁLENO" &&
      stav !== "SCHVÁLENO" &&
      driverName
    ) {
      const { data: vehicleRow, error: vehicleLoadError } = await supabase
        .from("vozy")
        .select("id, cislo, ridic_1, ridic_2, ridic_1_pridelen_at, ridic_2_pridelen_at")
        .eq("id", request.vuz_id)
        .single();

      if (vehicleLoadError || !vehicleRow) {
        setError(
          vehicleLoadError?.message || "Vůz se nepodařilo načíst."
        );
        setSavingId(null);
        return;
      }

      const driver1 = (vehicleRow.ridic_1 || "").trim();
      const driver2 = (vehicleRow.ridic_2 || "").trim();
      const normalizedName = driverName.toLowerCase();
      let vehiclePayload = null;

      if (driver1.toLowerCase() === normalizedName) {
        // Pokud byl žadatel Řidič 1, posuneme případného Řidiče 2 nahoru.
        vehiclePayload = {
          ridic_1: driver2 || null,
          ridic_1_pridelen_at: driver2 ? vehicleRow.ridic_2_pridelen_at : null,
          ridic_2: null,
          ridic_2_pridelen_at: null,
        };
      } else if (driver2.toLowerCase() === normalizedName) {
        vehiclePayload = { ridic_2: null, ridic_2_pridelen_at: null };
      }

      if (vehiclePayload) {
        const { error: vehicleUpdateError } = await supabase
          .from("vozy")
          .update(vehiclePayload)
          .eq("id", request.vuz_id);

        if (vehicleUpdateError) {
          setError(vehicleUpdateError.message);
          setSavingId(null);
          return;
        }
      }
    }

    const { error: updateError } = await supabase
      .from("zadosti_vozidla")
      .update({ stav })
      .eq("id", id);

    if (updateError) {
      setError(updateError.message);
      setSavingId(null);
      return;
    }

    await Promise.all([
      supabase.from("notifications").insert({
        uzivatel_id: request.uzivatel_id,
        typ: "PRIDELENI_VOZU",
        zprava: `Žádost o vůz ${vehicles[request.vuz_id]?.cislo ?? request.vuz_id} byla změněna na ${stav}.`,
      }),
      supabase.from("vehicle_history").insert({
        vuz_id: request.vuz_id,
        uzivatel_id: request.uzivatel_id,
        typ: stav === "SCHVÁLENO" ? "RIDIC_PRIDELEN" : "ZMENA_ZADOSTI",
        popis: `${driverName || "Řidič"}: stav žádosti ${stav}.`,
      }),
      supabase.from("audit_log").insert({
        uzivatel_id: null,
        akce: "ZMENA_STAVU_ZADOSTI",
        entita: "zadosti_vozidla",
        entita_id: String(id),
        detail: `${driverName || request.uzivatel_id} → ${stav}`,
      }),
    ]);

    setSuccess(
      stav === "SCHVÁLENO"
        ? "Žádost byla schválena a řidič byl přidělen k vozu."
        : request.stav === "SCHVÁLENO"
        ? "Žádost byla změněna a řidič byl z vozu odebrán."
        : "Stav žádosti byl změněn."
    );

    await loadRequests();
    setSavingId(null);
  }


  async function deleteRequest(request) {
    setError("");
    setSuccess("");
    setSavingId(request.id);

    const vehicle = vehicles[request.vuz_id];
    const applicant = profiles[request.uzivatel_id];

    const confirmed = window.confirm(
      `Opravdu chceš smazat žádost ${applicant?.jmeno || ""} o vůz ${
        vehicle?.cislo ?? request.vuz_id
      }?`
    );

    if (!confirmed) {
      setSavingId(null);
      return;
    }

    const { data: deletedRows, error: deleteError } = await supabase
      .from("zadosti_vozidla")
      .delete()
      .eq("id", request.id)
      .select("id");

    if (deleteError) {
      console.error("Chyba při mazání žádosti:", deleteError);
      setError(`Žádost se nepodařilo smazat: ${deleteError.message}`);
      setSavingId(null);
      return;
    }

    if (!deletedRows || deletedRows.length === 0) {
      setError(
        "Žádost nebyla smazána. Supabase nevrátil smazaný řádek. Zkontroluj DELETE RLS policy pro zadosti_vozidla."
      );
      setSavingId(null);
      return;
    }

    // Okamžitě ji odebereme i z UI.
    setRequests((old) =>
      old.filter((item) => String(item.id) !== String(request.id))
    );

    // Audit nesmí zablokovat samotné smazání žádosti.
    const { error: auditError } = await supabase.from("audit_log").insert({
      uzivatel_id: null,
      akce: "SMAZANA_ZADOST_O_PRIDELENI",
      entita: "zadosti_vozidla",
      entita_id: String(request.id),
      detail: `${applicant?.jmeno || request.uzivatel_id} · vůz ${
        vehicle?.cislo ?? request.vuz_id
      }`,
    });

    if (auditError) {
      console.warn("Audit log se nepodařilo zapsat:", auditError);
    }

    setSuccess("Žádost byla úspěšně smazána.");
    setSavingId(null);

    // Synchronizace s databází.
    await loadRequests();
  }

  function getRequestStatusClass(stav) {
    if (stav === "SCHVÁLENO") return "approved";
    if (stav === "ZAMÍTNUTO") return "rejected";
    if (stav === "VYŘÍZENO") return "done";
    return "pending";
  }

  return (
    <div className="assignment-admin-page">
      <div className="topbar">
        <div>
          <div className="assignment-admin-eyebrow">VOZOVÝ PARK</div>
          <h1>Žádosti o přidělení vozidla</h1>
          <p>Schvalování, zamítání a správa žádostí o konkrétní vozy.</p>
        </div>

        <div className="profile-badge">
          {requests.length} ŽÁDOSTÍ
        </div>
      </div>

      {error && (
        <div className="request-alert request-alert-error">
          <span className="request-alert-icon">!</span>
          <div>
            <strong>Chyba</strong>
            <div>{error}</div>
          </div>
        </div>
      )}

      {success && (
        <div className="request-alert request-alert-success">
          <span className="request-alert-icon">✓</span>
          <div>
            <strong>Hotovo</strong>
            <div>{success}</div>
          </div>
        </div>
      )}

      {loading ? (
        <div className="assignment-admin-empty">
          <div className="request-spinner" />
          <span>Načítám žádosti…</span>
        </div>
      ) : requests.length === 0 ? (
        <div className="assignment-admin-empty">
          <div className="assignment-admin-empty-icon">📋</div>
          <strong>Žádné žádosti</strong>
          <span>Aktuálně není co vyřizovat.</span>
        </div>
      ) : (
        <div className="assignment-admin-list">
          {requests.map((request) => {
            const applicant = profiles[request.uzivatel_id];
            const vehicle = vehicles[request.vuz_id];
            const busy = savingId === request.id;

            return (
              <article className="assignment-admin-card" key={request.id}>
                <div className="assignment-admin-card-head">
                  <div className="assignment-admin-vehicle">
                    <div className="assignment-admin-bus-icon">🚌</div>

                    <div className="assignment-admin-title">
                      <span>ŽÁDOST O PŘIDĚLENÍ</span>
                      <h3>Vůz {vehicle?.cislo ?? request.vuz_id ?? "-"}</h3>
                      <p>
                        {vehicle
                          ? `${vehicle.vyrobce || "—"} ${vehicle.typ || ""}`.trim()
                          : "Vozidlo se nepodařilo načíst"}
                      </p>
                    </div>
                  </div>

                  <span
                    className={`assignment-status-badge ${getRequestStatusClass(
                      request.stav
                    )}`}
                  >
                    {request.stav || "ČEKÁ NA VYŘÍZENÍ"}
                  </span>
                </div>

                <div className="assignment-admin-info-grid">
                  <div className="assignment-admin-info">
                    <span>👤 Žadatel</span>
                    <strong>
                      {applicant?.jmeno || request.uzivatel_id || "-"}
                    </strong>
                  </div>

                  <div className="assignment-admin-info">
                    <span>🪪 SPZ</span>
                    <strong>{vehicle?.spz || "—"}</strong>
                  </div>

                  <div className="assignment-admin-info">
                    <span>📅 Odesláno</span>
                    <strong>
                      {request.created_at
                        ? new Date(request.created_at).toLocaleString("cs-CZ")
                        : "—"}
                    </strong>
                  </div>
                </div>

                <div className="assignment-admin-note">
                  <span>Poznámka žadatele</span>
                  <p>{request.poznamka || "Bez poznámky"}</p>
                </div>

                <div className="assignment-admin-actions">
                  <div className="assignment-admin-status-control">
                    <label>Stav žádosti</label>
                    <select
                      className="assignment-status-select"
                      value={request.stav || "ČEKÁ NA VYŘÍZENÍ"}
                      onChange={(e) =>
                        changeStatus(request.id, e.target.value)
                      }
                      disabled={busy}
                    >
                      <option value="ČEKÁ NA VYŘÍZENÍ">
                        ČEKÁ NA VYŘÍZENÍ
                      </option>
                      <option value="SCHVÁLENO">SCHVÁLENO</option>
                      <option value="ZAMÍTNUTO">ZAMÍTNUTO</option>
                      <option value="VYŘÍZENO">VYŘÍZENO</option>
                    </select>
                  </div>

                  <button
                    type="button"
                    className="assignment-delete-button"
                    disabled={busy}
                    onClick={() => deleteRequest(request)}
                  >
                    <span>🗑️</span>
                    {busy ? "Pracuji…" : "Smazat žádost"}
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}



/* =========================================================
   ČLENOVÉ
========================================================= */

function getMinutesBetweenTimes(start, end) {
  if (!start || !end) return 0;

  const startMatch = String(start).match(/^(\d{1,2}):(\d{2})/);
  const endMatch = String(end).match(/^(\d{1,2}):(\d{2})/);

  if (!startMatch || !endMatch) return 0;

  const startMinutes = Number(startMatch[1]) * 60 + Number(startMatch[2]);
  const endMinutes = Number(endMatch[1]) * 60 + Number(endMatch[2]);

  if (endMinutes >= startMinutes) {
    return endMinutes - startMinutes;
  }

  // Směna přes půlnoc, např. 22:00–02:00.
  return 24 * 60 - startMinutes + endMinutes;
}

function formatDuration(minutes) {
  const safeMinutes = Math.max(0, Number(minutes) || 0);
  const hours = Math.floor(safeMinutes / 60);
  const mins = safeMinutes % 60;

  if (hours === 0) return `${mins} min`;
  if (mins === 0) return `${hours} h`;
  return `${hours} h ${mins} min`;
}

function Members({ user }) {
  const [members, setMembers] = useState([]);
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedMemberId, setSelectedMemberId] = useState(null);

  async function loadMembers() {
    setLoading(true);
    setError("");

    const [membersResult, reportsResult] = await Promise.all([
      supabase
        .from("profiles")
        .select("id, jmeno, role, roles, created_at")
        .order("jmeno", { ascending: true }),
      supabase
        .from("vykazy")
        .select(
          "id, uzivatel_id, datum, linka, smer, vuz, zacatek, konec, provozovna_id"
        )
        .order("datum", { ascending: false })
        .order("zacatek", { ascending: false }),
    ]);

    if (membersResult.error) {
      setError(membersResult.error.message);
      setMembers([]);
    } else {
      setMembers(membersResult.data || []);
    }

    if (reportsResult.error) {
      setError((old) => old || reportsResult.error.message);
      setReports([]);
    } else {
      setReports(reportsResult.data || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadMembers();
  }, []);

  const statsByMember = members.reduce((acc, member) => {
    const memberReports = reports.filter(
      (report) => String(report.uzivatel_id) === String(member.id)
    );

    const totalMinutes = memberReports.reduce(
      (sum, report) =>
        sum + getMinutesBetweenTimes(report.zacatek, report.konec),
      0
    );

    acc[member.id] = {
      reports: memberReports,
      totalMinutes,
    };

    return acc;
  }, {});

  const selectedMember = members.find(
    (member) => String(member.id) === String(selectedMemberId)
  );

  const selectedStats = selectedMember
    ? statsByMember[selectedMember.id] || { reports: [], totalMinutes: 0 }
    : null;

  if (selectedMember) {
    return (
      <div>
        <div className="topbar">
          <div>
            <button
              type="button"
              className="secondary-button"
              onClick={() => setSelectedMemberId(null)}
              style={{ marginBottom: 12 }}
            >
              ← Zpět na členy
            </button>
            <h1>{selectedMember.jmeno || "Bez jména"}</h1>
            <p>{getRoleName(selectedMember)}</p>
          </div>

          <div className="profile-badge">
            {formatDuration(selectedStats.totalMinutes)}
          </div>
        </div>

        {error && (
          <div className="error-box" style={{ marginBottom: 16 }}>
            <strong>Chyba:</strong>
            <br />
            {error}
          </div>
        )}

        <div className="member-detail-stats">
          <div className="member-stat-card">
            <span>Celkem hodin</span>
            <strong>{formatDuration(selectedStats.totalMinutes)}</strong>
          </div>
          <div className="member-stat-card">
            <span>Počet výkazů</span>
            <strong>{selectedStats.reports.length}</strong>
          </div>
        </div>

        <div className="panel">
          <div className="users-toolbar">
            <div>
              <h2>Historie směn</h2>
              <p className="muted">
                Všechny výkazy tohoto člena. Celkové hodiny se počítají přímo
                ze začátku a konce jednotlivých směn.
              </p>
            </div>
          </div>

          {selectedStats.reports.length === 0 ? (
            <div className="empty">Tento člen zatím nemá žádný výkaz.</div>
          ) : (
            <div className="member-reports-list">
              {selectedStats.reports.map((report) => {
                const duration = getMinutesBetweenTimes(
                  report.zacatek,
                  report.konec
                );

                return (
                  <div className="member-report-card" key={report.id}>
                    <div className="member-report-date">
                      <strong>
                        {report.datum
                          ? new Date(
                              `${report.datum}T00:00:00`
                            ).toLocaleDateString("cs-CZ")
                          : "-"}
                      </strong>
                      <small>
                        {report.zacatek || "-"} – {report.konec || "-"}
                      </small>
                    </div>

                    <div>
                      <small>Vůz</small>
                      <strong>{report.vuz || "-"}</strong>
                    </div>

                    <div>
                      <small>Linka</small>
                      <strong>{report.linka || "-"}</strong>
                    </div>

                    <div className="member-report-route">
                      <small>Směr</small>
                      <strong>{report.smer || "-"}</strong>
                    </div>

                    <div>
                      <small>Délka</small>
                      <strong>{formatDuration(duration)}</strong>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    );
  }

  const totalMemberHours = Object.values(statsByMember).reduce(
    (sum, stats) => sum + stats.totalMinutes,
    0
  );

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Členové</h1>
          <p>Přehled členů a jejich odjetých směn</p>
        </div>

        <div className="profile-badge">
          {members.length} ČLENŮ
        </div>
      </div>

      {error && (
        <div className="error-box">
          <strong>Chyba:</strong>
          <br />
          {error}
        </div>
      )}

      {!loading && !error && (
        <div className="member-summary-bar">
          <div>
            <span>Členové</span>
            <strong>{members.length}</strong>
          </div>
          <div>
            <span>Celkem hodin</span>
            <strong>{formatDuration(totalMemberHours)}</strong>
          </div>
          <div>
            <span>Celkem výkazů</span>
            <strong>{reports.length}</strong>
          </div>
        </div>
      )}

      <div className="panel">
        {loading ? (
          <div className="empty">Načítání členů...</div>
        ) : members.length === 0 ? (
          <div className="empty">Žádní členové.</div>
        ) : (
          <div className="member-grid">
            {members.map((member) => {
              const stats = statsByMember[member.id] || {
                reports: [],
                totalMinutes: 0,
              };

              return (
                <button
                  type="button"
                  className="member-card"
                  key={member.id}
                  onClick={() => setSelectedMemberId(member.id)}
                >
                  <div className="member-card-avatar">
                    {(member.jmeno || "Č")
                      .charAt(0)
                      .toUpperCase()}
                  </div>

                  <div className="member-card-main">
                    <strong>{member.jmeno || "Bez jména"}</strong>
                    <small>{getRoleName(member)}</small>
                  </div>

                  <div className="member-card-stat">
                    <span>Celkem hodin</span>
                    <strong>{formatDuration(stats.totalMinutes)}</strong>
                  </div>

                  <div className="member-card-stat">
                    <span>Výkazy</span>
                    <strong>{stats.reports.length}</strong>
                  </div>

                  <div className="member-card-arrow">›</div>
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

/* =========================================================
   APP
========================================================= */


/* =========================================================
   NOVÉ MODULY: NOTIFIKACE, ODEVZDÁNÍ, ZÁVADY, VÝPRAVY, AUDIT
========================================================= */
function Notifications({ user, role }) {
  const manage = canManageVehicles(role);
  const isDriver = hasRole(role, ROLE_RIDIC);

  const [items, setItems] = useState([]);
  const [sentItems, setSentItems] = useState([]);
  const [profiles, setProfiles] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [sending, setSending] = useState(false);
  const [busyId, setBusyId] = useState(null);
  const [browserPermission, setBrowserPermission] = useState(
    typeof window !== "undefined" && "Notification" in window
      ? window.Notification.permission
      : "unsupported"
  );

  const [recipientId, setRecipientId] = useState("");
  const [notificationType, setNotificationType] = useState("OBECNÁ");
  const [message, setMessage] = useState("");
  const [requiresConfirmation, setRequiresConfirmation] = useState(true);
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState("");

  const [editingId, setEditingId] = useState(null);
  const [editType, setEditType] = useState("OBECNÁ");
  const [editMessage, setEditMessage] = useState("");
  const [editRequiresConfirmation, setEditRequiresConfirmation] = useState(true);
  const [editImageFile, setEditImageFile] = useState(null);
  const [editImagePreview, setEditImagePreview] = useState("");
  const [editRemoveImage, setEditRemoveImage] = useState(false);

  const notificationTypes = [
    "OBECNÁ",
    "INFORMACE",
    "DŮLEŽITÉ",
    "UPOZORNĚNÍ",
    "VOZIDLO",
    "VÝPRAVA",
  ];

  function getProfile(id) {
    return profiles.find((profile) => String(profile.id) === String(id));
  }

  function getSenderName(notification) {
    if (!notification?.odesilatel_id) {
      return "Systém";
    }

    const sender = getProfile(notification.odesilatel_id);

    return sender?.jmeno || "Neznámý uživatel";
  }


  // Jedna rozesílka může mít v DB více řádků (jeden pro každého příjemce).
  // V administraci je ale zobrazíme jako JEDNU kartu.
  const sentGroups = sentItems.reduce((groups, notification) => {
    const key = `${notification.odesilatel_id || "sender"}::${
      notification.created_at || notification.id
    }`;

    let group = groups.find((item) => item.key === key);

    if (!group) {
      group = {
        key,
        items: [],
        first: notification,
      };
      groups.push(group);
    }

    group.items.push(notification);
    return groups;
  }, []);

  function getGroupRecipientNames(group) {
    const names = group.items.map((notification) => {
      const profile = getProfile(notification.uzivatel_id);
      return profile?.jmeno || notification.uzivatel_id;
    });

    if (names.length <= 4) return names.join(", ");

    return `${names.slice(0, 4).join(", ")} +${names.length - 4}`;
  }

  function getGroupConfirmation(group) {
    const first = group.first;

    if (!first.vyzaduje_potvrzeni) {
      return {
        label: "Potvrzení se nevyžaduje",
        confirmed: true,
      };
    }

    const driverItems = group.items.filter((notification) => {
      const profile = getProfile(notification.uzivatel_id);
      return hasRole(profile, ROLE_RIDIC);
    });

    if (driverItems.length === 0) {
      return {
        label: "Bez řidičů k potvrzení",
        confirmed: true,
      };
    }

    const confirmedCount = driverItems.filter(
      (notification) => notification.potvrzeno
    ).length;

    return {
      label: `${confirmedCount}/${driverItems.length} řidičů potvrdilo`,
      confirmed: confirmedCount === driverItems.length,
    };
  }

  async function load() {
    setError("");

    const ownQuery = supabase
      .from("notifications")
      .select("*")
      .eq("uzivatel_id", user.id)
      .order("created_at", { ascending: false });

    const sentQuery = manage
      ? supabase
          .from("notifications")
          .select("*")
          .not("odesilatel_id", "is", null)
          .order("created_at", { ascending: false })
      : Promise.resolve({ data: [], error: null });

    const [ownResult, sentResult] = await Promise.all([ownQuery, sentQuery]);

    if (ownResult.error) {
      setError(ownResult.error.message);
      setItems([]);
    } else {
      setItems(ownResult.data || []);
    }

    if (manage) {
      if (sentResult.error) {
        setError((old) => old || sentResult.error.message);
        setSentItems([]);
      } else {
        setSentItems(sentResult.data || []);
      }
    } else {
      setSentItems([]);
    }
  }

  async function loadProfiles() {
    const { data, error: profilesError } = await supabase
      .from("profiles")
      .select("id, jmeno, role, roles")
      .order("jmeno", { ascending: true });

    if (profilesError) {
      console.error("NOTIFICATION PROFILES:", profilesError);
      setProfiles([]);
      return;
    }

    setProfiles(data || []);
  }

  useEffect(() => {
    load();
  }, [user.id, manage]);

  useEffect(() => {
    if (!user?.id) return;

    const channel = supabase
      .channel(`notifications-page-${user.id}-${manage ? "manage" : "own"}`)
      .on(
        "postgres_changes",
        manage
          ? {
              event: "*",
              schema: "public",
              table: "notifications",
            }
          : {
              event: "*",
              schema: "public",
              table: "notifications",
              filter: `uzivatel_id=eq.${user.id}`,
            },
        () => {
          load();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user.id, manage]);

  useEffect(() => {
    loadProfiles();
  }, [user?.id, manage]);

  useEffect(() => {
    return () => {
      if (imagePreview) URL.revokeObjectURL(imagePreview);
      if (editImagePreview) URL.revokeObjectURL(editImagePreview);
    };
  }, [imagePreview, editImagePreview]);

  async function enableBrowserNotifications() {
    if (
      typeof window === "undefined" ||
      !("Notification" in window)
    ) {
      setError("Tento prohlížeč nepodporuje systémová oznámení.");
      return;
    }

    try {
      const permission = await window.Notification.requestPermission();
      setBrowserPermission(permission);

      if (permission === "granted") {
        setSuccess("Systémová oznámení byla zapnuta.");
        setError("");
      } else if (permission === "denied") {
        setError(
          "Oznámení jsou v prohlížeči zakázaná. Povol je v nastavení webu."
        );
      }
    } catch (permissionError) {
      setError(
        permissionError?.message ||
          "Nepodařilo se požádat o povolení oznámení."
      );
    }
  }

  async function markAll() {
    setError("");

    const { error: markError } = await supabase.rpc(
      "mark_my_notifications_read"
    );

    if (markError) {
      setError(markError.message);
      return;
    }

    await load();
  }

  async function confirmNotification(notification) {
    if (!isDriver) return;

    setError("");
    setSuccess("");
    setBusyId(notification.id);

    const { error: confirmError } = await supabase.rpc(
      "confirm_notification",
      {
        p_notification_id: notification.id,
      }
    );

    if (confirmError) {
      setError(`Potvrzení se nepodařilo uložit: ${confirmError.message}`);
      setBusyId(null);
      return;
    }

    setSuccess("Zpráva byla potvrzena.");
    await load();
    setBusyId(null);
  }

  function validateImage(file) {
    if (!file) return null;

    const allowedTypes = ["image/jpeg", "image/png", "image/webp"];

    if (!allowedTypes.includes(file.type)) {
      return "Fotka musí být JPG, PNG nebo WebP.";
    }

    if (file.size > 5 * 1024 * 1024) {
      return "Fotka může mít maximálně 5 MB.";
    }

    return null;
  }

  function chooseImage(event) {
    setError("");

    const file = event.target.files?.[0] || null;

    if (!file) {
      if (imagePreview) URL.revokeObjectURL(imagePreview);
      setImageFile(null);
      setImagePreview("");
      return;
    }

    const validationError = validateImage(file);

    if (validationError) {
      event.target.value = "";
      setError(validationError);
      return;
    }

    if (imagePreview) URL.revokeObjectURL(imagePreview);

    setImageFile(file);
    setImagePreview(URL.createObjectURL(file));
  }

  function chooseEditImage(event) {
    setError("");

    const file = event.target.files?.[0] || null;

    if (!file) {
      if (editImagePreview) URL.revokeObjectURL(editImagePreview);
      setEditImageFile(null);
      setEditImagePreview("");
      return;
    }

    const validationError = validateImage(file);

    if (validationError) {
      event.target.value = "";
      setError(validationError);
      return;
    }

    if (editImagePreview) URL.revokeObjectURL(editImagePreview);

    setEditImageFile(file);
    setEditImagePreview(URL.createObjectURL(file));
    setEditRemoveImage(false);
  }

  function removeSelectedImage() {
    if (imagePreview) URL.revokeObjectURL(imagePreview);
    setImageFile(null);
    setImagePreview("");
  }

  function resetEditImage() {
    if (editImagePreview) URL.revokeObjectURL(editImagePreview);
    setEditImageFile(null);
    setEditImagePreview("");
    setEditRemoveImage(false);
  }

  async function uploadFile(file) {
    if (!file) {
      return { publicUrl: null, path: null };
    }

    const extension =
      file.name.split(".").pop()?.toLowerCase().replace(/[^a-z0-9]/g, "") ||
      "jpg";

    const path = `${user.id}/${Date.now()}-${Math.random()
      .toString(36)
      .slice(2, 10)}.${extension}`;

    const { error: uploadError } = await supabase.storage
      .from("notification-images")
      .upload(path, file, {
        cacheControl: "3600",
        upsert: false,
        contentType: file.type,
      });

    if (uploadError) {
      throw new Error(`Nahrání fotky selhalo: ${uploadError.message}`);
    }

    const { data } = supabase.storage
      .from("notification-images")
      .getPublicUrl(path);

    if (!data?.publicUrl) {
      throw new Error("Nepodařilo se získat veřejnou URL nahrané fotky.");
    }

    return {
      publicUrl: data.publicUrl,
      path,
    };
  }

  function getStoragePathFromUrl(url) {
    if (!url) return null;

    const marker = "/notification-images/";
    const index = String(url).indexOf(marker);

    if (index === -1) return null;

    return decodeURIComponent(String(url).slice(index + marker.length));
  }

  async function removeUnusedImage(imageUrl) {
    if (!imageUrl) return;

    const { count, error: countError } = await supabase
      .from("notifications")
      .select("id", { count: "exact", head: true })
      .eq("image_url", imageUrl);

    if (countError || Number(count || 0) > 0) {
      return;
    }

    const path = getStoragePathFromUrl(imageUrl);

    if (path) {
      await supabase.storage.from("notification-images").remove([path]);
    }
  }

  async function sendNotification(event) {
    event.preventDefault();

    setError("");
    setSuccess("");

    if (!manage) {
      setError("K odesílání notifikací nemáš oprávnění.");
      return;
    }

    if (!recipientId) {
      setError("Vyber příjemce.");
      return;
    }

    const cleanMessage = message.trim();

    if (!cleanMessage) {
      setError("Napiš zprávu notifikace.");
      return;
    }

    setSending(true);

    let uploadedPath = null;

    try {
      const { publicUrl, path } = await uploadFile(imageFile);
      uploadedPath = path;

      const recipients =
        recipientId === "__all__"
          ? profiles.map((profile) => profile.id)
          : [recipientId];

      if (recipients.length === 0) {
        throw new Error("Nebyl nalezen žádný příjemce.");
      }

      const payload = recipients.map((id) => ({
        uzivatel_id: id,
        odesilatel_id: user.id,
        typ: notificationType || "OBECNÁ",
        zprava: cleanMessage,
        image_url: publicUrl,
        precteno: false,
        vyzaduje_potvrzeni: requiresConfirmation,
        potvrzeno: false,
        potvrzeno_at: null,
      }));

      const { error: insertError } = await supabase
        .from("notifications")
        .insert(payload);

      if (insertError) {
        if (uploadedPath) {
          await supabase.storage
            .from("notification-images")
            .remove([uploadedPath]);
        }

        throw new Error(`Odeslání notifikace selhalo: ${insertError.message}`);
      }

      setSuccess(
        recipientId === "__all__"
          ? `Notifikace byla odeslána ${recipients.length} uživatelům.`
          : "Notifikace byla odeslána."
      );

      setRecipientId("");
      setNotificationType("OBECNÁ");
      setMessage("");
      setRequiresConfirmation(true);
      removeSelectedImage();

      await load();
    } catch (sendError) {
      setError(sendError?.message || "Notifikaci se nepodařilo odeslat.");
    } finally {
      setSending(false);
    }
  }

  function startEditGroup(group) {
    const notification = group.first;

    setError("");
    setSuccess("");

    resetEditImage();
    setEditingId(group.key);
    setEditType(notification.typ || "OBECNÁ");
    setEditMessage(notification.zprava || "");
    setEditRequiresConfirmation(
      notification.vyzaduje_potvrzeni !== false
    );
  }

  function cancelEdit() {
    resetEditImage();
    setEditingId(null);
    setEditType("OBECNÁ");
    setEditMessage("");
    setEditRequiresConfirmation(true);
  }

  async function saveEditGroup(group) {
    if (!manage) return;

    const cleanMessage = editMessage.trim();

    if (!cleanMessage) {
      setError("Zpráva nesmí být prázdná.");
      return;
    }

    setError("");
    setSuccess("");
    setBusyId(group.key);

    const ids = group.items.map((notification) => notification.id);
    const oldImageUrl = group.first.image_url || null;
    let newUploadedPath = null;

    try {
      let nextImageUrl = oldImageUrl;

      if (editImageFile) {
        const uploaded = await uploadFile(editImageFile);
        nextImageUrl = uploaded.publicUrl;
        newUploadedPath = uploaded.path;
      } else if (editRemoveImage) {
        nextImageUrl = null;
      }

      const { error: updateError } = await supabase
        .from("notifications")
        .update({
          typ: editType || "OBECNÁ",
          zprava: cleanMessage,
          image_url: nextImageUrl,
          vyzaduje_potvrzeni: editRequiresConfirmation,
          potvrzeno: false,
          potvrzeno_at: null,
          precteno: false,
          updated_at: new Date().toISOString(),
        })
        .in("id", ids);

      if (updateError) {
        if (newUploadedPath) {
          await supabase.storage
            .from("notification-images")
            .remove([newUploadedPath]);
        }

        throw new Error(`Úprava notifikace selhala: ${updateError.message}`);
      }

      if (oldImageUrl && oldImageUrl !== nextImageUrl) {
        await removeUnusedImage(oldImageUrl);
      }

      setSuccess(
        `Rozesílka byla upravena pro ${ids.length} příjemců. Potvrzení byla vynulována.`
      );

      cancelEdit();
      await load();
    } catch (editError) {
      setError(editError?.message || "Notifikaci se nepodařilo upravit.");
    } finally {
      setBusyId(null);
    }
  }

  async function deleteNotificationGroup(group) {
    if (!manage) return;

    const count = group.items.length;

    const confirmed = window.confirm(
      `Opravdu chceš smazat celou tuto rozesílku pro ${count} ${
        count === 1 ? "příjemce" : "příjemců"
      }?`
    );

    if (!confirmed) return;

    setError("");
    setSuccess("");
    setBusyId(group.key);

    const ids = group.items.map((notification) => notification.id);
    const imageUrl = group.first.image_url || null;

    const { error: deleteError } = await supabase
      .from("notifications")
      .delete()
      .in("id", ids);

    if (deleteError) {
      setError(`Smazání notifikace selhalo: ${deleteError.message}`);
      setBusyId(null);
      return;
    }

    if (imageUrl) {
      await removeUnusedImage(imageUrl);
    }

    if (editingId === group.key) {
      cancelEdit();
    }

    setSuccess(`Celá rozesílka byla smazána (${count} příjemců).`);
    await load();
    setBusyId(null);
  }

  return (
    <div className="notifications-page">
      <div className="topbar">
        <div>
          <div className="notifications-eyebrow">CENTRUM OZNÁMENÍ</div>
          <h1>Notifikace</h1>
          <p>Zprávy, oznámení a potvrzení řidičů.</p>
        </div>

        <div className="notification-topbar-actions">
          {browserPermission !== "unsupported" && (
            <button
              type="button"
              className={
                browserPermission === "granted"
                  ? "secondary-button notification-browser-enabled"
                  : "primary-button"
              }
              onClick={enableBrowserNotifications}
              disabled={browserPermission === "granted"}
            >
              {browserPermission === "granted"
                ? "✓ Oznámení zapnutá"
                : browserPermission === "denied"
                ? "🔕 Oznámení zakázaná"
                : "🔔 Zapnout oznámení"}
            </button>
          )}

          <button
            type="button"
            className="secondary-button"
            onClick={markAll}
          >
            ✓ Označit vše jako přečtené
          </button>
        </div>
      </div>

      {error && (
        <div className="request-alert request-alert-error">
          <span className="request-alert-icon">!</span>
          <div>
            <strong>Chyba</strong>
            <div>{error}</div>
          </div>
        </div>
      )}

      {success && (
        <div className="request-alert request-alert-success">
          <span className="request-alert-icon">✓</span>
          <div>
            <strong>Hotovo</strong>
            <div>{success}</div>
          </div>
        </div>
      )}

      {manage && (
        <div className="notification-compose-card">
          <div className="notification-compose-heading">
            <div>
              <span className="notification-compose-icon">🔔</span>
              <div>
                <h2>Odeslat notifikaci</h2>
                <p>
                  Vyber příjemce, typ zprávy, text a případně fotografii.
                </p>
              </div>
            </div>
          </div>

          <form onSubmit={sendNotification}>
            <div className="notification-compose-grid">
              <div className="notification-field">
                <label>Příjemce</label>
                <select
                  value={recipientId}
                  onChange={(e) => setRecipientId(e.target.value)}
                  required
                >
                  <option value="">Vyber příjemce…</option>
                  <option value="__all__">📢 Všichni uživatelé</option>

                  {profiles.map((profile) => (
                    <option key={profile.id} value={profile.id}>
                      {profile.jmeno || profile.id} — {getRoleName(profile)}
                    </option>
                  ))}
                </select>
              </div>

              <div className="notification-field">
                <label>Typ notifikace</label>
                <select
                  value={notificationType}
                  onChange={(e) => setNotificationType(e.target.value)}
                >
                  {notificationTypes.map((type) => (
                    <option key={type} value={type}>
                      {type}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="notification-field">
              <label>Zpráva</label>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Napiš text notifikace…"
                rows={5}
                required
              />
            </div>

            <label className="notification-confirm-switch">
              <input
                type="checkbox"
                checked={requiresConfirmation}
                onChange={(e) => setRequiresConfirmation(e.target.checked)}
              />
              <span className="notification-switch-ui" />
              <span>
                <strong>Vyžadovat potvrzení řidičem</strong>
                <small>
                  Řidič bude muset kliknout na „Potvrzuji převzetí“.
                </small>
              </span>
            </label>

            <div className="notification-upload-box">
              <div className="notification-upload-top">
                <div>
                  <strong>📷 Fotka</strong>
                  <span>JPG, PNG nebo WebP · maximálně 5 MB</span>
                </div>

                <label className="notification-file-button">
                  Vybrat fotku
                  <input
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    onChange={chooseImage}
                  />
                </label>
              </div>

              {imagePreview && (
                <div className="notification-image-preview-wrap">
                  <img
                    src={imagePreview}
                    alt="Náhled vybrané fotky"
                    className="notification-image-preview"
                  />

                  <button
                    type="button"
                    className="notification-remove-image"
                    onClick={removeSelectedImage}
                  >
                    ✕ Odebrat fotku
                  </button>
                </div>
              )}
            </div>

            <div className="notification-compose-actions">
              <button
                type="submit"
                className="primary-button"
                disabled={sending}
              >
                {sending ? "Odesílám…" : "📨 Odeslat notifikaci"}
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="notification-section-heading">
        <div>
          <h2>Moje notifikace</h2>
          <p>Zprávy určené pro tebe.</p>
        </div>
      </div>

      <div className="notifications-list">
        {items.length === 0 ? (
          <div className="notification-empty">
            <div>🔔</div>
            <strong>Žádné notifikace</strong>
            <span>Až se něco stane, zobrazí se to tady.</span>
          </div>
        ) : (
          items.map((notification) => (
            <article
              className={`notification-card ${
                notification.precteno ? "" : "unread"
              }`}
              key={notification.id}
            >
              <div className="notification-card-header">
                <div>
                  <span className="notification-type">
                    {notification.typ || "OZNÁMENÍ"}
                  </span>

                  <small>
                    {notification.created_at
                      ? new Date(notification.created_at).toLocaleString("cs-CZ")
                      : "—"}
                    {notification.updated_at
                      ? ` · upraveno ${new Date(
                          notification.updated_at
                        ).toLocaleString("cs-CZ")}`
                      : ""}
                  </small>
                </div>

                {!notification.precteno && (
                  <span className="notification-unread-badge">NOVÉ</span>
                )}
              </div>

              <div className="notification-sender">
                <span className="notification-sender-avatar">👤</span>
                <span>
                  Odeslal: <strong>{getSenderName(notification)}</strong>
                </span>
              </div>

              <div className="notification-message">
                {notification.zprava}
              </div>

              {notification.image_url && (
                <a
                  href={notification.image_url}
                  target="_blank"
                  rel="noreferrer"
                  className="notification-image-link"
                  title="Otevřít fotku v plné velikosti"
                >
                  <img
                    src={notification.image_url}
                    alt="Fotka v notifikaci"
                    className="notification-image"
                    loading="lazy"
                  />
                </a>
              )}

              {isDriver && notification.vyzaduje_potvrzeni && (
                <div className="notification-confirm-area">
                  {notification.potvrzeno ? (
                    <div className="notification-confirmed">
                      ✓ Potvrzeno
                      {notification.potvrzeno_at
                        ? ` · ${new Date(
                            notification.potvrzeno_at
                          ).toLocaleString("cs-CZ")}`
                        : ""}
                    </div>
                  ) : (
                    <button
                      type="button"
                      className="notification-confirm-button"
                      disabled={busyId === notification.id}
                      onClick={() => confirmNotification(notification)}
                    >
                      {busyId === notification.id
                        ? "Ukládám…"
                        : "✓ Potvrzuji převzetí"}
                    </button>
                  )}
                </div>
              )}
            </article>
          ))
        )}
      </div>

      {manage && (
        <>
          <div className="notification-section-heading notification-sent-heading">
            <div>
              <h2>Odeslané notifikace</h2>
              <p>
                Jedna rozesílka je teď vždy jedna karta. Úprava i smazání se
                provedou všem příjemcům najednou.
              </p>
            </div>
          </div>

          <div className="notifications-list">
            {sentGroups.length === 0 ? (
              <div className="notification-empty">
                <div>📨</div>
                <strong>Zatím nic odesláno</strong>
                <span>Ručně odeslané notifikace se zobrazí tady.</span>
              </div>
            ) : (
              sentGroups.map((group) => {
                const notification = group.first;
                const editing = editingId === group.key;
                const busy = busyId === group.key;
                const confirmation = getGroupConfirmation(group);

                return (
                  <article
                    className="notification-card notification-sent-card"
                    key={group.key}
                  >
                    <div className="notification-card-header">
                      <div>
                        <span className="notification-type">
                          {notification.typ || "OZNÁMENÍ"}
                        </span>

                        <small>
                          {notification.created_at
                            ? new Date(
                                notification.created_at
                              ).toLocaleString("cs-CZ")
                            : "—"}
                          {" · "}
                          {group.items.length}{" "}
                          {group.items.length === 1
                            ? "příjemce"
                            : "příjemců"}
                        </small>
                      </div>

                      <span
                        className={`notification-confirm-state ${
                          confirmation.confirmed ? "confirmed" : "waiting"
                        }`}
                      >
                        {confirmation.label}
                      </span>
                    </div>

                    <div className="notification-sent-meta-row">
                      <div className="notification-sender">
                        <span className="notification-sender-avatar">👤</span>
                        <span>
                          Odeslal:{" "}
                          <strong>{getSenderName(notification)}</strong>
                        </span>
                      </div>

                      <div className="notification-recipient-summary">
                        <strong>Příjemci:</strong>{" "}
                        {getGroupRecipientNames(group)}
                      </div>
                    </div>

                    {editing ? (
                      <div className="notification-edit-box">
                        <div className="notification-compose-grid">
                          <div className="notification-field">
                            <label>Typ</label>
                            <select
                              value={editType}
                              onChange={(e) => setEditType(e.target.value)}
                            >
                              {notificationTypes.map((type) => (
                                <option key={type} value={type}>
                                  {type}
                                </option>
                              ))}
                            </select>
                          </div>

                          <div className="notification-field">
                            <label>Potvrzení</label>
                            <select
                              value={
                                editRequiresConfirmation ? "ANO" : "NE"
                              }
                              onChange={(e) =>
                                setEditRequiresConfirmation(
                                  e.target.value === "ANO"
                                )
                              }
                            >
                              <option value="ANO">
                                Vyžadovat potvrzení řidičem
                              </option>
                              <option value="NE">
                                Potvrzení nevyžadovat
                              </option>
                            </select>
                          </div>
                        </div>

                        <div className="notification-field">
                          <label>Zpráva</label>
                          <textarea
                            value={editMessage}
                            onChange={(e) => setEditMessage(e.target.value)}
                            rows={4}
                          />
                        </div>

                        {notification.image_url &&
                          !editRemoveImage &&
                          !editImagePreview && (
                            <div className="notification-current-image">
                              <img
                                src={notification.image_url}
                                alt="Současná fotka"
                              />
                              <button
                                type="button"
                                className="notification-remove-image"
                                onClick={() => setEditRemoveImage(true)}
                              >
                                🗑️ Odebrat současnou fotku
                              </button>
                            </div>
                          )}

                        {editImagePreview && (
                          <div className="notification-current-image">
                            <img
                              src={editImagePreview}
                              alt="Nová fotka"
                            />
                            <button
                              type="button"
                              className="notification-remove-image"
                              onClick={resetEditImage}
                            >
                              ✕ Zrušit novou fotku
                            </button>
                          </div>
                        )}

                        <label className="notification-file-button notification-edit-file">
                          📷 Vybrat novou fotku
                          <input
                            type="file"
                            accept="image/jpeg,image/png,image/webp"
                            onChange={chooseEditImage}
                          />
                        </label>

                        <div className="notification-edit-actions">
                          <button
                            type="button"
                            className="primary-button"
                            disabled={busy}
                            onClick={() => saveEditGroup(group)}
                          >
                            {busy
                              ? "Ukládám…"
                              : `💾 Uložit všem (${group.items.length})`}
                          </button>

                          <button
                            type="button"
                            className="secondary-button"
                            disabled={busy}
                            onClick={cancelEdit}
                          >
                            Zrušit
                          </button>
                        </div>
                      </div>
                    ) : (
                      <>
                        <div className="notification-message">
                          {notification.zprava}
                        </div>

                        {notification.image_url && (
                          <a
                            href={notification.image_url}
                            target="_blank"
                            rel="noreferrer"
                            className="notification-image-link"
                          >
                            <img
                              src={notification.image_url}
                              alt="Fotka v notifikaci"
                              className="notification-image"
                              loading="lazy"
                            />
                          </a>
                        )}

                        <div className="notification-admin-actions">
                          <button
                            type="button"
                            className="secondary-button"
                            disabled={busy}
                            onClick={() => startEditGroup(group)}
                          >
                            ✏️ Upravit celou rozesílku
                          </button>

                          <button
                            type="button"
                            className="delete-button"
                            disabled={busy}
                            onClick={() => deleteNotificationGroup(group)}
                          >
                            🗑️ Smazat celou rozesílku
                          </button>
                        </div>
                      </>
                    )}
                  </article>
                );
              })
            )}
          </div>
        </>
      )}

    </div>
  );
}

function VehicleReleaseRequests({ user, profile, adminMode=false }) {
  const [rows,setRows]=useState([]),[vehicles,setVehicles]=useState([]),[error,setError]=useState(""),[success,setSuccess]=useState("");
  async function load(){ setError(""); const rq=await supabase.from("vehicle_release_requests").select("*").order("created_at",{ascending:false}); const vz=await supabase.from("vozy").select("id,cislo,ridic_1,ridic_2,ridic_1_pridelen_at,ridic_2_pridelen_at"); if(rq.error)setError(rq.error.message); setRows(adminMode?(rq.data||[]):((rq.data||[]).filter(x=>x.uzivatel_id===user.id))); setVehicles(vz.data||[]); }
  useEffect(()=>{load();},[user.id,adminMode]);
  const myName=(profile?.jmeno||"").trim();
  function eligible(v){ const d=v.ridic_1===myName?v.ridic_1_pridelen_at:v.ridic_2===myName?v.ridic_2_pridelen_at:null; return d && new Date() >= new Date(new Date(d).setMonth(new Date(d).getMonth()+3)); }
  async function requestRelease(v){ if(!eligible(v)){setError("O odevzdání lze požádat až po 3 měsících od přidělení.");return;} const active=rows.some(r=>r.vuz_id===v.id&&r.uzivatel_id===user.id&&r.stav==="ČEKÁ NA VYŘÍZENÍ"); if(active){setError("Žádost o odevzdání už čeká na vyřízení.");return;} const {error}=await supabase.from("vehicle_release_requests").insert({uzivatel_id:user.id,vuz_id:v.id,stav:"ČEKÁ NA VYŘÍZENÍ"}); if(error)setError(error.message); else {setSuccess("Žádost o odevzdání byla odeslána.");load();} }
  async function decide(r,stav){ const v=vehicles.find(x=>x.id===r.vuz_id); if(stav==="SCHVÁLENO"&&v){ const name=v.ridic_1===myName&&r.uzivatel_id===user.id?myName:null; const {data:p}=await supabase.from("profiles").select("jmeno").eq("id",r.uzivatel_id).maybeSingle(); const n=(p?.jmeno||name||"").trim(); let payload={}; if(v.ridic_1===n) payload={ridic_1:v.ridic_2||null,ridic_1_pridelen_at:v.ridic_2? v.ridic_2_pridelen_at:null,ridic_2:null,ridic_2_pridelen_at:null}; else if(v.ridic_2===n) payload={ridic_2:null,ridic_2_pridelen_at:null}; if(Object.keys(payload).length) await supabase.from("vozy").update(payload).eq("id",v.id); await supabase.from("vehicle_history").insert({vuz_id:v.id,uzivatel_id:r.uzivatel_id,typ:"RIDIC_ODEBRAN",popis:`${n} odevzdal vůz.`}); } await supabase.from("vehicle_release_requests").update({stav,vyrizeno_at:new Date().toISOString()}).eq("id",r.id); await supabase.from("notifications").insert({uzivatel_id:r.uzivatel_id,typ:"ODEVZDANI_VOZU",zprava:`Žádost o odevzdání vozu byla změněna na ${stav}.`}); load(); }
  const assigned=vehicles.filter(v=>v.ridic_1===myName||v.ridic_2===myName);
  return <div><div className="topbar"><div><h1>Odevzdání vozu</h1><p>Žádost je možná po 3 měsících od přidělení</p></div></div>{error&&<div className="error-box">{error}</div>}{success&&<div className="success-box">{success}</div>}{!adminMode&&<div className="panel"><h2>Přidělené vozy</h2>{assigned.length===0?<div className="empty">Nemáš přidělený vůz.</div>:assigned.map(v=><div className="simple-list-item" key={v.id}><strong>Vůz {v.cislo}</strong><button className="primary-button" disabled={!eligible(v)} onClick={()=>requestRelease(v)}>{eligible(v)?"Požádat o odevzdání":"Ještě neuplynuly 3 měsíce"}</button></div>)}</div>}<div className="panel"><h2>{adminMode?"Žádosti k vyřízení":"Moje žádosti"}</h2>{rows.length===0?<div className="empty">Žádné žádosti.</div>:rows.map(r=><div className="simple-list-item" key={r.id}><div><strong>Vůz {vehicles.find(v=>v.id===r.vuz_id)?.cislo||r.vuz_id}</strong><div>{r.stav}</div></div>{adminMode&&<select value={r.stav} onChange={e=>decide(r,e.target.value)}><option>ČEKÁ NA VYŘÍZENÍ</option><option>SCHVÁLENO</option><option>ZAMÍTNUTO</option></select>}</div>)}</div></div>;
}

function VehicleFaults({ user, role }) {
 const manage=canManageVehicles(role); const [rows,setRows]=useState([]),[vehicles,setVehicles]=useState([]),[form,setForm]=useState({vuz_id:"",nazev:"",popis:"",zavaznost:"BĚŽNÁ"}),[error,setError]=useState("");
 async function load(){const [a,b]=await Promise.all([supabase.from("vehicle_faults").select("*").order("created_at",{ascending:false}),supabase.from("vozy").select("id,cislo").order("cislo")]); if(a.error)setError(a.error.message); setRows(a.data||[]);setVehicles(b.data||[])} useEffect(()=>{load()},[]);
 async function add(e){e.preventDefault();const {error}=await supabase.from("vehicle_faults").insert({...form,vuz_id:Number(form.vuz_id),uzivatel_id:user.id});if(error)setError(error.message);else{await supabase.from("vehicle_history").insert({vuz_id:Number(form.vuz_id),uzivatel_id:user.id,typ:"ZAVADA",popis:`Nahlášena závada: ${form.nazev}`});setForm({vuz_id:"",nazev:"",popis:"",zavaznost:"BĚŽNÁ"});load()}}
 async function status(r,stav){await supabase.from("vehicle_faults").update({stav,vyreseno_at:stav==="OPRAVENO"?new Date().toISOString():null}).eq("id",r.id);load()}
 return <div><div className="topbar"><div><h1>Závady vozů</h1><p>Evidence a řešení závad</p></div></div>{error&&<div className="error-box">{error}</div>}<div className="panel"><h2>Nahlásit závadu</h2><form onSubmit={add} className="form-grid"><select value={form.vuz_id} onChange={e=>setForm({...form,vuz_id:e.target.value})} required><option value="">Vyber vůz</option>{vehicles.map(v=><option key={v.id} value={v.id}>Vůz {v.cislo}</option>)}</select><input placeholder="Název závady" value={form.nazev} onChange={e=>setForm({...form,nazev:e.target.value})} required/><select value={form.zavaznost} onChange={e=>setForm({...form,zavaznost:e.target.value})}><option>BĚŽNÁ</option><option>VÁŽNÁ</option><option>KRITICKÁ</option></select><input placeholder="Popis" value={form.popis} onChange={e=>setForm({...form,popis:e.target.value})}/><button className="primary-button">Nahlásit</button></form></div><div className="panel simple-list">{rows.map(r=><div className="simple-list-item" key={r.id}><div><strong>Vůz {vehicles.find(v=>v.id===r.vuz_id)?.cislo||r.vuz_id} · {r.nazev}</strong><div>{r.zavaznost} · {r.popis||"Bez popisu"}</div></div>{manage?<select value={r.stav} onChange={e=>status(r,e.target.value)}><option>NOVÁ</option><option>ŘEŠÍ SE</option><option>OPRAVENO</option></select>:<strong>{r.stav}</strong>}</div>)}</div></div>
}


function AdminCourses() {
  const { provozovny } = useProvozovny();

  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [editing, setEditing] = useState(null);
  const [search, setSearch] = useState("");
  const [filterProvozovna, setFilterProvozovna] = useState("");
  const [form, setForm] = useState({
    nazev: "",
    provozovna_id: "",
    typ_dne: "",
    varianta: "",
    typ_vozu: "",
    zacatek: "",
    konec: "",
  });

  async function loadCourses() {
    setLoading(true);
    setError("");

    const { data, error: loadError } = await supabase
      .from("kurzy")
      .select("id, nazev, provozovna_id, aktivni, typ_dne, varianta, typ_vozu, zacatek, konec, created_at")
      .order("nazev", { ascending: true });

    if (loadError) {
      setError(getDkvSaveError(loadError));
      setCourses([]);
    } else {
      setCourses(data || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadCourses();
  }, []);

  function resetForm() {
    setEditing(null);
    setForm({ nazev: "", provozovna_id: "", typ_dne: "", varianta: "", typ_vozu: "", zacatek: "", konec: "" });
  }

  async function saveCourse(e) {
    e.preventDefault();

    setSaving(true);
    setError("");
    setSuccess("");

    const name = form.nazev.trim();

    if (!name || !form.provozovna_id) {
      setError("Vyplň název kurzu a provozovnu.");
      setSaving(false);
      return;
    }

    const payload = {
      nazev: name,
      provozovna_id: Number(form.provozovna_id),
      aktivni: true,
      typ_dne: form.typ_dne || null,
      varianta: form.varianta || null,
      typ_vozu: form.typ_vozu || null,
      zacatek: form.zacatek || null,
      konec: form.konec || null,
    };

    const result = editing
      ? await supabase
          .from("kurzy")
          .update(payload)
          .eq("id", editing.id)
      : await supabase.from("kurzy").insert(payload);

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(editing ? "Kurz byl upraven." : "Kurz byl přidán.");
    resetForm();
    await loadCourses();
    setSaving(false);
  }

  async function toggleCourse(course) {
    setError("");
    setSuccess("");

    const { error: updateError } = await supabase
      .from("kurzy")
      .update({ aktivni: !course.aktivni })
      .eq("id", course.id);

    if (updateError) {
      setError(updateError.message);
      return;
    }

    setSuccess(course.aktivni ? "Kurz byl deaktivován." : "Kurz byl aktivován.");
    await loadCourses();
  }

  async function deleteCourse(course) {
    if (
      !window.confirm(
        `Opravdu chceš smazat kurz ${course.nazev}?`
      )
    ) {
      return;
    }

    setError("");
    setSuccess("");

    const { error: deleteError } = await supabase
      .from("kurzy")
      .delete()
      .eq("id", course.id);

    if (deleteError) {
      setError(
        deleteError.message.includes("foreign key")
          ? "Kurz už je použitý ve výpravách. Místo smazání ho deaktivuj."
          : deleteError.message
      );
      return;
    }

    setSuccess("Kurz byl smazán.");
    await loadCourses();
  }

  function getProvozovnaName(id) {
    return (
      provozovny.find(
        (provozovna) => String(provozovna.id) === String(id)
      )?.nazev || "-"
    );
  }

  const query = search.trim().toLowerCase();

  const filtered = courses.filter((course) => {
    if (
      filterProvozovna &&
      String(course.provozovna_id) !== String(filterProvozovna)
    ) {
      return false;
    }

    if (!query) return true;

    return `${course.nazev} ${getProvozovnaName(
      course.provozovna_id
    )}`
      .toLowerCase()
      .includes(query);
  });

  const filteredWorkdayCourses = filtered.filter(
    (course) => course.typ_dne === "PD"
  );

  const filteredWeekendCourses = filtered.filter(
    (course) => course.typ_dne === "VIKEND"
  );

  const filteredSundayCourses = filtered.filter(
    (course) => course.typ_dne === "NE"
  );

  const filteredDailyCourses = filtered.filter(
    (course) => course.typ_dne === "DENNE"
  );

  const filteredOtherCourses = filtered.filter(
    (course) => !course.typ_dne
  );

  function renderCourseItem(course) {
    return (
      <div
        className={`course-admin-item ${
          course.aktivni ? "" : "inactive"
        }`}
        key={course.id}
      >
        <div>
          <strong>{course.nazev}</strong>
          <span>
            {getProvozovnaName(course.provozovna_id)}
            {course.typ_dne
              ? ` · ${getCourseDayLabel(course.typ_dne)}`
              : ""}
            {course.varianta
              ? ` · ${getCourseVariantLabel(course.varianta)}`
              : ""}
            {course.typ_vozu
              ? ` · ${course.typ_vozu === "SOLO" ? "Sólo" : "Kloub"}`
              : ""}
            {course.zacatek || course.konec
              ? ` · ${course.zacatek ? String(course.zacatek).slice(0, 5) : "—"}–${course.konec ? String(course.konec).slice(0, 5) : "—"}`
              : ""}
          </span>
        </div>

        <span
          className={`course-active-badge ${
            course.aktivni ? "active" : "inactive"
          }`}
        >
          {course.aktivni ? "AKTIVNÍ" : "NEAKTIVNÍ"}
        </span>

        <div className="course-admin-actions">
          <button
            type="button"
            className="secondary-button"
            onClick={() => {
              setEditing(course);
              setForm({
                nazev: course.nazev,
                provozovna_id:
                  course.provozovna_id || "",
                typ_dne: course.typ_dne || "",
                varianta: course.varianta || "",
                typ_vozu: course.typ_vozu || "",
                zacatek: course.zacatek
                  ? String(course.zacatek).slice(0, 5)
                  : "",
                konec: course.konec
                  ? String(course.konec).slice(0, 5)
                  : "",
              });
              window.scrollTo({
                top: 0,
                behavior: "smooth",
              });
            }}
          >
            ✏️ Upravit
          </button>

          <button
            type="button"
            className="secondary-button"
            onClick={() => toggleCourse(course)}
          >
            {course.aktivni
              ? "⏸ Deaktivovat"
              : "▶ Aktivovat"}
          </button>

          <button
            type="button"
            className="delete-button"
            onClick={() => deleteCourse(course)}
          >
            🗑️ Smazat
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Kurzy</h1>
          <p>Číselník pořadí podle provozoven</p>
        </div>

        <div className="profile-badge">
          {courses.length} KURZŮ
        </div>
      </div>

      {error && (
        <div className="error-box">
          <strong>Chyba:</strong>
          <br />
          {error}
        </div>
      )}

      {success && <div className="success-box">{success}</div>}

      <div className="course-admin-layout">
        <div className="panel">
          <h2>{editing ? "✏️ Upravit pořadí" : "➕ Přidat pořadí"}</h2>

          <form onSubmit={saveCourse}>
            <div className="form-grid">
              <div>
                <label>Název pořadí</label>
                <input
                  value={form.nazev}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      nazev: e.target.value,
                    })
                  }
                  placeholder="Např. MHDCL1, 53.01, 349101..."
                  required
                />
              </div>

              <div>
                <label>Provozovna</label>
                <select
                  value={form.provozovna_id}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      provozovna_id: e.target.value,
                    })
                  }
                  required
                >
                  <option value="">Vyber provozovnu</option>
                  {provozovny.map((provozovna) => (
                    <option
                      key={provozovna.id}
                      value={provozovna.id}
                    >
                      {provozovna.nazev}
                      {provozovna.kod
                        ? ` (${provozovna.kod})`
                        : ""}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label>Typ dne</label>
                <select
                  value={form.typ_dne}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      typ_dne: e.target.value,
                    })
                  }
                >
                  <option value="">Bez omezení dne</option>
                  <option value="PD">Pracovní den (Po–Pá)</option>
                  <option value="VIKEND">Víkend (So–Ne)</option>
                  <option value="NE">Pouze neděle</option>
                  <option value="DENNE">Každý den (Po–Ne)</option>
                </select>
              </div>

              <div>
                <label>Režim provozu</label>
                <select
                  value={form.varianta}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      varianta: e.target.value,
                    })
                  }
                >
                  <option value="">Bez varianty</option>
                  <option value="BEZNY">Běžný provoz</option>
                  <option value="PRAZDNINY">Prázdniny</option>
                </select>
              </div>

              <div>
                <label>Typ vozu</label>
                <select
                  value={form.typ_vozu}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      typ_vozu: e.target.value,
                    })
                  }
                >
                  <option value="">Bez omezení</option>
                  <option value="SOLO">Sólo</option>
                  <option value="KLOUB">Kloub</option>
                </select>
              </div>

              <div>
                <label>Začátek</label>
                <input
                  type="time"
                  value={form.zacatek || ""}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      zacatek: e.target.value,
                    })
                  }
                />
              </div>

              <div>
                <label>Konec</label>
                <input
                  type="time"
                  value={form.konec || ""}
                  onChange={(e) =>
                    setForm({
                      ...form,
                      konec: e.target.value,
                    })
                  }
                />
              </div>
            </div>

            <div className="form-buttons">
              <button
                type="submit"
                className="primary-button"
                disabled={saving}
              >
                {saving
                  ? "Ukládám..."
                  : editing
                  ? "💾 Uložit změny"
                  : "➕ Přidat kurz"}
              </button>

              {editing && (
                <button
                  type="button"
                  className="secondary-button"
                  onClick={resetForm}
                >
                  Zrušit úpravy
                </button>
              )}
            </div>
          </form>
        </div>

        <div className="panel">
          <div className="users-toolbar">
            <div>
              <h2>Seznam kurzů</h2>
              <p className="muted">
                Pořadí se ve Výpravách zobrazí pouze u své provozovny.
              </p>
            </div>
          </div>

          <div className="course-admin-filters">
            <input
              className="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="🔎 Hledat pořadí..."
            />

            <select
              value={filterProvozovna}
              onChange={(e) =>
                setFilterProvozovna(e.target.value)
              }
            >
              <option value="">Všechny provozovny</option>
              {provozovny.map((provozovna) => (
                <option
                  key={provozovna.id}
                  value={provozovna.id}
                >
                  {provozovna.nazev}
                </option>
              ))}
            </select>
          </div>

          {loading ? (
            <div className="empty">Načítání kurzů...</div>
          ) : filtered.length === 0 ? (
            <div className="empty">Žádné kurzy.</div>
          ) : (
            <div className="course-day-sections">
              {filteredWorkdayCourses.length > 0 && (
                <section className="course-day-section workday">
                  <div className="course-day-section-title">
                    <div>
                      <strong>Pracovní den</strong>
                      <span>{filteredWorkdayCourses.length} kurzů</span>
                    </div>
                    <span className="course-day-chip">PD</span>
                  </div>

                  <div className="course-admin-list">
                    {filteredWorkdayCourses.map(renderCourseItem)}
                  </div>
                </section>
              )}

              {filteredWeekendCourses.length > 0 && (
                <section className="course-day-section weekend">
                  <div className="course-day-section-title">
                    <div>
                      <strong>Víkend</strong>
                      <span>{filteredWeekendCourses.length} kurzů</span>
                    </div>
                    <span className="course-day-chip">VÍKEND</span>
                  </div>

                  <div className="course-admin-list">
                    {filteredWeekendCourses.map(renderCourseItem)}
                  </div>
                </section>
              )}

              {filteredSundayCourses.length > 0 && (
                <section className="course-day-section sunday">
                  <div className="course-day-section-title">
                    <div>
                      <strong>Neděle</strong>
                      <span>{filteredSundayCourses.length} kurzů</span>
                    </div>
                    <span className="course-day-chip">NE</span>
                  </div>

                  <div className="course-admin-list">
                    {filteredSundayCourses.map(renderCourseItem)}
                  </div>
                </section>
              )}

              {filteredDailyCourses.length > 0 && (
                <section className="course-day-section daily">
                  <div className="course-day-section-title">
                    <div>
                      <strong>Každý den</strong>
                      <span>{filteredDailyCourses.length} kurzů</span>
                    </div>
                    <span className="course-day-chip">PO–NE</span>
                  </div>

                  <div className="course-admin-list">
                    {filteredDailyCourses.map(renderCourseItem)}
                  </div>
                </section>
              )}

              {filteredOtherCourses.length > 0 && (
                <section className="course-day-section">
                  <div className="course-day-section-title">
                    <div>
                      <strong>Bez omezení dne</strong>
                      <span>{filteredOtherCourses.length} kurzů</span>
                    </div>
                  </div>

                  <div className="course-admin-list">
                    {filteredOtherCourses.map(renderCourseItem)}
                  </div>
                </section>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}






/* =========================================================
   REZERVACE SMĚN
========================================================= */

function ShiftReservations({
  user,
  profile,
  role,
  initialTarget = null,
  onInitialTargetUsed,
}) {
  const { provozovny } = useProvozovny();
  const manage = canManageVehicles(role);

  const [date, setDate] = useState(() => localDateIso(new Date()));
  const [branchId, setBranchId] = useState("");
  const [courses, setCourses] = useState([]);
  const [courseId, setCourseId] = useState("");
  const [connections, setConnections] = useState([]);
  const [occupiedIds, setOccupiedIds] = useState(new Set());
  const [occupiedBy, setOccupiedBy] = useState({});

  const [rangeStart, setRangeStart] = useState(null);
  const [rangeEnd, setRangeEnd] = useState(null);

  const [reservations, setReservations] = useState([]);
  const [reservationCourses, setReservationCourses] = useState({});
  const [reservationProfiles, setReservationProfiles] = useState({});

  const [editingReservation, setEditingReservation] = useState(null);
  const [reservationView, setReservationView] = useState("upcoming");
  const [reservationSection, setReservationSection] = useState("new");

  const [loadingCourses, setLoadingCourses] = useState(false);
  const [loadingConnections, setLoadingConnections] = useState(false);
  const [loadingReservations, setLoadingReservations] = useState(false);
  const [saving, setSaving] = useState(false);

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const mainBranches = getMainProvozovny(provozovny);
  const todayIso = localDateIso(new Date());

  function branchById(value) {
    return provozovny.find(
      (branch) => String(branch.id) === String(value)
    );
  }

  function courseFitsDate(
    course,
    targetDate = date,
    targetBranchId = branchId
  ) {
    if (!targetDate) return true;

    const d = new Date(`${targetDate}T12:00:00`);
    const weekday = d.getDay();
    const weekend = weekday === 0 || weekday === 6;

    if (course.typ_dne === "PD" && weekend) return false;
    if (course.typ_dne === "VIKEND" && !weekend) return false;
    if (course.typ_dne === "NE" && weekday !== 0) return false;

    const branch = branchById(targetBranchId);
    const code = String(branch?.kod || "")
      .trim()
      .toUpperCase();

    if (code === "BRE" && course.varianta) {
      const month = Number(targetDate.split("-")[1]);
      const expectedVariant =
        month === 8 ? "PRAZDNINY" : "BEZNY";

      if (course.varianta !== expectedVariant) {
        return false;
      }
    }

    return true;
  }

  async function loadCourses(
    targetBranchId = branchId,
    targetDate = date
  ) {
    if (!targetBranchId || !targetDate) {
      setCourses([]);
      return [];
    }

    setLoadingCourses(true);
    setError("");

    // Rezervovat lze pouze turnusy, které jsou pro zvolený den
    // skutečně zadané ve Výpravách.
    const { data: departureRows, error: departureError } =
      await supabase
        .from("vypravy")
        .select("kurz_id,linka")
        .eq("datum", targetDate)
        .eq("provozovna_id", Number(targetBranchId));

    if (departureError) {
      setError(departureError.message);
      setCourses([]);
      setLoadingCourses(false);
      return [];
    }

    const plannedIds = new Set(
      (departureRows || [])
        .map((row) => row.kurz_id)
        .filter(Boolean)
        .map((id) => String(id))
    );

    const plannedNames = new Set(
      (departureRows || [])
        .map((row) => String(row.linka || "").trim().toLowerCase())
        .filter(Boolean)
    );

    if (plannedIds.size === 0 && plannedNames.size === 0) {
      setCourses([]);
      setLoadingCourses(false);
      return [];
    }

    const { data, error: loadError } = await supabase
      .from("kurzy")
      .select(
        "id,nazev,provozovna_id,aktivni,typ_dne,varianta,zacatek,konec"
      )
      .eq("provozovna_id", Number(targetBranchId))
      .eq("aktivni", true)
      .order("nazev", { ascending: true });

    if (loadError) {
      setError(loadError.message);
      setCourses([]);
      setLoadingCourses(false);
      return [];
    }

    const filtered = (data || [])
      .filter((course) => {
        const isInDepartures =
          plannedIds.has(String(course.id)) ||
          plannedNames.has(
            String(course.nazev || "").trim().toLowerCase()
          );

        return (
          isInDepartures &&
          courseFitsDate(course, targetDate, targetBranchId)
        );
      })
      .sort((a, b) =>
        String(a.nazev).localeCompare(
          String(b.nazev),
          "cs",
          {
            numeric: true,
            sensitivity: "base",
          }
        )
      );

    setCourses(filtered);
    setLoadingCourses(false);
    return filtered;
  }

  function clearOccupiedConnections() {
    setOccupiedIds(new Set());
    setOccupiedBy({});
  }

  function restoreRange(realTrips, restoreIds = []) {
    if (!restoreIds.length) {
      setRangeStart(null);
      setRangeEnd(null);
      return;
    }

    const wanted = new Set(
      restoreIds.map((id) => String(id))
    );

    const indices = realTrips
      .map((row, index) =>
        wanted.has(String(row.id)) ? index : -1
      )
      .filter((index) => index >= 0);

    if (!indices.length) {
      setRangeStart(null);
      setRangeEnd(null);
      return;
    }

    setRangeStart(Math.min(...indices));
    setRangeEnd(Math.max(...indices));
  }

  async function loadConnections(
    targetCourseId = courseId,
    targetDate = date,
    excludedReservationId = editingReservation?.id || null,
    restoreIds = []
  ) {
    if (!targetCourseId) {
      setConnections([]);
      clearOccupiedConnections();
      setRangeStart(null);
      setRangeEnd(null);
      return [];
    }

    setLoadingConnections(true);
    setError("");

    const { data, error: loadError } = await supabase
      .from("kurz_spoje")
      .select(
        "id,kurz_id,poradi,typ,spoj,odjezd,prijezd,usek,odkud,kam,poznamka"
      )
      .eq("kurz_id", Number(targetCourseId))
      .order("poradi", { ascending: true });

    if (loadError) {
      setError(loadError.message);
      setConnections([]);
      clearOccupiedConnections();
      setLoadingConnections(false);
      return [];
    }

    const realTrips = (data || []).filter(
      (row) => !row.typ || row.typ === "SPOJ"
    );

    setConnections(realTrips);

    if (realTrips.length === 0) {
      clearOccupiedConnections();
      restoreRange([], []);
      setLoadingConnections(false);
      return [];
    }

    const { data: occupied, error: occupiedError } =
      await supabase.rpc("obsazenost_rezervace_smeny", {
        p_datum: targetDate,
        p_kurz_id: Number(targetCourseId),
      });

    if (occupiedError) {
      setError(occupiedError.message);
      clearOccupiedConnections();
    } else {
      const visibleOccupied = (occupied || []).filter(
        (row) =>
          !excludedReservationId ||
          String(row.rezervace_id) !==
            String(excludedReservationId)
      );

      setOccupiedIds(
        new Set(
          visibleOccupied.map((row) =>
            String(row.kurz_spoj_id)
          )
        )
      );

      setOccupiedBy(
        Object.fromEntries(
          visibleOccupied.map((row) => [
            String(row.kurz_spoj_id),
            {
              rezervace_id: row.rezervace_id,
              uzivatel_id: row.uzivatel_id,
              jmeno:
                row.jmeno ||
                "Neznámý zaměstnanec",
            },
          ])
        )
      );
    }

    restoreRange(realTrips, restoreIds);
    setLoadingConnections(false);
    return realTrips;
  }

  async function loadReservations() {
    if (!user?.id) return;

    setLoadingReservations(true);

    const { data, error: loadError } =
      await supabase.rpc(
        "prehled_rezervaci_smen_pro_vsechny"
      );

    if (loadError) {
      setError(loadError.message);
      setReservations([]);
      setReservationCourses({});
      setReservationProfiles({});
      setLoadingReservations(false);
      return;
    }

    const loaded = data || [];

    setReservations(
      loaded.map((item) => ({
        id: item.id,
        uzivatel_id: item.uzivatel_id,
        datum: item.datum,
        provozovna_id: item.provozovna_id,
        kurz_id: item.kurz_id,
        od_spoj: item.od_spoj,
        do_spoj: item.do_spoj,
        pocet_spoju: item.pocet_spoju,
        minuty_jizdy: item.minuty_jizdy,
        stav: item.stav,
        created_at: item.created_at,
        updated_at: item.updated_at,
      }))
    );

    setReservationProfiles(
      Object.fromEntries(
        loaded
          .filter((item) => item.uzivatel_id)
          .map((item) => [
            String(item.uzivatel_id),
            {
              id: item.uzivatel_id,
              jmeno:
                item.jmeno ||
                "Neznámý zaměstnanec",
            },
          ])
      )
    );

    const courseIds = [
      ...new Set(
        loaded
          .map((item) => item.kurz_id)
          .filter(Boolean)
      ),
    ];

    if (courseIds.length > 0) {
      const { data: courseRows } = await supabase
        .from("kurzy")
        .select("id,nazev,provozovna_id")
        .in("id", courseIds);

      setReservationCourses(
        Object.fromEntries(
          (courseRows || []).map((item) => [
            String(item.id),
            item,
          ])
        )
      );
    } else {
      setReservationCourses({});
    }

    setLoadingReservations(false);
  }

  useEffect(() => {
    loadReservations();
  }, [user?.id, role]);

  useEffect(() => {
    if (
      !initialTarget ||
      !initialTarget.date ||
      !initialTarget.branchId ||
      !initialTarget.courseId ||
      provozovny.length === 0
    ) {
      return;
    }

    let cancelled = false;

    async function openFromDepartures() {
      const targetDate = initialTarget.date;
      const targetBranchId = String(initialTarget.branchId);
      const targetCourseId = String(initialTarget.courseId);

      setEditingReservation(null);
      setReservationSection("new");
      setDate(targetDate);
      setBranchId(targetBranchId);
      setCourseId("");
      setConnections([]);
      clearOccupiedConnections();
      setRangeStart(null);
      setRangeEnd(null);
      setError("");
      setSuccess("");

      const loadedCourses = await loadCourses(
        targetBranchId,
        targetDate
      );

      if (cancelled) return;

      const targetCourse = loadedCourses.find(
        (course) =>
          String(course.id) === targetCourseId
      );

      if (!targetCourse) {
        setError(
          "Tento turnus není pro zvolený den ve Výpravách, takže ho nelze nabídnout k rezervaci."
        );
        onInitialTargetUsed?.();
        return;
      }

      setCourseId(targetCourseId);

      await loadConnections(
        targetCourseId,
        targetDate,
        null,
        []
      );

      if (cancelled) return;

      setSuccess(
        `Turnus ${targetCourse.nazev} byl načten z Výprav. Vyber si požadovaný úsek spojů.`
      );

      onInitialTargetUsed?.();
    }

    openFromDepartures();

    return () => {
      cancelled = true;
    };
  }, [
    initialTarget?.key,
    provozovny.length,
  ]);

  function resetTripSelection() {
    setRangeStart(null);
    setRangeEnd(null);
    setError("");
  }

  async function handleDateChange(value) {
    setDate(value);
    setCourseId("");
    setConnections([]);
    clearOccupiedConnections();
    resetTripSelection();

    if (branchId && value) {
      await loadCourses(branchId, value);
    }
  }

  async function handleBranchChange(value) {
    setBranchId(value);
    setCourseId("");
    setConnections([]);
    clearOccupiedConnections();
    resetTripSelection();

    if (value && date) {
      await loadCourses(value, date);
    } else {
      setCourses([]);
    }
  }

  async function handleCourseChange(value) {
    setCourseId(value);
    resetTripSelection();

    if (value) {
      await loadConnections(
        value,
        date,
        editingReservation?.id || null,
        []
      );
    } else {
      setConnections([]);
      clearOccupiedConnections();
    }
  }

  function tripMinutes(row) {
    if (!row?.odjezd || !row?.prijezd) return 0;

    const [sh, sm] = String(row.odjezd)
      .slice(0, 5)
      .split(":")
      .map(Number);

    const [eh, em] = String(row.prijezd)
      .slice(0, 5)
      .split(":")
      .map(Number);

    const start = sh * 60 + sm;
    const end = eh * 60 + em;

    return end >= start
      ? end - start
      : 1440 - start + end;
  }

  const selectedRows =
    rangeStart === null || rangeEnd === null
      ? []
      : connections.slice(
          Math.min(rangeStart, rangeEnd),
          Math.max(rangeStart, rangeEnd) + 1
        );

  const selectedMinutes = selectedRows.reduce(
    (sum, row) => sum + tripMinutes(row),
    0
  );

  const selectedHasOccupied = selectedRows.some(
    (row) => occupiedIds.has(String(row.id))
  );

  function chooseTrip(index) {
    const row = connections[index];

    if (!row || occupiedIds.has(String(row.id))) {
      return;
    }

    setError("");
    setSuccess("");

    if (
      rangeStart === null ||
      rangeEnd === null ||
      rangeStart !== rangeEnd
    ) {
      setRangeStart(index);
      setRangeEnd(index);
      return;
    }

    if (rangeStart === index) {
      setRangeStart(null);
      setRangeEnd(null);
      return;
    }

    const newStart = Math.min(rangeStart, index);
    const newEnd = Math.max(rangeStart, index);
    const nextRows = connections.slice(newStart, newEnd + 1);

    if (
      nextRows.some((item) =>
        occupiedIds.has(String(item.id))
      )
    ) {
      setError(
        "Mezi vybranými spoji je už rezervovaný spoj. Vyber jiný souvislý úsek."
      );
      return;
    }

    setRangeStart(newStart);
    setRangeEnd(newEnd);
  }

  async function selectWholeTurnus() {
    if (connections.length === 0) return;

    if (
      connections.some((row) =>
        occupiedIds.has(String(row.id))
      )
    ) {
      setError(
        "Celý turnus nejde vybrat, protože některý jeho spoj je už rezervovaný."
      );
      return;
    }

    setRangeStart(0);
    setRangeEnd(connections.length - 1);
    setError("");
  }

  async function beginEditReservation(reservation) {
    const isMine =
      String(reservation.uzivatel_id) === String(user.id);

    if (!isMine && !manage) return;

    setError("");
    setSuccess("");
    setReservationSection("new");

    const { data: reservationLinks, error: linksError } =
      await supabase
        .from("rezervace_smen_spoje")
        .select("kurz_spoj_id")
        .eq("rezervace_id", reservation.id);

    if (linksError) {
      setError(linksError.message);
      return;
    }

    const selectedIds = (reservationLinks || []).map(
      (row) => row.kurz_spoj_id
    );

    const editData = {
      ...reservation,
      spojIds: selectedIds,
    };

    setEditingReservation(editData);
    setDate(reservation.datum);
    setBranchId(String(reservation.provozovna_id));

    const loadedCourses = await loadCourses(
      String(reservation.provozovna_id),
      reservation.datum
    );

    const courseStillExists = loadedCourses.some(
      (course) =>
        String(course.id) === String(reservation.kurz_id)
    );

    if (!courseStillExists) {
      setError(
        "Původní turnus už není aktivní pro zvolený den. Vyber jiný turnus."
      );
      setCourseId("");
      setConnections([]);
    } else {
      setCourseId(String(reservation.kurz_id));

      await loadConnections(
        String(reservation.kurz_id),
        reservation.datum,
        reservation.id,
        selectedIds
      );
    }

    if (typeof window !== "undefined") {
      window.scrollTo({
        top: 0,
        behavior: "smooth",
      });
    }
  }

  async function stopEditing() {
    const currentCourse = courseId;

    setEditingReservation(null);
    resetTripSelection();

    if (currentCourse) {
      await loadConnections(
        currentCourse,
        date,
        null,
        []
      );
    }
  }

  async function saveReservation() {
    if (!courseId || selectedRows.length === 0) {
      setError("Vyber turnus a souvislý úsek spojů.");
      return;
    }

    if (selectedHasOccupied) {
      setError("Některý vybraný spoj je už rezervovaný.");
      return;
    }

    if (selectedMinutes < 50) {
      setError(
        `Minimální doba jízdy je 50 minut. Teď máš ${selectedMinutes} min.`
      );
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const isEditing = Boolean(editingReservation);

    const rpcResult = isEditing
      ? await supabase.rpc("upravit_rezervaci_smeny", {
          p_rezervace_id: editingReservation.id,
          p_datum: date,
          p_kurz_id: Number(courseId),
          p_spoj_ids: selectedRows.map((row) => row.id),
        })
      : await supabase.rpc("vytvor_rezervaci_smeny", {
          p_datum: date,
          p_kurz_id: Number(courseId),
          p_spoj_ids: selectedRows.map((row) => row.id),
        });

    if (rpcResult.error) {
      setError(
        rpcResult.error.message ||
          (isEditing
            ? "Rezervaci se nepodařilo upravit."
            : "Rezervaci se nepodařilo vytvořit.")
      );
      setSaving(false);

      await loadConnections(
        courseId,
        date,
        editingReservation?.id || null,
        selectedRows.map((row) => row.id)
      );
      return;
    }

    setSuccess(
      isEditing
        ? `Rezervace byla upravena: ${selectedRows.length} spojů / ${selectedMinutes} minut jízdy.`
        : `Rezervace byla vytvořena: ${selectedRows.length} spojů / ${selectedMinutes} minut jízdy.`
    );

    setEditingReservation(null);
    resetTripSelection();

    await Promise.all([
      loadConnections(courseId, date, null, []),
      loadReservations(),
    ]);

    setReservationView("upcoming");
    setReservationSection("overview");
    setSaving(false);
  }

  async function cancelReservation(reservation) {
    const isMine =
      String(reservation.uzivatel_id) === String(user.id);

    if (!isMine && !manage) return;

    if (
      !window.confirm(
        `Opravdu chceš zrušit rezervaci ${reservation.od_spoj || ""} – ${reservation.do_spoj || ""}?`
      )
    ) {
      return;
    }

    setError("");
    setSuccess("");

    const { error: deleteError } = await supabase
      .from("rezervace_smen")
      .delete()
      .eq("id", reservation.id);

    if (deleteError) {
      setError(deleteError.message);
      return;
    }

    if (
      editingReservation &&
      String(editingReservation.id) === String(reservation.id)
    ) {
      setEditingReservation(null);
      resetTripSelection();
    }

    setSuccess("Rezervace byla zrušena.");

    await Promise.all([
      loadReservations(),
      courseId
        ? loadConnections(courseId, date, null, [])
        : Promise.resolve(),
    ]);
  }

  const selectedCourse = courses.find(
    (course) => String(course.id) === String(courseId)
  );

  const dateLabel = (() => {
    try {
      return new Intl.DateTimeFormat("cs-CZ", {
        weekday: "long",
        day: "numeric",
        month: "long",
        year: "numeric",
      }).format(new Date(`${date}T12:00:00`));
    } catch {
      return date;
    }
  })();

  const upcomingCount = reservations.filter(
    (reservation) => reservation.datum >= todayIso
  ).length;

  const todayCount = reservations.filter(
    (reservation) => reservation.datum === todayIso
  ).length;

  const upcomingMinutes = reservations
    .filter((reservation) => reservation.datum >= todayIso)
    .reduce(
      (sum, reservation) =>
        sum + Number(reservation.minuty_jizdy || 0),
      0
    );

  const filteredReservations = reservations
    .filter((reservation) => {
      if (reservationView === "today") {
        return reservation.datum === todayIso;
      }

      if (reservationView === "upcoming") {
        return reservation.datum >= todayIso;
      }

      if (reservationView === "past") {
        return reservation.datum < todayIso;
      }

      return true;
    })
    .sort((a, b) => {
      if (reservationView === "past") {
        return String(b.datum).localeCompare(String(a.datum));
      }

      return String(a.datum).localeCompare(String(b.datum));
    });

  const reservationGroups = filteredReservations.reduce(
    (groups, reservation) => {
      if (!groups[reservation.datum]) {
        groups[reservation.datum] = [];
      }

      groups[reservation.datum].push(reservation);
      return groups;
    },
    {}
  );

  function formatReservationDay(value) {
    return new Intl.DateTimeFormat("cs-CZ", {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(new Date(`${value}T12:00:00`));
  }

  function formatShortDate(value) {
    return new Intl.DateTimeFormat("cs-CZ", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    }).format(new Date(`${value}T12:00:00`));
  }

  return (
    <div className="shift-reservations-page">
      <div className="topbar reservation-page-topbar">
        <div>
          <span className="page-kicker">PLÁNOVÁNÍ SMĚN</span>
          <h1>Rezervace směn</h1>
          <p>
            Rezervuj si souvislý úsek turnusu. Nabízí se pouze
            turnusy skutečně zadané ve Výpravách pro vybraný den.
            Minimum je 50 minut skutečné jízdy.
          </p>
        </div>

        <div className="reservation-minimum-badge">
          <span>MINIMUM</span>
          <strong>50 min</strong>
          <small>skutečné jízdy</small>
        </div>
      </div>

      <div className="reservation-main-tabs">
        <button
          type="button"
          className={reservationSection === "new" ? "active" : ""}
          onClick={() => setReservationSection("new")}
        >
          <span className="reservation-main-tab-icon">
            {editingReservation ? "✏️" : "＋"}
          </span>
          <span>
            <strong>
              {editingReservation ? "Upravit rezervaci" : "Nová rezervace"}
            </strong>
            <small>Vyber den, turnus a spoje</small>
          </span>
        </button>

        <button
          type="button"
          className={reservationSection === "overview" ? "active" : ""}
          onClick={() => setReservationSection("overview")}
        >
          <span className="reservation-main-tab-icon">📋</span>
          <span>
            <strong>
              Přehled rezervací
            </strong>
            <small>
              {upcomingCount} nadcházejících · {reservations.length} celkem
            </small>
          </span>
        </button>
      </div>

      {reservationSection === "overview" && (
        <div className="reservation-overview-grid">
          <div className="reservation-overview-card">
            <span>📅</span>
            <div>
              <small>Dnes</small>
              <strong>{todayCount}</strong>
            </div>
          </div>

          <div className="reservation-overview-card">
            <span>→</span>
            <div>
              <small>Nadcházející</small>
              <strong>{upcomingCount}</strong>
            </div>
          </div>

          <div className="reservation-overview-card">
            <span>⏱</span>
            <div>
              <small>Jízda dopředu</small>
              <strong>{upcomingMinutes} min</strong>
            </div>
          </div>

          <div className="reservation-overview-card">
            <span>✓</span>
            <div>
              <small>Celkem rezervací</small>
              <strong>{reservations.length}</strong>
            </div>
          </div>
        </div>
      )}

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      {reservationSection === "new" && editingReservation && (
        <div className="reservation-edit-banner">
          <div className="reservation-edit-banner-icon">✏️</div>

          <div>
            <span>UPRAVUJEŠ REZERVACI</span>
            <strong>
              {formatShortDate(editingReservation.datum)}
              {" · "}
              {reservationCourses[
                String(editingReservation.kurz_id)
              ]?.nazev || "Turnus"}
              {" · "}
              {editingReservation.od_spoj || "—"}
              {" → "}
              {editingReservation.do_spoj || "—"}
            </strong>
            <small>
              Můžeš změnit datum, provozovnu, turnus i rozsah
              spojů. Pořád musí zůstat alespoň 50 minut jízdy.
            </small>
          </div>

          <button
            type="button"
            className="secondary-button"
            onClick={stopEditing}
          >
            Ukončit úpravu
          </button>
        </div>
      )}

      {reservationSection === "new" && (
        <>
          <div className="reservation-steps">
            <div className="reservation-step done">
              <span>1</span>
              <div>
                <strong>Den a provozovna</strong>
                <small>{date && branchId ? "Vybráno" : "Vyber údaje"}</small>
              </div>
            </div>

            <div
              className={[
                "reservation-step",
                courseId ? "done" : branchId ? "active" : "",
              ]
                .filter(Boolean)
                .join(" ")}
            >
              <span>2</span>
              <div>
                <strong>Turnus</strong>
                <small>
                  {selectedCourse?.nazev ||
                    (branchId ? "Vyber turnus" : "Čeká na provozovnu")}
                </small>
              </div>
            </div>

            <div
              className={[
                "reservation-step",
                selectedMinutes >= 50
                  ? "done"
                  : courseId
                  ? "active"
                  : "",
              ]
                .filter(Boolean)
                .join(" ")}
            >
              <span>3</span>
              <div>
                <strong>Spoje a potvrzení</strong>
                <small>
                  {selectedRows.length
                    ? `${selectedMinutes} min · ${selectedRows.length} spojů`
                    : courseId
                    ? "Vyber souvislý úsek"
                    : "Čeká na turnus"}
                </small>
              </div>
            </div>
          </div>

          <div
        className={[
          "reservation-builder",
          "panel",
          editingReservation ? "editing" : "",
        ]
          .filter(Boolean)
          .join(" ")}
      >
        <div className="reservation-builder-head">
          <div>
            <span>
              {editingReservation ? "ÚPRAVA" : "KROK 1"}
            </span>
            <h2>
              {editingReservation
                ? "Uprav rezervaci"
                : "Vyber den a turnus"}
            </h2>
            <p>
              Nejdřív datum a provozovna, potom konkrétní turnus.
            </p>
          </div>

          <strong>{dateLabel}</strong>
        </div>

        <div className="reservation-filter-grid">
          <label>
            <span>1 · Datum</span>
            <input
              type="date"
              value={date}
              onChange={(event) =>
                handleDateChange(event.target.value)
              }
            />
          </label>

          <label>
            <span>2 · Provozovna</span>
            <select
              value={branchId}
              onChange={(event) =>
                handleBranchChange(event.target.value)
              }
            >
              <option value="">Vyber provozovnu</option>
              {mainBranches.map((branch) => (
                <option key={branch.id} value={branch.id}>
                  {branch.nazev}
                </option>
              ))}
            </select>
          </label>

          <label>
            <span>3 · Turnus</span>
            <select
              value={courseId}
              onChange={(event) =>
                handleCourseChange(event.target.value)
              }
              disabled={!branchId || loadingCourses}
            >
              <option value="">
                {loadingCourses
                  ? "Načítám Výpravy..."
                  : !branchId
                  ? "Nejdřív vyber provozovnu"
                  : courses.length === 0
                  ? "Pro tento den není ve Výpravách žádný turnus"
                  : "Vyber turnus z Výprav"}
              </option>

              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.nazev}
                </option>
              ))}
            </select>
          </label>
        </div>

        {branchId && date && (
          <div className="reservation-departures-source">
            <span>◆</span>
            <div>
              <strong>Turnusy se načítají z Výprav</strong>
              <small>
                Když je ve Výpravách pro tento den například 210.01,
                objeví se tady k rezervaci. Pokud ve Výpravách není,
                rezervovat ho nepůjde.
              </small>
            </div>
          </div>
        )}

        {branchId &&
          String(branchById(branchId)?.kod || "")
            .trim()
            .toUpperCase() === "BRE" && (
            <div className="reservation-bre-mode">
              <span>Břeclavsko</span>
              <strong>
                {Number(date.split("-")[1]) === 8
                  ? "Prázdninový provoz"
                  : "Běžný provoz"}
              </strong>
              <small>
                Režim se vybírá automaticky podle data.
              </small>
            </div>
          )}
      </div>

      {courseId && (
        <div className="reservation-trips-panel panel">
          <div className="reservation-trips-head">
            <div>
              <span>
                {editingReservation ? "ÚPRAVA SPOJŮ" : "KROK 2"}
              </span>
              <h2>
                Turnus {selectedCourse?.nazev || "—"}
              </h2>
              <p>
                Klikni na první spoj a potom na poslední. Výběr
                mezi nimi musí být souvislý.
              </p>
            </div>

            <div className="reservation-trips-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={selectWholeTurnus}
                disabled={connections.length === 0}
              >
                Vybrat celý turnus
              </button>

              <button
                type="button"
                className="secondary-button"
                onClick={resetTripSelection}
                disabled={rangeStart === null}
              >
                Vymazat výběr
              </button>
            </div>
          </div>

          <div className="reservation-current-context">
            <div>
              <span>Datum</span>
              <strong>{formatShortDate(date)}</strong>
            </div>
            <div>
              <span>Provozovna</span>
              <strong>{branchById(branchId)?.nazev || "—"}</strong>
            </div>
            <div>
              <span>Turnus</span>
              <strong>{selectedCourse?.nazev || "—"}</strong>
            </div>
          </div>

          <div className="reservation-legend">
            <span>
              <i className="free" /> Volné
            </span>
            <span>
              <i className="selected" /> Tvoje volba
            </span>
            <span>
              <i className="occupied" /> Rezervované · se jménem
            </span>
          </div>

          {loadingConnections ? (
            <div className="empty">Načítám spoje...</div>
          ) : connections.length === 0 ? (
            <div className="empty">
              Tento turnus nemá uložené žádné spoje.
            </div>
          ) : (
            <>
              <div className="reservation-trip-list">
                <div className="reservation-trip-table-head">
                  <span>Spoj</span>
                  <span>Čas</span>
                  <span>Trasa</span>
                  <span>Jízda</span>
                  <span>Stav</span>
                </div>

                {connections.map((row, index) => {
                  const occupied = occupiedIds.has(
                    String(row.id)
                  );

                  const selected =
                    rangeStart !== null &&
                    rangeEnd !== null &&
                    index >= Math.min(rangeStart, rangeEnd) &&
                    index <= Math.max(rangeStart, rangeEnd);

                  return (
                    <button
                      type="button"
                      key={row.id}
                      className={[
                        "reservation-trip",
                        selected ? "selected" : "",
                        occupied ? "occupied" : "",
                      ]
                        .filter(Boolean)
                        .join(" ")}
                      onClick={() => chooseTrip(index)}
                      disabled={occupied}
                    >
                      <span className="reservation-trip-number">
                        {row.spoj || "Spoj"}
                      </span>

                      <span className="reservation-trip-time">
                        {row.odjezd
                          ? String(row.odjezd).slice(0, 5)
                          : "—"}
                        {" – "}
                        {row.prijezd
                          ? String(row.prijezd).slice(0, 5)
                          : "—"}
                      </span>

                      <span className="reservation-trip-route">
                        {row.usek ||
                          [row.odkud, row.kam]
                            .filter(Boolean)
                            .join(" → ") ||
                          "—"}
                      </span>

                      <span className="reservation-trip-duration">
                        {tripMinutes(row)} min
                      </span>

                      <span className="reservation-trip-state">
                        <strong>
                          {occupied
                            ? "REZERVOVÁNO"
                            : selected
                            ? "VYBRÁNO"
                            : "VOLNÉ"}
                        </strong>

                        {occupied && (
                          <small>
                            {occupiedBy[String(row.id)]?.jmeno ||
                              "Neznámý zaměstnanec"}
                          </small>
                        )}
                      </span>
                    </button>
                  );
                })}
              </div>

              <div
                className={[
                  "reservation-summary",
                  selectedMinutes >= 50 ? "ready" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
              >
                <div className="reservation-summary-main">
                  <span>Vybraný úsek</span>

                  <strong>
                    {selectedRows.length > 0
                      ? `${selectedRows[0]?.spoj || "—"} → ${
                          selectedRows[
                            selectedRows.length - 1
                          ]?.spoj || "—"
                        }`
                      : "Vyber první spoj"}
                  </strong>

                  <small>
                    {selectedRows.length > 0
                      ? `${selectedRows.length} spojů`
                      : "Potom klikni na poslední spoj úseku"}
                  </small>
                </div>

                <div
                  className={[
                    "reservation-minutes",
                    selectedMinutes >= 50 ? "ok" : "",
                  ]
                    .filter(Boolean)
                    .join(" ")}
                >
                  <span>Skutečný čas jízdy</span>
                  <strong>{selectedMinutes} min</strong>
                  <small>
                    {selectedMinutes >= 50
                      ? "✓ Minimum splněno"
                      : `Ještě ${Math.max(
                          0,
                          50 - selectedMinutes
                        )} min`}
                  </small>

                  <div className="reservation-progress">
                    <span
                      style={{
                        width: `${Math.min(
                          100,
                          (selectedMinutes / 50) * 100
                        )}%`,
                      }}
                    />
                  </div>
                </div>

                <button
                  type="button"
                  className="primary-button reservation-create-button"
                  disabled={
                    saving ||
                    selectedRows.length === 0 ||
                    selectedMinutes < 50 ||
                    selectedHasOccupied
                  }
                  onClick={saveReservation}
                >
                  {saving
                    ? "Ukládám..."
                    : editingReservation
                    ? "💾 Uložit úpravu"
                    : "✓ Rezervovat směnu"}
                </button>
              </div>
            </>
          )}
        </div>
      )}

        </>
      )}

      {reservationSection === "overview" && (
      <div className="reservation-list-panel panel">
        <div className="reservation-list-head">
          <div>
            <span>PŘEHLED</span>
            <h2>
              Rezervace směn
            </h2>
            <p>
              Každý přihlášený vidí, kdo má konkrétní směnu rezervovanou.
            </p>
          </div>

          <div className="reservation-list-head-actions">
            <button
              type="button"
              className="primary-button"
              onClick={() => setReservationSection("new")}
            >
              ＋ Nová rezervace
            </button>

            <button
              type="button"
              className="secondary-button"
              onClick={loadReservations}
              disabled={loadingReservations}
            >
              ↻ Obnovit
            </button>
          </div>
        </div>

        <div className="reservation-view-tabs">
          <button
            type="button"
            className={
              reservationView === "upcoming" ? "active" : ""
            }
            onClick={() => setReservationView("upcoming")}
          >
            Nadcházející
            <strong>{upcomingCount}</strong>
          </button>

          <button
            type="button"
            className={
              reservationView === "today" ? "active" : ""
            }
            onClick={() => setReservationView("today")}
          >
            Dnes
            <strong>{todayCount}</strong>
          </button>

          <button
            type="button"
            className={
              reservationView === "past" ? "active" : ""
            }
            onClick={() => setReservationView("past")}
          >
            Minulé
          </button>

          <button
            type="button"
            className={
              reservationView === "all" ? "active" : ""
            }
            onClick={() => setReservationView("all")}
          >
            Všechny
            <strong>{reservations.length}</strong>
          </button>
        </div>

        {loadingReservations ? (
          <div className="empty">Načítám rezervace...</div>
        ) : filteredReservations.length === 0 ? (
          <div className="reservation-empty">
            <span>📅</span>
            <strong>V tomto přehledu nic není</strong>
            <small>
              Rezervace se po vytvoření zobrazí tady.
            </small>
          </div>
        ) : (
          <div className="reservation-day-groups">
            {Object.entries(reservationGroups).map(
              ([groupDate, groupReservations]) => (
                <section
                  className="reservation-day-group"
                  key={groupDate}
                >
                  <div className="reservation-day-heading">
                    <div>
                      <strong>
                        {formatReservationDay(groupDate)}
                      </strong>
                      <span>
                        {groupDate === todayIso
                          ? "DNES"
                          : groupDate > todayIso
                          ? "NADCHÁZEJÍCÍ"
                          : "MINULÉ"}
                      </span>
                    </div>

                    <small>
                      {groupReservations.length}{" "}
                      {groupReservations.length === 1
                        ? "rezervace"
                        : "rezervací"}
                    </small>
                  </div>

                  <div className="reservation-cards">
                    {groupReservations.map((reservation) => {
                      const course =
                        reservationCourses[
                          String(reservation.kurz_id)
                        ];

                      const branch = branchById(
                        reservation.provozovna_id
                      );

                      const person =
                        reservationProfiles[
                          String(reservation.uzivatel_id)
                        ];

                      const canChange =
                        manage ||
                        String(reservation.uzivatel_id) ===
                          String(user.id);

                      const isBeingEdited =
                        editingReservation &&
                        String(editingReservation.id) ===
                          String(reservation.id);

                      return (
                        <article
                          className={[
                            "reservation-card",
                            isBeingEdited ? "editing" : "",
                          ]
                            .filter(Boolean)
                            .join(" ")}
                          key={reservation.id}
                        >
                          <div className="reservation-card-course">
                            <span>Turnus</span>
                            <strong>
                              {course?.nazev || "—"}
                            </strong>
                            <small>
                              {branch?.nazev || "—"}
                            </small>
                          </div>

                          <div className="reservation-card-route">
                            <span>Rezervovaný úsek</span>
                            <strong>
                              {reservation.od_spoj || "—"}
                              <b>→</b>
                              {reservation.do_spoj || "—"}
                            </strong>
                            <small>
                              {reservation.pocet_spoju} spojů
                            </small>
                          </div>

                          <div className="reservation-card-person">
                            <span>Rezervoval/a</span>
                            <strong>
                              {person?.jmeno ||
                                "Neznámý zaměstnanec"}
                            </strong>
                          </div>

                          <div className="reservation-card-minutes">
                            <span>Skutečná jízda</span>
                            <strong>
                              {reservation.minuty_jizdy}
                              <small> min</small>
                            </strong>
                            <i>✓ minimum splněno</i>
                          </div>

                          <div className="reservation-card-actions">
                            {canChange && (
                              <button
                                type="button"
                                className="reservation-edit-button"
                                onClick={() =>
                                  beginEditReservation(
                                    reservation
                                  )
                                }
                              >
                                ✏️ Upravit
                              </button>
                            )}

                            {canChange && (
                              <button
                                type="button"
                                className="reservation-cancel-button"
                                onClick={() =>
                                  cancelReservation(reservation)
                                }
                              >
                                Zrušit
                              </button>
                            )}
                          </div>

                          {reservation.updated_at && (
                            <div className="reservation-card-updated">
                              Upraveno{" "}
                              {new Intl.DateTimeFormat("cs-CZ", {
                                day: "2-digit",
                                month: "2-digit",
                                hour: "2-digit",
                                minute: "2-digit",
                              }).format(
                                new Date(
                                  reservation.updated_at
                                )
                              )}
                            </div>
                          )}
                        </article>
                      );
                    })}
                  </div>
                </section>
              )
            )}
          </div>
        )}
      </div>
      )}
    </div>
  );
}



function AdminConnections() {
  const { provozovny } = useProvozovny();

  const [courses, setCourses] = useState([]);
  const [selectedCourseId, setSelectedCourseId] = useState("");
  const [connections, setConnections] = useState([]);
  const [search, setSearch] = useState("");
  const [loadingCourses, setLoadingCourses] = useState(true);
  const [loadingConnections, setLoadingConnections] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [form, setForm] = useState({
    poradi: "",
    typ: "SPOJ",
    spoj: "",
    odjezd: "",
    prijezd: "",
    usek: "",
    odkud: "",
    kam: "",
    delka_trasy: "",
    poznamka: "",
    ois: "",
  });

  async function loadCourses() {
    setLoadingCourses(true);
    setError("");

    const { data, error: loadError } = await supabase
      .from("kurzy")
      .select(
        "id,nazev,provozovna_id,aktivni,typ_dne,varianta,zacatek,konec,zacatek_misto,stridani_misto,stridani_cas,konec_misto,druh_smeny,poznamka_turnusu"
      )
      .order("nazev", { ascending: true });

    if (loadError) {
      setError(loadError.message);
      setCourses([]);
    } else {
      setCourses(data || []);
    }

    setLoadingCourses(false);
  }

  async function loadConnections(courseId) {
    if (!courseId) {
      setConnections([]);
      return;
    }

    setLoadingConnections(true);
    setError("");

    const { data, error: loadError } = await supabase
      .from("kurz_spoje")
      .select("id,kurz_id,poradi,typ,spoj,odjezd,prijezd,usek,odkud,kam,delka_trasy,poznamka,ois")
      .eq("kurz_id", Number(courseId))
      .order("poradi", { ascending: true });

    if (loadError) {
      setError(loadError.message);
      setConnections([]);
    } else {
      setConnections(data || []);
    }

    setLoadingConnections(false);
  }

  useEffect(() => {
    loadCourses();
  }, []);

  useEffect(() => {
    loadConnections(selectedCourseId);
    setEditing(null);
    setForm({
      poradi: "",
      typ: "SPOJ",
      spoj: "",
      odjezd: "",
      prijezd: "",
      usek: "",
      odkud: "",
      kam: "",
      delka_trasy: "",
      poznamka: "",
      ois: "",
    });
  }, [selectedCourseId]);

  function resetForm() {
    setEditing(null);
    setForm({
      poradi: "",
      typ: "SPOJ",
      spoj: "",
      odjezd: "",
      prijezd: "",
      usek: "",
      odkud: "",
      kam: "",
      delka_trasy: "",
      poznamka: "",
      ois: "",
    });
  }

  function getBranch(course) {
    return provozovny.find(
      (item) => String(item.id) === String(course.provozovna_id)
    );
  }

  function getBranchCode(course) {
    const branch = getBranch(course);
    return String(
      branch?.kod ||
      branch?.code ||
      branch?.zkratka ||
      branch?.nazev ||
      ""
    ).trim();
  }

  const visibleCourses = courses
    .filter((course) => {
      const branch = getBranch(course);
      if (!branch) return false;

      const code = getBranchCode(course).toUpperCase();

      if (!isMainProvozovna(branch)) return false;

      const needle = search.trim().toLowerCase();
      if (!needle) return true;

      return (
        String(course.nazev || "").toLowerCase().includes(needle) ||
        String(branch.nazev || "").toLowerCase().includes(needle) ||
        code.toLowerCase().includes(needle)
      );
    })
    .sort((a, b) =>
      String(a.nazev).localeCompare(String(b.nazev), "cs", {
        numeric: true,
        sensitivity: "base",
      })
    );

  const selectedCourse =
    courses.find(
      (course) => String(course.id) === String(selectedCourseId)
    ) || null;

  async function saveConnection(event) {
    event.preventDefault();

    if (!selectedCourseId) {
      setError("Nejdřív vyber turnus.");
      return;
    }

    if (
      form.typ === "SPOJ" &&
      (!form.spoj.trim() || !form.odjezd || !form.prijezd)
    ) {
      setError("U běžného spoje vyplň číslo spoje, odjezd a příjezd.");
      return;
    }

    if (!form.usek.trim()) {
      setError("Vyplň úsek / činnost.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const nextOrder =
      connections.length > 0
        ? Math.max(
            ...connections.map((item) => Number(item.poradi) || 0)
          ) + 1
        : 1;

    const payload = {
      kurz_id: Number(selectedCourseId),
      poradi: Number(form.poradi || nextOrder),
      typ: form.typ,
      spoj: form.spoj.trim() || null,
      odjezd: form.odjezd || null,
      prijezd: form.prijezd || null,
      usek: form.usek.trim() || null,
      odkud: form.odkud.trim() || null,
      kam: form.kam.trim() || null,
      delka_trasy: form.delka_trasy.trim() || null,
      poznamka: form.poznamka.trim() || null,
      ois: form.ois.trim() || null,
    };

    const result = editing
      ? await supabase
          .from("kurz_spoje")
          .update(payload)
          .eq("id", editing.id)
      : await supabase
          .from("kurz_spoje")
          .insert(payload);

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editing ? "Spoj byl upraven." : "Spoj byl přidán."
    );
    resetForm();
    await loadConnections(selectedCourseId);
    setSaving(false);
  }

  function editConnection(connection) {
    setEditing(connection);
    setError("");
    setSuccess("");
    setForm({
      poradi: String(connection.poradi || ""),
      typ: connection.typ || "SPOJ",
      spoj: connection.spoj || "",
      odjezd: connection.odjezd
        ? String(connection.odjezd).slice(0, 5)
        : "",
      prijezd: connection.prijezd
        ? String(connection.prijezd).slice(0, 5)
        : "",
      usek: connection.usek || "",
      odkud: connection.odkud || "",
      kam: connection.kam || "",
      delka_trasy: connection.delka_trasy || "",
      poznamka: connection.poznamka || "",
      ois: connection.ois || "",
    });
  }

  async function deleteConnection(connection) {
    if (
      !window.confirm(
        `Opravdu chceš smazat řádek ${connection.spoj || connection.usek || ""}?`
      )
    ) {
      return;
    }

    setError("");
    setSuccess("");

    const { error: deleteError } = await supabase
      .from("kurz_spoje")
      .delete()
      .eq("id", connection.id);

    if (deleteError) {
      setError(deleteError.message);
      return;
    }

    if (editing?.id === connection.id) {
      resetForm();
    }

    setSuccess("Spoj byl smazán.");
    await loadConnections(selectedCourseId);
  }

  return (
    <div>
      <div className="topbar">
        <div>
          <span className="page-kicker">TURNUSE</span>
          <h1>Spoje</h1>
          <p>
            Správa jednotlivých spojů a časů uvnitř turnusů.
          </p>
        </div>

        <div className="count-badge">
          {connections.length} spojů
        </div>
      </div>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      <div className="admin-connections-layout">
        <aside className="panel admin-connections-courses">
          <div className="admin-connections-side-head">
            <div>
              <h2>Turnusy</h2>
              <p>Vyber turnus, jehož spoje chceš upravit.</p>
            </div>
          </div>

          <input
            className="admin-connections-search"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Hledat turnus..."
          />

          {loadingCourses ? (
            <div className="empty">Načítám turnusy...</div>
          ) : (
            <div className="admin-connections-course-list">
              {visibleCourses.map((course) => {
                const branch = getBranch(course);

                return (
                  <button
                    type="button"
                    key={course.id}
                    className={`admin-connections-course ${
                      String(selectedCourseId) === String(course.id)
                        ? "active"
                        : ""
                    }`}
                    onClick={() =>
                      setSelectedCourseId(String(course.id))
                    }
                  >
                    <strong>{course.nazev}</strong>
                    <span>
                      {branch?.nazev || "Bez provozovny"}
                      {course.typ_dne
                        ? ` · ${getCourseDayLabel(course.typ_dne)}`
                        : ""}
                      {course.varianta
                        ? ` · ${getCourseVariantLabel(course.varianta)}`
                        : ""}
                    </span>
                  </button>
                );
              })}
            </div>
          )}
        </aside>

        <section className="panel admin-connections-main">
          {!selectedCourse ? (
            <div className="admin-connections-empty">
              <div className="admin-connections-empty-icon">⇄</div>
              <strong>Vyber turnus vlevo</strong>
              <span>
                Potom se zobrazí jeho spoje a časy.
              </span>
            </div>
          ) : (
            <>
              <div className="admin-connections-turnus-head">
                <div>
                  <span>TURNUS</span>
                  <h2>{selectedCourse.nazev}</h2>
                  <p>
                    {getBranch(selectedCourse)?.nazev || ""}
                    {selectedCourse.typ_dne
                      ? ` · ${getCourseDayLabel(selectedCourse.typ_dne)}`
                      : ""}
                    {selectedCourse.varianta
                      ? ` · ${getCourseVariantLabel(selectedCourse.varianta)}`
                      : ""}
                    {selectedCourse.zacatek || selectedCourse.konec
                      ? ` · ${
                          selectedCourse.zacatek
                            ? String(selectedCourse.zacatek).slice(0, 5)
                            : "—"
                        }–${
                          selectedCourse.konec
                            ? String(selectedCourse.konec).slice(0, 5)
                            : "—"
                        }`
                      : ""}
                  </p>
                </div>

                <span className="admin-connections-count">
                  {connections.length} spojů
                </span>
              </div>

              <form
                className="admin-connection-form"
                onSubmit={saveConnection}
              >
                <div className="admin-connection-form-title">
                  <strong>
                    {editing ? "Upravit spoj" : "Přidat spoj"}
                  </strong>

                  {editing && (
                    <button
                      type="button"
                      className="secondary-button"
                      onClick={resetForm}
                      disabled={saving}
                    >
                      Zrušit úpravu
                    </button>
                  )}
                </div>

                <div className="admin-connection-grid">
                  <label>
                    <span>Pořadí</span>
                    <input
                      type="number"
                      min="1"
                      value={form.poradi}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          poradi: event.target.value,
                        })
                      }
                      placeholder="automaticky"
                    />
                  </label>

                  <label>
                    <span>Typ řádku</span>
                    <select
                      value={form.typ}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          typ: event.target.value,
                        })
                      }
                    >
                      <option value="SPOJ">Spoj</option>
                      <option value="ODPOCINEK">Odpočinek</option>
                      <option value="STRIDANI">Střídání</option>
                      <option value="SLUZEBNI_JIZDA">Služební jízda</option>
                    </select>
                  </label>

                  <label>
                    <span>Linkospoj</span>
                    <input
                      value={form.spoj}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          spoj: event.target.value,
                        })
                      }
                      placeholder="např. 572/31"
                    />
                  </label>

                  <label>
                    <span>Odjezd / od</span>
                    <input
                      type="time"
                      value={form.odjezd}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          odjezd: event.target.value,
                        })
                      }
                    />
                  </label>

                  <label>
                    <span>Příjezd / do</span>
                    <input
                      type="time"
                      value={form.prijezd}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          prijezd: event.target.value,
                        })
                      }
                    />
                  </label>

                  <label className="admin-connection-wide">
                    <span>Úsek / činnost</span>
                    <input
                      value={form.usek}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          usek: event.target.value,
                        })
                      }
                      placeholder="Břeclav, a.n. - Lužice, žel.st."
                      required
                    />
                  </label>

                  <label className="admin-connection-wide">
                    <span>Odkud</span>
                    <input
                      value={form.odkud}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          odkud: event.target.value,
                        })
                      }
                      placeholder="Výchozí zastávka"
                    />
                  </label>

                  <label className="admin-connection-wide">
                    <span>Kam</span>
                    <input
                      value={form.kam}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          kam: event.target.value,
                        })
                      }
                      placeholder="Cílová zastávka"
                    />
                  </label>

                  <label>
                    <span>Délka trasy</span>
                    <input
                      value={form.delka_trasy}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          delka_trasy: event.target.value,
                        })
                      }
                      placeholder="např. 27 km"
                    />
                  </label>

                  <label className="admin-connection-wide">
                    <span>Poznámka</span>
                    <input
                      value={form.poznamka}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          poznamka: event.target.value,
                        })
                      }
                      placeholder="Poznámka ke spoji"
                    />
                  </label>

                  <label>
                    <span>OIS</span>
                    <input
                      value={form.ois}
                      onChange={(event) =>
                        setForm({
                          ...form,
                          ois: event.target.value,
                        })
                      }
                      placeholder="např. 572/13"
                    />
                  </label>
                </div>
                <div className="admin-connection-form-actions">
                  <button
                    type="submit"
                    className="primary-button"
                    disabled={saving}
                  >
                    {saving
                      ? "Ukládám..."
                      : editing
                      ? "💾 Uložit změny"
                      : "+ Přidat spoj"}
                  </button>
                </div>
              </form>

              {loadingConnections ? (
                <div className="empty">Načítám spoje...</div>
              ) : connections.length === 0 ? (
                <div className="admin-connections-empty compact">
                  <strong>Zatím žádné spoje</strong>
                  <span>
                    Přidej první spoj formulářem nahoře.
                  </span>
                </div>
              ) : (
                <div className="admin-connections-table-wrap">
                  <table className="admin-connections-table">
                    <thead>
                      <tr>
                        <th>#</th>
                        <th>Typ</th>
                        <th>Linkospoj</th>
                        <th>Odj.</th>
                        <th>Pří.</th>
                        <th>Úsek / činnost</th>
                        <th>Délka</th>
                        <th>Poznámka</th>
                        <th>OIS</th>
                        <th />
                      </tr>
                    </thead>
                    <tbody>
                      {connections.map((connection) => (
                        <tr
                          key={connection.id}
                          className={
                            connection.typ &&
                            connection.typ !== "SPOJ"
                              ? "admin-connection-activity-row"
                              : ""
                          }
                        >
                          <td>{connection.poradi}</td>
                          <td>
                            <span className="connection-type-badge">
                              {connection.typ === "ODPOCINEK"
                                ? "Odpočinek"
                                : connection.typ === "STRIDANI"
                                ? "Střídání"
                                : connection.typ === "SLUZEBNI_JIZDA"
                                ? "Služební jízda"
                                : "Spoj"}
                            </span>
                          </td>
                          <td>
                            <strong>{connection.spoj || "—"}</strong>
                          </td>
                          <td className="admin-connection-time">
                            {connection.odjezd
                              ? String(connection.odjezd).slice(0, 5)
                              : "—"}
                          </td>
                          <td className="admin-connection-time">
                            {connection.prijezd
                              ? String(connection.prijezd).slice(0, 5)
                              : "—"}
                          </td>
                          <td>{connection.usek || "—"}</td>
                          <td>{connection.delka_trasy || "—"}</td>
                          <td>{connection.poznamka || "—"}</td>
                          <td>{connection.ois || "—"}</td>
                          <td>
                            <div className="admin-connection-row-actions">
                              <button
                                type="button"
                                className="secondary-button"
                                onClick={() =>
                                  editConnection(connection)
                                }
                              >
                                ✏️
                              </button>

                              <button
                                type="button"
                                className="delete-button"
                                onClick={() =>
                                  deleteConnection(connection)
                                }
                              >
                                🗑️
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </>
          )}
        </section>
      </div>
    </div>
  );
}


function Departures({
  role,
  onOpenVehicle,
  onReserveTurnus,
}) {
  const manage = canManageVehicles(role);
  const { provozovny } = useProvozovny();

  const now = new Date();

  const [selectedProvozovna, setSelectedProvozovna] = useState("");
  const [selectedMonth, setSelectedMonth] = useState(
    `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`
  );

  const [breclavVariant, setBreclavVariant] = useState(() => {
    if (typeof window === "undefined") return "BEZNY";
    return (
      window.localStorage.getItem("cm-breclav-variant") ||
      "BEZNY"
    );
  });

  const [rows, setRows] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [courses, setCourses] = useState([]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [editor, setEditor] = useState(null);
  const [saving, setSaving] = useState(false);
  const [courseDetail, setCourseDetail] = useState(null);
  const [courseDetailRows, setCourseDetailRows] = useState([]);
  const [courseDetailLoading, setCourseDetailLoading] = useState(false);
  const [courseDetailError, setCourseDetailError] = useState("");
  const [cellForm, setCellForm] = useState({
    kurz_ids: [],
    poznamka: "",
  });

  useEffect(() => {
    if (selectedProvozovna) return;

    function normalizeBranchName(value) {
      return String(value || "")
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .trim();
    }

    const allowed = getMainProvozovny(provozovny);

    const preferred =
      allowed.find(
        (provozovna) =>
          normalizeBranchName(provozovna.nazev) === "400"
      ) || allowed[0];

    if (preferred) {
      setSelectedProvozovna(String(preferred.id));
    }
  }, [provozovny, selectedProvozovna]);

  async function loadReferences() {
    setError("");

    const [vehicleResult, courseResult] = await Promise.all([
      supabase
        .from("vozy")
        .select("id,cislo,vyrobce,typ,provozovna_id")
        .order("cislo", { ascending: true }),

      supabase
        .from("kurzy")
        .select("id,nazev,provozovna_id,aktivni,typ_dne,varianta,typ_vozu,zacatek,konec,zacatek_misto,stridani_misto,stridani_cas,konec_misto,druh_smeny,poznamka_turnusu")
        .order("nazev", { ascending: true }),
    ]);

    if (vehicleResult.error) {
      setError(vehicleResult.error.message);
      setVehicles([]);
    } else {
      setVehicles(vehicleResult.data || []);
    }

    if (courseResult.error) {
      setError((old) => old || courseResult.error.message);
      setCourses([]);
    } else {
      setCourses(courseResult.data || []);
    }
  }

  async function loadMonth({ silent = false } = {}) {
    if (!selectedProvozovna || !selectedMonth) {
      setRows([]);
      if (!silent) setLoading(false);
      return;
    }

    if (!silent) setLoading(true);
    setError("");

    const [yearText, monthText] = selectedMonth.split("-");
    const year = Number(yearText);
    const month = Number(monthText);

    const from = `${year}-${String(month).padStart(2, "0")}-01`;
    const lastDay = new Date(year, month, 0).getDate();
    const to = `${year}-${String(month).padStart(2, "0")}-${String(
      lastDay
    ).padStart(2, "0")}`;

    const { data, error: loadError } = await supabase
      .from("vypravy")
      .select("*")
      .eq("provozovna_id", Number(selectedProvozovna))
      .gte("datum", from)
      .lte("datum", to)
      .order("datum", { ascending: true });

    if (loadError) {
      setError(loadError.message);
      setRows([]);
    } else {
      setRows(data || []);
    }

    if (!silent) setLoading(false);
  }

  useEffect(() => {
    loadReferences();
  }, []);

  useEffect(() => {
    loadMonth();
  }, [selectedProvozovna, selectedMonth]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(
      "cm-breclav-variant",
      breclavVariant
    );
  }, [breclavVariant]);

  useEffect(() => {
    const monthNumber = Number(
      String(selectedMonth).split("-")[1]
    );

    setBreclavVariant(
      monthNumber === 8
        ? "PRAZDNINY"
        : "BEZNY"
    );
  }, [selectedMonth]);

  const [yearText, monthText] = selectedMonth.split("-");
  const year = Number(yearText);
  const month = Number(monthText);
  const daysInMonth = new Date(year, month, 0).getDate();

  const days = Array.from(
    { length: daysInMonth },
    (_, index) => index + 1
  );

  const selectedProvozovnaRow =
    provozovny.find(
      (item) => String(item.id) === String(selectedProvozovna)
    ) || null;

  function normalizeBranchName(value) {
    return String(value || "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/ł/g, "l")
      .replace(/Ł/g, "l")
      .toLowerCase()
      .trim();
  }

  const departureProvozovny = getMainProvozovny(provozovny);

  const visibleVehicles = vehicles.filter(
    (vehicle) =>
      String(vehicle.provozovna_id) === String(selectedProvozovna)
  );

  const visibleCourses = courses.filter(
    (course) =>
      course.aktivni &&
      String(course.provozovna_id) === String(selectedProvozovna)
  );

  const isBreclavSelected =
    String(selectedProvozovnaRow?.kod || "")
      .trim()
      .toUpperCase() === "BRE" ||
    normalizeBranchName(selectedProvozovnaRow?.nazev).includes(
      "breclav"
    );

  const activeVariantCourses = visibleCourses.filter((course) => {
    if (!isBreclavSelected) return true;
    if (!course.varianta) return true;
    return course.varianta === breclavVariant;
  });

  function coursesForDay(day) {
    const date = new Date(year, month - 1, day);
    const weekday = date.getDay();
    const isWeekend = weekday === 0 || weekday === 6;

    return activeVariantCourses.filter((course) => {
      if (!course.typ_dne) return true;
      if (course.typ_dne === "DENNE") return true;
      if (course.typ_dne === "NE") return weekday === 0;
      if (course.typ_dne === "VIKEND") return isWeekend;
      if (course.typ_dne === "PD") return !isWeekend;
      return true;
    });
  }

  function isoDate(day) {
    return `${year}-${String(month).padStart(2, "0")}-${String(
      day
    ).padStart(2, "0")}`;
  }

  function getEntries(vehicleId, day) {
    const date = isoDate(day);

    return rows.filter(
      (row) =>
        String(row.vuz_id) === String(vehicleId) &&
        row.datum === date
    );
  }

  function getCourse(row) {
    if (!row) return null;

    return (
      courses.find(
        (course) => String(course.id) === String(row.kurz_id)
      ) ||
      courses.find(
        (course) =>
          row.linka &&
          String(course.nazev).trim().toLowerCase() ===
            String(row.linka).trim().toLowerCase()
      ) ||
      null
    );
  }

  function dayInfo(day) {
    const date = new Date(year, month - 1, day);
    const weekdayIndex = date.getDay();

    const names = ["Ne", "Po", "Út", "St", "Čt", "Pá", "So"];
    const today = new Date();

    return {
      name: names[weekdayIndex],
      weekend: weekdayIndex === 0 || weekdayIndex === 6,
      today:
        date.getFullYear() === today.getFullYear() &&
        date.getMonth() === today.getMonth() &&
        date.getDate() === today.getDate(),
    };
  }

  function openEditor(vehicle, day) {
    if (!manage) return;

    const entries = getEntries(vehicle.id, day);

    setError("");
    setSuccess("");

    setEditor({
      vehicle,
      day,
      date: isoDate(day),
      rows: entries,
      courses: coursesForDay(day),
    });

    setCellForm({
      kurz_ids: entries
        .filter((row) => row.kurz_id)
        .map((row) => String(row.kurz_id)),
      poznamka: entries[0]?.poznamka || "",
    });
  }

  function closeEditor() {
    setEditor(null);
    setCellForm({
      kurz_ids: [],
      poznamka: "",
    });
  }

  function captureDepartureScrollPosition() {
    if (
      typeof window === "undefined" ||
      typeof document === "undefined" ||
      !editor
    ) {
      return null;
    }

    const selector =
      `[data-departure-cell="${editor.vehicle.id}-${editor.day}"]`;

    const cell = document.querySelector(selector);
    const tableWrap = document.querySelector(
      ".departures-table-wrap"
    );

    return {
      selector,
      scrollY: window.scrollY,
      cellTop: cell
        ? cell.getBoundingClientRect().top
        : null,
      tableScrollLeft: tableWrap
        ? tableWrap.scrollLeft
        : 0,
    };
  }

  function restoreDepartureScrollPosition(snapshot) {
    if (
      !snapshot ||
      typeof window === "undefined" ||
      typeof document === "undefined"
    ) {
      return;
    }

    // Dvě RAF počkají na React render i přepočet layoutu.
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        const cell = document.querySelector(snapshot.selector);
        const tableWrap = document.querySelector(
          ".departures-table-wrap"
        );

        let targetY = snapshot.scrollY;

        if (cell && snapshot.cellTop != null) {
          const currentTop =
            cell.getBoundingClientRect().top;

          targetY =
            window.scrollY +
            (currentTop - snapshot.cellTop);
        }

        window.scrollTo({
          top: Math.max(0, targetY),
          left: window.scrollX,
          behavior: "auto",
        });

        if (tableWrap) {
          tableWrap.scrollLeft =
            snapshot.tableScrollLeft;
        }
      });
    });
  }

  function toggleCourse(courseId) {
    const id = String(courseId);

    setCellForm((old) => ({
      ...old,
      kurz_ids: old.kurz_ids.includes(id)
        ? old.kurz_ids.filter((item) => item !== id)
        : [...old.kurz_ids, id],
    }));
  }

  async function openCourseDetail(
    course,
    reservationDate = editor?.date || null
  ) {
    setCourseDetail({
      ...course,
      reservation_date: reservationDate,
      reservation_provozovna_id: selectedProvozovna,
    });
    setCourseDetailRows([]);
    setCourseDetailError("");
    setCourseDetailLoading(true);

    const { data, error: detailError } = await supabase
      .from("kurz_spoje")
      .select("id,poradi,typ,spoj,odjezd,prijezd,usek,odkud,kam,delka_trasy,poznamka,ois")
      .eq("kurz_id", course.id)
      .order("poradi", { ascending: true });

    if (detailError) {
      setCourseDetailError(detailError.message);
      setCourseDetailRows([]);
    } else {
      setCourseDetailRows(data || []);
    }

    setCourseDetailLoading(false);
  }

  function closeCourseDetail() {
    setCourseDetail(null);
    setCourseDetailRows([]);
    setCourseDetailError("");
    setCourseDetailLoading(false);
  }

  async function saveEntry(e) {
    e.preventDefault();

    if (!editor || cellForm.kurz_ids.length === 0) {
      setError("Vyber alespoň jednu výpravu / pořadí.");
      return;
    }

    const scrollSnapshot =
      captureDepartureScrollPosition();

    const selectedCourses = cellForm.kurz_ids
      .map((id) =>
        courses.find(
          (item) => String(item.id) === String(id)
        )
      )
      .filter(Boolean);

    if (selectedCourses.length !== cellForm.kurz_ids.length) {
      setError("Některá vybraná výprava nebyla nalezena.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const existingRows = editor.rows || [];
    const desiredIds = new Set(
      selectedCourses.map((course) => String(course.id))
    );

    const rowsToDelete = existingRows.filter(
      (row) =>
        !row.kurz_id ||
        !desiredIds.has(String(row.kurz_id))
    );

    const existingCourseIds = new Set(
      existingRows
        .filter((row) => row.kurz_id)
        .map((row) => String(row.kurz_id))
    );

    const coursesToInsert = selectedCourses.filter(
      (course) => !existingCourseIds.has(String(course.id))
    );

    const retainedRows = existingRows.filter(
      (row) =>
        row.kurz_id &&
        desiredIds.has(String(row.kurz_id))
    );

    const note = cellForm.poznamka.trim() || null;

    if (rowsToDelete.length > 0) {
      const deleteResult = await supabase
        .from("vypravy")
        .delete()
        .in(
          "id",
          rowsToDelete.map((row) => row.id)
        );

      if (deleteResult.error) {
        setError(deleteResult.error.message);
        setSaving(false);
        return;
      }
    }

    if (retainedRows.length > 0) {
      const updateResult = await supabase
        .from("vypravy")
        .update({ poznamka: note })
        .in(
          "id",
          retainedRows.map((row) => row.id)
        );

      if (updateResult.error) {
        setError(updateResult.error.message);
        setSaving(false);
        return;
      }
    }

    if (coursesToInsert.length > 0) {
      const payload = coursesToInsert.map((course) => ({
        datum: editor.date,
        provozovna_id: Number(selectedProvozovna),
        vuz_id: Number(editor.vehicle.id),
        kurz_id: Number(course.id),
        linka: course.nazev,
        ridic_id: null,
        poznamka: note,
      }));

      const insertResult = await supabase
        .from("vypravy")
        .insert(payload);

      if (insertResult.error) {
        setError(insertResult.error.message);
        setSaving(false);
        return;
      }
    }

    setSuccess(
      `Vůz ${editor.vehicle.cislo} má pro ${editor.date} přiřazeno ${selectedCourses.length} ${
        selectedCourses.length === 1 ? "pořadí" : "pořadí"
      }.`
    );

    closeEditor();
    await loadMonth({ silent: true });
    setSaving(false);
    restoreDepartureScrollPosition(scrollSnapshot);
  }

  async function deleteEntry() {
    const existingRows = editor?.rows || [];
    if (existingRows.length === 0) return;

    const scrollSnapshot =
      captureDepartureScrollPosition();

    if (
      !window.confirm(
        `Opravdu chceš odebrat všechny výpravy vozu ${editor.vehicle.cislo} dne ${editor.date}?`
      )
    ) {
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const { error: deleteError } = await supabase
      .from("vypravy")
      .delete()
      .in(
        "id",
        existingRows.map((row) => row.id)
      );

    if (deleteError) {
      setError(deleteError.message);
      setSaving(false);
      return;
    }

    setSuccess("Všechny výpravy byly z vozu pro tento den odebrány.");
    closeEditor();
    await loadMonth({ silent: true });
    setSaving(false);
    restoreDepartureScrollPosition(scrollSnapshot);
  }

  function changeMonth(offset) {
    const date = new Date(year, month - 1 + offset, 1);

    setSelectedMonth(
      `${date.getFullYear()}-${String(
        date.getMonth() + 1
      ).padStart(2, "0")}`
    );
  }

  function getDepartureCourseGroups(courseRows) {
    const hasVehicleType = courseRows.some((course) => course.typ_vozu);

    if (hasVehicleType) {
      const typeGroups = [
        {
          key: "solo",
          title: "Sólo",
          courses: courseRows.filter((course) => course.typ_vozu === "SOLO"),
        },
        {
          key: "kloub",
          title: "Kloub",
          courses: courseRows.filter((course) => course.typ_vozu === "KLOUB"),
        },
        {
          key: "ostatni",
          title: "Ostatní",
          courses: courseRows.filter(
            (course) =>
              course.typ_vozu !== "SOLO" &&
              course.typ_vozu !== "KLOUB"
          ),
        },
      ];

      return typeGroups
        .map((group) => ({
          ...group,
          courses: group.courses.sort((a, b) =>
            String(a.nazev).localeCompare(String(b.nazev), "cs", {
              numeric: true,
              sensitivity: "base",
            })
          ),
        }))
        .filter((group) => group.courses.length > 0);
    }

    const groups = [
      {
        key: "liberec",
        title: "ČSAD Liberec",
        test: (name) =>
          ["205.01", "206.01", "210.11", "210.21", "211.01", "304.01", "305.01", "306.01", "309.01", "310.01", "311.01", "205.67", "206.07", "303.07", "317.67"].includes(name),
      },
      {
        key: "mhdcl",
        title: "MHDCL",
        test: (name) => /^MHDCL/i.test(name),
      },
      {
        key: "ceska-lipa",
        title: "ČSAD Česká Lípa",
        test: (name) =>
          ["51.01", "52.01", "53.01", "54.01", "55.01", "56.01", "57.01", "58.01", "59.01", "51.67", "52.67", "53.67", "54.67", "55.67", "56.67", "57.67", "58.67", "59.67"].includes(name),
      },
      {
        key: "stredni-cechy",
        title: "Střední Čechy",
        test: (name) => /^349\d+$/i.test(name),
      },
      {
        key: "smluvni",
        title: "Smluvní doprava",
        test: (name) => /^S1\./i.test(name),
      },
      {
        key: "nad",
        title: "NAD",
        test: (name) => /^(XR|XS|XL)/i.test(name),
      },
    ];

    const result = groups.map((group) => ({
      ...group,
      courses: courseRows
        .filter((course) => group.test(String(course.nazev || "").trim()))
        .sort((a, b) =>
          String(a.nazev).localeCompare(String(b.nazev), "cs", {
            numeric: true,
            sensitivity: "base",
          })
        ),
    }));

    const usedIds = new Set(
      result.flatMap((group) => group.courses.map((course) => String(course.id)))
    );

    const otherCourses = courseRows
      .filter((course) => !usedIds.has(String(course.id)))
      .sort((a, b) =>
        String(a.nazev).localeCompare(String(b.nazev), "cs", {
          numeric: true,
          sensitivity: "base",
        })
      );

    if (otherCourses.length > 0) {
      result.push({
        key: "ostatni",
        title: "Ostatní",
        courses: otherCourses,
      });
    }

    return result.filter((group) => group.courses.length > 0);
  }

  const departureCourseGroups = getDepartureCourseGroups(
    editor?.courses || activeVariantCourses
  );

  function getMissingCoursesForDay(day) {
    const date = isoDate(day);

    const assignedCourseIds = new Set(
      rows
        .filter(
          (row) =>
            row.datum === date &&
            row.kurz_id
        )
        .map((row) => String(row.kurz_id))
    );

    return coursesForDay(day).filter(
      (course) => !assignedCourseIds.has(String(course.id))
    );
  }

  function getAssignedCountForDay(day) {
    const date = isoDate(day);

    return rows.filter(
      (row) =>
        row.datum === date &&
        row.kurz_id
    ).length;
  }

  return (
    <div className="departures-page">
      <div className="topbar">
        <div>
          <div className="departures-eyebrow">
            VÝPRAVOVÝ PLÁN
          </div>
          <h1>Výpravy</h1>
          <p>
            Vozy provozovny a jejich výpravy podle jednotlivých dnů
          </p>
        </div>

        <div className="profile-badge">
          {visibleVehicles.length} VOZŮ
        </div>
      </div>

      {error && (
        <div className="error-box">
          <strong>Chyba:</strong>
          <br />
          {error}
        </div>
      )}

      {success && (
        <div className="success-box">
          {success}
        </div>
      )}

      <div className="departures-toolbar panel">
        <div className="departures-branches departures-tabs">
          {departureProvozovny.map((provozovna) => (
            <button
              type="button"
              key={provozovna.id}
              className={
                String(provozovna.id) === String(selectedProvozovna)
                  ? "active"
                  : ""
              }
              onClick={() =>
                setSelectedProvozovna(String(provozovna.id))
              }
            >
              {provozovna.nazev}
            </button>
          ))}
        </div>

        <div className="departures-month-control">
          <button
            type="button"
            className="secondary-button"
            onClick={() => changeMonth(-1)}
          >
            ‹
          </button>

          <input
            type="month"
            value={selectedMonth}
            onChange={(e) => setSelectedMonth(e.target.value)}
          />

          <button
            type="button"
            className="secondary-button"
            onClick={() => changeMonth(1)}
          >
            ›
          </button>
        </div>
      </div>

      {selectedProvozovnaRow && (
        <div className="departures-selected-branch">
          <div>
            <span>PROVOZOVNA</span>
            <strong>{selectedProvozovnaRow.nazev}</strong>
          </div>

          <div>
            <span>VOZY</span>
            <strong>{visibleVehicles.length}</strong>
          </div>

          <div>
            <span>VÝPRAVY / POŘADÍ</span>
            <strong>{activeVariantCourses.length}</strong>
          </div>
        </div>
      )}

      {isBreclavSelected && (
        <div className="breclav-variant-panel">
          <div>
            <span>REŽIM BŘECLAVSKO</span>
            <strong>
              {breclavVariant === "PRAZDNINY"
                ? "Prázdniny"
                : "Běžný provoz"}
            </strong>
            <small>
              {Number(String(selectedMonth).split("-")[1]) === 8
                ? "Srpen = automaticky prázdninový provoz"
                : "Automaticky podle zvoleného měsíce"}
            </small>
          </div>

          <div className="breclav-variant-buttons">
            <button
              type="button"
              className={
                breclavVariant === "BEZNY" ? "active" : ""
              }
              onClick={() => setBreclavVariant("BEZNY")}
            >
              Běžný provoz
            </button>

            <button
              type="button"
              className={
                breclavVariant === "PRAZDNINY" ? "active" : ""
              }
              onClick={() => setBreclavVariant("PRAZDNINY")}
            >
              Prázdniny
            </button>
          </div>
        </div>
      )}

      {!selectedProvozovna ? (
        <div className="empty">Vyber provozovnu.</div>
      ) : loading ? (
        <div className="empty">Načítání výprav...</div>
      ) : visibleVehicles.length === 0 ? (
        <div className="empty">
          Provozovna{" "}
          <strong>{selectedProvozovnaRow?.nazev}</strong>{" "}
          zatím nemá přiřazené žádné vozy. Přiřaď je v
          Administraci vozů.
        </div>
      ) : (
        <>
          <div className="departures-mobile-hint">
            ← Posuň tabulku do stran • číslo vozu zůstává vlevo
          </div>

          <div className="departures-table-wrap">
          <table className="departures-month-table">
            <thead>
              <tr>
                <th className="departures-vehicle-column">
                  Vůz
                </th>

                {days.map((day) => {
                  const info = dayInfo(day);

                  return (
                    <th
                      key={day}
                      className={[
                        info.weekend ? "weekend" : "",
                        info.today ? "today" : "",
                      ]
                        .filter(Boolean)
                        .join(" ")}
                    >
                      <span>{info.name}</span>
                      <strong>{day}</strong>

                      {getMissingCoursesForDay(day).length > 0 && (
                        <em
                          className="departure-missing-badge"
                          title={`${getMissingCoursesForDay(day).length} nevypravených pořadí`}
                        >
                          !{getMissingCoursesForDay(day).length}
                        </em>
                      )}
                    </th>
                  );
                })}
              </tr>
            </thead>

            <tbody>
              {visibleVehicles.map((vehicle) => (
                <tr key={vehicle.id}>
                  <td className="departures-vehicle-column">
                    <button
                      type="button"
                      className="departure-vehicle-link"
                      onClick={() => {
                        if (onOpenVehicle) {
                          onOpenVehicle(vehicle.id);
                        }
                      }}
                      title={`Otevřít detail vozu ${vehicle.cislo}`}
                    >
                      <strong>{vehicle.cislo}</strong>
                      <small>
                        {vehicle.vyrobce || ""} {vehicle.typ || ""}
                      </small>
                    </button>
                  </td>

                  {days.map((day) => {
                    const info = dayInfo(day);
                    const entries = getEntries(vehicle.id, day);
                    const assigned = entries.map((row) => ({
                      row,
                      course: getCourse(row),
                    }));

                    return (
                      <td
                        key={day}
                        data-departure-cell={`${vehicle.id}-${day}`}
                        className={[
                          "departure-cell",
                          info.weekend ? "weekend" : "",
                          info.today ? "today" : "",
                          entries.length > 0 ? "filled" : "",
                          entries.length > 1 ? "multi" : "",
                          manage ? "editable" : "",
                        ]
                          .filter(Boolean)
                          .join(" ")}
                        onClick={() => openEditor(vehicle, day)}
                        title={
                          entries.length > 0
                            ? assigned
                                .map(
                                  ({ row, course }) =>
                                    course?.nazev ||
                                    row.linka ||
                                    "Výprava"
                                )
                                .join(", ")
                            : manage
                            ? "Klikni pro přiřazení jedné nebo více výprav"
                            : ""
                        }
                      >
                        {entries.length > 0 ? (
                          <div className="departure-cell-course-list">
                            {assigned.map(({ row, course }) =>
                              course ? (
                                <button
                                  type="button"
                                  className="departure-cell-course-tag departure-cell-course-link"
                                  key={row.id}
                                  onClick={(event) => {
                                    event.stopPropagation();
                                    openCourseDetail(
                                      course,
                                      isoDate(day)
                                    );
                                  }}
                                  title={`Zobrazit spoje turnusu ${course.nazev}`}
                                >
                                  {course.nazev}
                                </button>
                              ) : (
                                <span
                                  className="departure-cell-course-tag"
                                  key={row.id}
                                >
                                  {row.linka || "-"}
                                </span>
                              )
                            )}
                          </div>
                        ) : (
                          <span className="departure-cell-empty">
                            {manage ? "+" : ""}
                          </span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}

              <tr className="departure-missing-row">
                <td className="departures-vehicle-column departure-missing-label">
                  <strong>Nevypraveno</strong>
                  <small>Chybějící pořadí</small>
                </td>

                {days.map((day) => {
                  const missing = getMissingCoursesForDay(day);

                  return (
                    <td
                      key={`missing-${day}`}
                      className={[
                        "departure-missing-cell",
                        missing.length > 0 ? "has-missing" : "all-dispatched",
                      ].join(" ")}
                    >
                      {missing.length === 0 ? (
                        <span className="departure-all-ok">✓</span>
                      ) : (
                        <div className="departure-missing-list">
                          <strong>{missing.length}</strong>
                          <div className="departure-missing-names">
                            {missing.map((course) => (
                              <span key={course.id}>
                                {course.nazev}
                              </span>
                            ))}
                          </div>
                        </div>
                      )}
                    </td>
                  );
                })}
              </tr>
            </tbody>
          </table>
          </div>
        </>
      )}

      {selectedProvozovna &&
        activeVariantCourses.length > 0 && (
          <div className="departure-missing-summary">
            <div>
              <strong>Kontrola vypravení</strong>
              <span>
                Červené označení znamená, že v daný den není některé pořadí přiřazené žádnému vozu.
              </span>
            </div>

            <div className="departure-missing-summary-stats">
              {days
                .filter((day) => getMissingCoursesForDay(day).length > 0)
                .slice(0, 7)
                .map((day) => (
                  <span key={day}>
                    {day}. den: {getMissingCoursesForDay(day).length}
                  </span>
                ))}
            </div>
          </div>
        )}

      {manage &&
        selectedProvozovna &&
        activeVariantCourses.length === 0 && (
          <div className="departures-warning">
            Pro provozovnu{" "}
            <strong>{selectedProvozovnaRow?.nazev}</strong>{" "}
            nejsou zatím přidané žádné výpravy / pořadí.
            Přidej je v Administraci → Kurzy.
          </div>
        )}

      {editor && (
        <div
          className="departure-modal-backdrop"
          onMouseDown={(e) => {
            if (
              e.target === e.currentTarget &&
              !saving
            ) {
              closeEditor();
            }
          }}
        >
          <div className="departure-modal">
            <div className="departure-modal-head">
              <div>
                <span>
                  {selectedProvozovnaRow?.nazev}
                </span>
                <h2>Vůz {editor.vehicle.cislo}</h2>
                <p>
                  {new Date(
                    `${editor.date}T00:00:00`
                  ).toLocaleDateString("cs-CZ", {
                    weekday: "long",
                    day: "numeric",
                    month: "long",
                    year: "numeric",
                  })}
                </p>
              </div>

              <button
                type="button"
                className="departure-modal-close"
                onClick={closeEditor}
                disabled={saving}
              >
                ✕
              </button>
            </div>

            <form onSubmit={saveEntry}>
              <div className="notification-field">
                <label>Provozovna</label>
                <input
                  value={
                    selectedProvozovnaRow?.nazev || ""
                  }
                  disabled
                />
              </div>

              <div className="notification-field">
                <label>Vůz</label>
                <input
                  value={`${editor.vehicle.cislo}${
                    editor.vehicle.vyrobce
                      ? ` – ${editor.vehicle.vyrobce}`
                      : ""
                  }${
                    editor.vehicle.typ
                      ? ` ${editor.vehicle.typ}`
                      : ""
                  }`}
                  disabled
                />
              </div>

              <div className="departure-day-type-banner">
                <span>Typ dne</span>
                <strong>
                  {(() => {
                    const d = new Date(`${editor.date}T00:00:00`);
                    const isWeekend = d.getDay() === 0 || d.getDay() === 6;
                    return isWeekend ? "Víkend" : "Pracovní den";
                  })()}
                </strong>
              </div>

              <div className="notification-field">
                <label>Výpravy / pořadí – můžeš vybrat více</label>

                <div className="departure-multi-summary">
                  <strong>{cellForm.kurz_ids.length}</strong>
                  <span>
                    {cellForm.kurz_ids.length === 1
                      ? "vybrané pořadí"
                      : "vybraných pořadí"}
                  </span>
                </div>

                {(editor.courses || []).length === 0 ? (
                  <div className="departure-course-empty">
                    Pro tuto provozovnu zatím nejsou přidané žádné kurzy.
                  </div>
                ) : (
                  <div className="departure-course-groups">
                    {departureCourseGroups.map((group) => (
                      <div
                        className="departure-course-group"
                        key={group.key}
                      >
                        <div className="departure-course-group-title">
                          {group.title}
                        </div>

                        <div className="departure-course-picker">
                          {group.courses.map((course) => {
                            const selected = cellForm.kurz_ids.includes(
                              String(course.id)
                            );

                            return (
                              <div
                                key={course.id}
                                className={`departure-course-card ${
                                  selected ? "active" : ""
                                }`}
                              >
                                <button
                                  type="button"
                                  className="departure-course-select"
                                  onClick={() => toggleCourse(course.id)}
                                  aria-label={
                                    selected
                                      ? `Odebrat ${course.nazev} z výběru`
                                      : `Přidat ${course.nazev} do výběru`
                                  }
                                  title={
                                    selected
                                      ? "Odebrat z vozu"
                                      : "Přidat na vůz"
                                  }
                                >
                                  {selected ? "✓" : "+"}
                                </button>

                                <button
                                  type="button"
                                  className="departure-course-detail-button departure-course-number-only"
                                  onClick={() =>
                                    openCourseDetail(
                                      course,
                                      editor?.date || null
                                    )
                                  }
                                  title={`Zobrazit spoje turnusu ${course.nazev}`}
                                >
                                  <strong>{course.nazev}</strong>
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className="notification-field">
                <label>Poznámka</label>
                <textarea
                  rows={4}
                  value={cellForm.poznamka}
                  onChange={(e) =>
                    setCellForm({
                      ...cellForm,
                      poznamka: e.target.value,
                    })
                  }
                  placeholder="Volitelná poznámka..."
                />
              </div>

              <div className="departure-modal-actions">
                {(editor.rows || []).length > 0 && (
                  <button
                    type="button"
                    className="delete-button"
                    onClick={deleteEntry}
                    disabled={saving}
                  >
                    🗑️ Odebrat všechny
                  </button>
                )}

                <div>
                  <button
                    type="button"
                    className="secondary-button"
                    onClick={closeEditor}
                    disabled={saving}
                  >
                    Zrušit
                  </button>

                  <button
                    type="submit"
                    className="primary-button"
                    disabled={
                      saving ||
                      (editor.courses || []).length === 0 ||
                      cellForm.kurz_ids.length === 0
                    }
                  >
                    {saving
                      ? "Ukládám..."
                      : "💾 Uložit výpravy"}
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      {courseDetail && (
        <div
          className="modal-backdrop turnus-detail-backdrop"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              closeCourseDetail();
            }
          }}
        >
          <div className="turnus-detail-modal">
            <div className="turnus-detail-head">
              <div>
                <span className="turnus-detail-kicker">
                  SPOJE TURNUSE
                </span>
                <h2>{courseDetail.nazev}</h2>
                <p>
                  {courseDetail.typ_dne
                    ? getCourseDayLabel(courseDetail.typ_dne)
                    : "Bez omezení dne"}
                  {courseDetail.varianta
                    ? ` · ${getCourseVariantLabel(courseDetail.varianta)}`
                    : ""}
                  {" · "}
                  {courseDetail.zacatek
                    ? String(courseDetail.zacatek).slice(0, 5)
                    : "—"}
                  {" – "}
                  {courseDetail.konec
                    ? String(courseDetail.konec).slice(0, 5)
                    : "—"}
                </p>
              </div>

              <button
                type="button"
                className="stk-dashboard-modal-close"
                onClick={closeCourseDetail}
                aria-label="Zavřít detail turnusu"
              >
                ✕
              </button>
            </div>

            <div className="turnus-detail-summary turnus-detail-summary-full">
              <div>
                <span>Turnus</span>
                <strong>{courseDetail.nazev}</strong>
              </div>
              <div>
                <span>Režim</span>
                <strong>
                  {courseDetail.typ_dne === "VIKEND"
                    ? "Víkend"
                    : "Pracovní den"}
                  {courseDetail.varianta === "PRAZDNINY"
                    ? " · prázdniny"
                    : ""}
                </strong>
              </div>
              <div>
                <span>Začátek</span>
                <strong>
                  {courseDetail.zacatek
                    ? String(courseDetail.zacatek).slice(0, 5)
                    : "—"}
                </strong>
                <small>{courseDetail.zacatek_misto || ""}</small>
              </div>
              {courseDetail.stridani_cas && (
                <div>
                  <span>Střídání</span>
                  <strong>
                    {String(courseDetail.stridani_cas).slice(0, 5)}
                  </strong>
                  <small>{courseDetail.stridani_misto || ""}</small>
                </div>
              )}
              <div>
                <span>Konec</span>
                <strong>
                  {courseDetail.konec
                    ? String(courseDetail.konec).slice(0, 5)
                    : "—"}
                </strong>
                <small>{courseDetail.konec_misto || ""}</small>
              </div>
              <div>
                <span>Druh směny</span>
                <strong>{courseDetail.druh_smeny || "—"}</strong>
              </div>
            </div>

            {courseDetail.poznamka_turnusu && (
              <div className="turnus-course-note">
                <strong>Poznámka ke kurzu:</strong>
                <span>{courseDetail.poznamka_turnusu}</span>
              </div>
            )}
            {courseDetailError && (
              <div className="error-box">{courseDetailError}</div>
            )}

            {courseDetailLoading ? (
              <div className="turnus-detail-loading">Načítám spoje...</div>
            ) : courseDetailRows.length === 0 ? (
              <div className="turnus-detail-empty">
                Pro tento turnus zatím nejsou uložené žádné spoje.
              </div>
            ) : (
              <div className="turnus-spoje-wrap">
                <table className="turnus-spoje-table turnus-spoje-table-full">
                  <thead>
                    <tr>
                      <th>Linkospoj</th>
                      <th>Odj.</th>
                      <th>Pří.</th>
                      <th>Úsek / činnost</th>
                      <th>Délka trasy</th>
                      <th>Poznámky</th>
                      <th>OIS</th>
                    </tr>
                  </thead>
                  <tbody>
                    {courseDetailRows.map((row) => {
                      const activity =
                        row.typ && row.typ !== "SPOJ";

                      return (
                        <tr
                          key={row.id}
                          className={
                            activity
                              ? `turnus-activity-row ${String(
                                  row.typ
                                ).toLowerCase()}`
                              : ""
                          }
                        >
                          <td>
                            <strong>
                              {row.spoj ||
                                (row.typ === "ODPOCINEK"
                                  ? "Odpočinek"
                                  : row.typ === "STRIDANI"
                                  ? "Střídání"
                                  : row.typ === "SLUZEBNI_JIZDA"
                                  ? "Služební jízda"
                                  : "—")}
                            </strong>
                          </td>
                          <td className="turnus-time">
                            {row.odjezd
                              ? String(row.odjezd).slice(0, 5)
                              : "—"}
                          </td>
                          <td className="turnus-time">
                            {row.prijezd
                              ? String(row.prijezd).slice(0, 5)
                              : "—"}
                          </td>
                          <td>{row.usek || "—"}</td>
                          <td>{row.delka_trasy || "—"}</td>
                          <td>{row.poznamka || "—"}</td>
                          <td>{row.ois || "—"}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}

            <div className="turnus-detail-actions">
              {courseDetail.reservation_date && onReserveTurnus && (
                <button
                  type="button"
                  className="primary-button turnus-reservation-button"
                  onClick={() => {
                    const target = {
                      date: courseDetail.reservation_date,
                      branchId:
                        courseDetail.reservation_provozovna_id ||
                        selectedProvozovna,
                      courseId: courseDetail.id,
                    };

                    closeCourseDetail();
                    closeEditor();
                    onReserveTurnus(target);
                  }}
                >
                  📅 Rezervovat směnu
                </button>
              )}

              {manage && editor && (
                <button
                  type="button"
                  className={`primary-button ${
                    cellForm.kurz_ids.includes(String(courseDetail.id))
                      ? "turnus-selected-button"
                      : ""
                  }`}
                  onClick={() => toggleCourse(courseDetail.id)}
                >
                  {cellForm.kurz_ids.includes(String(courseDetail.id))
                    ? "✓ Turnus je vybraný – odebrat"
                    : "+ Přidat turnus na vůz"}
                </button>
              )}

              <button
                type="button"
                className="secondary-button"
                onClick={closeCourseDetail}
              >
                Zavřít
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function AuditLog() {
  const [rows, setRows] = useState([]);
  const [profiles, setProfiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  async function loadAudit() {
    setLoading(true);
    setError("");

    const [auditResult, profileResult] = await Promise.all([
      supabase
        .from("audit_log")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(200),

      supabase
        .from("profiles")
        .select("id,jmeno"),
    ]);

    if (auditResult.error) {
      console.error("AUDIT LOG ERROR:", auditResult.error);
      setError(auditResult.error.message);
      setRows([]);
    } else {
      setRows(auditResult.data || []);
    }

    if (!profileResult.error) {
      setProfiles(profileResult.data || []);
    }

    setLoading(false);
  }

  useEffect(() => {
    loadAudit();
  }, []);

  function actorName(id) {
    if (!id) return "Systém / administrátor";

    return (
      profiles.find(
        (profile) => String(profile.id) === String(id)
      )?.jmeno || "Uživatel"
    );
  }

  return (
    <div>
      <div className="topbar">
        <div>
          <h1>Audit log</h1>
          <p>Historie administrativních změn</p>
        </div>

        <div className="profile-badge">
          {rows.length} ZÁZNAMŮ
        </div>
      </div>

      {error && (
        <div className="error-box">
          <strong>Audit log se nepodařilo načíst:</strong>
          <br />
          {error}
        </div>
      )}

      <div className="panel">
        <div className="users-toolbar">
          <div>
            <h2>Historie změn</h2>
            <p className="muted">
              Automatické záznamy administrativních akcí.
            </p>
          </div>

          <button
            type="button"
            className="secondary-button"
            onClick={loadAudit}
            disabled={loading}
          >
            {loading ? "Načítám..." : "↻ Obnovit"}
          </button>
        </div>

        {loading ? (
          <div className="empty">
            Načítání audit logu...
          </div>
        ) : !error && rows.length === 0 ? (
          <div className="empty">
            Zatím tu nejsou žádné auditní záznamy.
          </div>
        ) : (
          <div className="audit-log-list">
            {rows.map((row) => (
              <div className="audit-log-item" key={row.id}>
                <div className="audit-log-icon">🕘</div>

                <div className="audit-log-main">
                  <strong>{row.akce}</strong>

                  <div className="audit-log-detail">
                    {row.detail || "Bez detailu"}
                  </div>

                  <div className="audit-log-meta">
                    <span>{actorName(row.uzivatel_id)}</span>
                    <span>
                      {row.entita}
                      {row.entita_id
                        ? ` #${row.entita_id}`
                        : ""}
                    </span>
                  </div>
                </div>

                <time>
                  {row.created_at
                    ? new Date(
                        row.created_at
                      ).toLocaleString("cs-CZ")
                    : "-"}
                </time>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}


/* =========================================================
   INTERNÍ KANÁL – DÍLNA
========================================================= */

function WorkshopChannel({ user, role }) {
  const canEdit = canEditWorkshop(role);
  const [posts, setPosts] = useState([]);
  const [partOrders, setPartOrders] = useState([]);
  const [workshopVehicles, setWorkshopVehicles] = useState([]);
  const [workshopBranches, setWorkshopBranches] = useState([]);
  const [loadingWorkshopVehicles, setLoadingWorkshopVehicles] = useState(false);
  const [profiles, setProfiles] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editingPartOrderId, setEditingPartOrderId] = useState(null);
  const [form, setForm] = useState({
    nadpis: "",
    obsah: "",
    priorita: "BĚŽNÁ",
    pripnuto: false,
  });
  const [partForm, setPartForm] = useState({
    nazev_dilu: "",
    katalogove_cislo: "",
    mnozstvi: 1,
    vuz: "",
    provozovna_id: "",
    dodavatel: "",
    odkaz: "",
    cena_ks: "",
    poznamka: "",
    priorita: "BĚŽNÁ",
    stav: "POŽADAVEK",
  });

  function resetForm() {
    setEditingId(null);
    setForm({
      nadpis: "",
      obsah: "",
      priorita: "BĚŽNÁ",
      pripnuto: false,
    });
  }

  function resetPartForm() {
    setEditingPartOrderId(null);
    setPartForm({
      nazev_dilu: "",
      katalogove_cislo: "",
      mnozstvi: 1,
      vuz: "",
      dodavatel: "",
      odkaz: "",
      cena_ks: "",
      poznamka: "",
      priorita: "BĚŽNÁ",
      stav: "POŽADAVEK",
    });
  }

  async function loadWorkshopBranches() {
    const { data, error: branchError } = await supabase
      .from("provozovny")
      .select("id,kod,nazev")
      .order("kod", { ascending: true });

    if (branchError) {
      console.error("WORKSHOP BRANCHES:", branchError);
      setWorkshopBranches([]);
      return;
    }

    setWorkshopBranches(getMainProvozovny(data || []));
  }

  async function loadWorkshopVehicles() {
    setLoadingWorkshopVehicles(true);

    const { data, error: vehicleError } = await supabase
      .from("vozy")
      .select("id,cislo,vyrobce,typ,spz,provozovna_id")
      .order("cislo", { ascending: true });

    if (vehicleError) {
      console.error("WORKSHOP VEHICLES:", vehicleError);
      setWorkshopVehicles([]);
      setLoadingWorkshopVehicles(false);
      return;
    }

    setWorkshopVehicles(
      (data || []).sort((a, b) =>
        String(a.cislo || "").localeCompare(
          String(b.cislo || ""),
          "cs",
          { numeric: true, sensitivity: "base" }
        )
      )
    );

    setLoadingWorkshopVehicles(false);
  }

  async function loadPartOrders() {
    const { data, error: orderError } = await supabase
      .from("workshop_part_orders")
      .select(
        "id,nazev_dilu,katalogove_cislo,mnozstvi,vuz,provozovna_id,dodavatel,odkaz,cena_ks,poznamka,priorita,stav,created_by,updated_by,created_at,updated_at"
      )
      .order("created_at", { ascending: false });

    if (orderError) {
      setError(orderError.message);
      setPartOrders([]);
      return [];
    }

    const rows = data || [];
    setPartOrders(rows);
    return rows;
  }

  async function savePartOrder(e) {
    e.preventDefault();

    if (!partForm.nazev_dilu.trim()) {
      setError("Vyplň název dílu.");
      return;
    }

    if (!partForm.provozovna_id) {
      setError("Vyber provozovnu, ze které se díl objednává.");
      return;
    }

    const quantity = Math.max(1, Number(partForm.mnozstvi) || 1);
    const price =
      String(partForm.cena_ks || "").trim() === ""
        ? null
        : Number(String(partForm.cena_ks).replace(",", "."));

    if (price !== null && (!Number.isFinite(price) || price < 0)) {
      setError("Cena za kus musí být platné nezáporné číslo.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      nazev_dilu: partForm.nazev_dilu.trim(),
      katalogove_cislo: partForm.katalogove_cislo.trim() || null,
      mnozstvi: quantity,
      vuz: partForm.vuz.trim() || null,
      provozovna_id: Number(partForm.provozovna_id),
      dodavatel: partForm.dodavatel.trim() || null,
      odkaz: partForm.odkaz.trim() || null,
      cena_ks: price,
      poznamka: partForm.poznamka.trim() || null,
      priorita: partForm.priorita,
      updated_by: user.id,
      updated_at: new Date().toISOString(),
    };

    let result;

    if (editingPartOrderId) {
      if (!canEdit) {
        setError("Objednávku může upravovat pouze administrátor.");
        setSaving(false);
        return;
      }

      result = await supabase
        .from("workshop_part_orders")
        .update({
          ...payload,
          stav: partForm.stav,
        })
        .eq("id", editingPartOrderId);
    } else {
      result = await supabase
        .from("workshop_part_orders")
        .insert({
          ...payload,
          stav: "POŽADAVEK",
          created_by: user.id,
        });
    }

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editingPartOrderId
        ? "Objednávka dílu byla upravena."
        : "Požadavek na díl byl vytvořen."
    );
    resetPartForm();
    await loadPartOrders();
    setSaving(false);
  }

  function editPartOrder(order) {
    if (!canEdit) return;

    setEditingPartOrderId(order.id);
    setPartForm({
      nazev_dilu: order.nazev_dilu || "",
      katalogove_cislo: order.katalogove_cislo || "",
      mnozstvi: order.mnozstvi || 1,
      vuz: order.vuz || "",
      provozovna_id: order.provozovna_id
        ? String(order.provozovna_id)
        : "",
      dodavatel: order.dodavatel || "",
      odkaz: order.odkaz || "",
      cena_ks: order.cena_ks ?? "",
      poznamka: order.poznamka || "",
      priorita: order.priorita || "BĚŽNÁ",
      stav: order.stav || "POŽADAVEK",
    });

    window.setTimeout(() => {
      document
        .querySelector(".part-order-editor")
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 30);
  }

  async function updatePartOrderStatus(id, stav) {
    if (!canEdit) return;

    const { error: statusError } = await supabase
      .from("workshop_part_orders")
      .update({
        stav,
        updated_by: user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    if (statusError) {
      setError(statusError.message);
      return;
    }

    setSuccess("Stav objednávky byl změněn.");
    await loadPartOrders();
  }

  async function deletePartOrder(id) {
    if (!canEdit) return;

    if (!window.confirm("Opravdu chceš objednávku dílu smazat?")) {
      return;
    }

    const { error: deleteError } = await supabase
      .from("workshop_part_orders")
      .delete()
      .eq("id", id);

    if (deleteError) {
      setError(deleteError.message);
      return;
    }

    if (editingPartOrderId === id) resetPartForm();
    setSuccess("Objednávka dílu byla smazána.");
    await loadPartOrders();
  }

  async function loadPosts() {
    setLoading(true);
    setError("");

    const { data, error: postsError } = await supabase
      .from("workshop_channel")
      .select(
        "id,nadpis,obsah,priorita,pripnuto,created_by,updated_by,created_at,updated_at"
      )
      .order("pripnuto", { ascending: false })
      .order("updated_at", { ascending: false });

    if (postsError) {
      setError(postsError.message);
      setPosts([]);
      setLoading(false);
      return;
    }

    const rows = data || [];
    setPosts(rows);

    const ids = [
      ...new Set(
        rows
          .flatMap((row) => [row.created_by, row.updated_by])
          .filter(Boolean)
      ),
    ];

    if (ids.length > 0) {
      const { data: people } = await supabase
        .from("profiles")
        .select("id,jmeno")
        .in("id", ids);

      const map = {};
      (people || []).forEach((person) => {
        map[String(person.id)] = person;
      });
      setProfiles(map);
    } else {
      setProfiles({});
    }

    setLoading(false);
  }

  useEffect(() => {
    loadPosts();
    loadPartOrders();
    loadWorkshopBranches();
    loadWorkshopVehicles();

    const channel = supabase
      .channel("workshop-channel-live")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_channel",
        },
        () => loadPosts()
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_part_orders",
        },
        () => loadPartOrders()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  function startEdit(post) {
    if (!canEdit) return;

    setEditingId(post.id);
    setForm({
      nadpis: post.nadpis || "",
      obsah: post.obsah || "",
      priorita: post.priorita || "BĚŽNÁ",
      pripnuto: Boolean(post.pripnuto),
    });
    setError("");
    setSuccess("");

    window.setTimeout(() => {
      document
        .querySelector(".workshop-editor")
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 30);
  }

  async function savePost(e) {
    e.preventDefault();

    if (!canEdit) return;

    const title = form.nadpis.trim();
    const body = form.obsah.trim();

    if (!title || !body) {
      setError("Vyplň nadpis i obsah zprávy.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      nadpis: title,
      obsah: body,
      priorita: form.priorita,
      pripnuto: Boolean(form.pripnuto),
      updated_by: user.id,
      updated_at: new Date().toISOString(),
    };

    let result;

    if (editingId) {
      result = await supabase
        .from("workshop_channel")
        .update(payload)
        .eq("id", editingId);
    } else {
      result = await supabase.from("workshop_channel").insert({
        ...payload,
        created_by: user.id,
      });
    }

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editingId
        ? "Zpráva v kanálu Dílna byla upravena."
        : "Nová zpráva byla přidána do kanálu Dílna."
    );

    resetForm();
    await loadPosts();
    setSaving(false);
  }

  async function deletePost(id) {
    if (!canEdit) return;

    if (!window.confirm("Opravdu chceš tuto zprávu z kanálu Dílna smazat?")) {
      return;
    }

    setError("");
    setSuccess("");

    const { error: deleteError } = await supabase
      .from("workshop_channel")
      .delete()
      .eq("id", id);

    if (deleteError) {
      setError(deleteError.message);
      return;
    }

    if (editingId === id) resetForm();

    setSuccess("Zpráva byla smazána.");
    await loadPosts();
  }

  function formatDate(value) {
    if (!value) return "-";

    return new Date(value).toLocaleString("cs-CZ", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  }

  return (
    <div className="standard-page workshop-page">
      <header className="standard-page-head">
        <div>
          <span className="page-eyebrow">INTERNÍ KANÁL</span>
          <h1>Dílna</h1>
          <p>
            Interní informace pro administrátory a dispečery. Obsah mohou
            přidávat a upravovat obě role.
          </p>
        </div>

        <div className={`access-pill ${canEdit ? "edit" : "read"}`}>
          {hasRole(role, ROLE_ADMIN)
            ? "✎ ADMIN · ÚPRAVY POVOLENY"
            : "✎ DISPEČER · ÚPRAVY POVOLENY"}
        </div>
      </header>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      {canEdit && (
        <form className="panel workshop-editor" onSubmit={savePost}>
          <div className="panel-section-head">
            <div>
              <span>{editingId ? "ÚPRAVA ZPRÁVY" : "NOVÁ ZPRÁVA"}</span>
              <h2>{editingId ? "Upravit příspěvek" : "Přidat informaci pro dílnu"}</h2>
            </div>

            {editingId && (
              <button
                type="button"
                className="secondary-button"
                onClick={resetForm}
              >
                Zrušit úpravu
              </button>
            )}
          </div>

          <div className="workshop-form-grid">
            <label className="workshop-title-field">
              <span>Nadpis</span>
              <input
                value={form.nadpis}
                onChange={(e) =>
                  setForm((old) => ({ ...old, nadpis: e.target.value }))
                }
                placeholder="Např. Vůz 3020 – plánovaná oprava"
                maxLength={160}
              />
            </label>

            <label>
              <span>Priorita</span>
              <select
                value={form.priorita}
                onChange={(e) =>
                  setForm((old) => ({ ...old, priorita: e.target.value }))
                }
              >
                <option value="BĚŽNÁ">Běžná</option>
                <option value="DŮLEŽITÁ">Důležitá</option>
                <option value="KRITICKÁ">Kritická</option>
              </select>
            </label>
          </div>

          <label className="workshop-body-field">
            <span>Obsah</span>
            <textarea
              value={form.obsah}
              onChange={(e) =>
                setForm((old) => ({ ...old, obsah: e.target.value }))
              }
              placeholder="Napiš informace pro administrátory a dispečery…"
              rows={7}
            />
          </label>

          <div className="workshop-editor-footer">
            <label className="workshop-pin-check">
              <input
                type="checkbox"
                checked={form.pripnuto}
                onChange={(e) =>
                  setForm((old) => ({
                    ...old,
                    pripnuto: e.target.checked,
                  }))
                }
              />
              <span>Připnout nahoře</span>
            </label>

            <button
              type="submit"
              className="primary-button"
              disabled={saving}
            >
              {saving
                ? "Ukládám…"
                : editingId
                ? "💾 Uložit změny"
                : "＋ Publikovat do Dílny"}
            </button>
          </div>
        </form>
      )}

      <section className="panel part-orders-panel">
        <div className="panel-section-head">
          <div>
            <span>OBJEDNÁVKY DÍLŮ</span>
            <h2>Díly a materiál</h2>
          </div>
          <span className="workshop-count">{partOrders.length}</span>
        </div>

        <form
          className="part-order-editor"
          onSubmit={savePartOrder}
        >
          <div className="part-order-grid">
            <label className="part-order-wide">
              <span>Název dílu *</span>
              <input
                value={partForm.nazev_dilu}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    nazev_dilu: e.target.value,
                  }))
                }
                placeholder="Např. brzdové destičky"
              />
            </label>

            <label>
              <span>Katalogové číslo</span>
              <input
                value={partForm.katalogove_cislo}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    katalogove_cislo: e.target.value,
                  }))
                }
                placeholder="OEM / SKU"
              />
            </label>

            <label>
              <span>Množství</span>
              <input
                type="number"
                min="1"
                step="1"
                value={partForm.mnozstvi}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    mnozstvi: e.target.value,
                  }))
                }
              />
            </label>

            <label>
              <span>Vůz</span>
              <input
                list="workshop-vehicle-options"
                value={partForm.vuz}
                onChange={(e) => {
                  const value = e.target.value;
                  const selectedVehicle = workshopVehicles.find(
                    (vehicle) =>
                      String(vehicle.cislo || "") === String(value || "")
                  );

                  setPartForm((old) => ({
                    ...old,
                    vuz: value,
                    provozovna_id:
                      selectedVehicle?.provozovna_id != null
                        ? String(selectedVehicle.provozovna_id)
                        : old.provozovna_id,
                  }));
                }}
                placeholder={
                  loadingWorkshopVehicles
                    ? "Načítám vozy..."
                    : "Napiš např. 332"
                }
                autoComplete="off"
              />
              <datalist id="workshop-vehicle-options">
                {workshopVehicles.map((vehicle) => (
                  <option
                    key={vehicle.id}
                    value={String(vehicle.cislo || "")}
                  >
                    {[
                      vehicle.vyrobce,
                      vehicle.typ,
                      vehicle.spz,
                    ]
                      .filter(Boolean)
                      .join(" · ")}
                  </option>
                ))}
              </datalist>
              <small className="vehicle-autocomplete-help">
                Začni psát číslo vozu — třeba 332 — a nabídnou se odpovídající vozy.
              </small>
            </label>

            <label>
              <span>Provozovna *</span>
              <select
                value={partForm.provozovna_id}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    provozovna_id: e.target.value,
                  }))
                }
              >
                <option value="">Vyber provozovnu</option>
                {workshopBranches.map((branch) => (
                  <option key={branch.id} value={String(branch.id)}>
                    {branch.kod} · {branch.nazev}
                  </option>
                ))}
              </select>
            </label>

            <label>
              <span>Dodavatel</span>
              <input
                value={partForm.dodavatel}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    dodavatel: e.target.value,
                  }))
                }
                placeholder="Název dodavatele"
              />
            </label>

            <label>
              <span>Cena / ks</span>
              <input
                inputMode="decimal"
                value={partForm.cena_ks}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    cena_ks: e.target.value,
                  }))
                }
                placeholder="Kč"
              />
            </label>

            <label>
              <span>Priorita</span>
              <select
                value={partForm.priorita}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    priorita: e.target.value,
                  }))
                }
              >
                <option value="BĚŽNÁ">Běžná</option>
                <option value="DŮLEŽITÁ">Důležitá</option>
                <option value="KRITICKÁ">Kritická</option>
              </select>
            </label>

            {editingPartOrderId && canEdit && (
              <label>
                <span>Stav</span>
                <select
                  value={partForm.stav}
                  onChange={(e) =>
                    setPartForm((old) => ({
                      ...old,
                      stav: e.target.value,
                    }))
                  }
                >
                  <option value="POŽADAVEK">Požadavek</option>
                  <option value="OBJEDNÁNO">Objednáno</option>
                  <option value="NA CESTĚ">Na cestě</option>
                  <option value="DORUČENO">Doručeno</option>
                  <option value="ZRUŠENO">Zrušeno</option>
                </select>
              </label>
            )}

            <label className="part-order-wide">
              <span>Odkaz na díl</span>
              <input
                value={partForm.odkaz}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    odkaz: e.target.value,
                  }))
                }
                placeholder="https://..."
              />
            </label>

            <label className="part-order-wide">
              <span>Poznámka</span>
              <textarea
                rows={3}
                value={partForm.poznamka}
                onChange={(e) =>
                  setPartForm((old) => ({
                    ...old,
                    poznamka: e.target.value,
                  }))
                }
                placeholder="Proč je díl potřeba, specifikace, termín..."
              />
            </label>
          </div>

          {partForm.vuz &&
            workshopVehicles.some(
              (vehicle) =>
                String(vehicle.cislo || "") ===
                String(partForm.vuz || "")
            ) && (
              <div className="selected-workshop-vehicle">
                {(() => {
                  const vehicle = workshopVehicles.find(
                    (item) =>
                      String(item.cislo || "") ===
                      String(partForm.vuz || "")
                  );

                  return (
                    <>
                      <span className="selected-workshop-vehicle-icon">🚌</span>
                      <div>
                        <strong>Vybraný vůz {vehicle?.cislo}</strong>
                        <small>
                          {[vehicle?.vyrobce, vehicle?.typ, vehicle?.spz]
                            .filter(Boolean)
                            .join(" · ")}
                        </small>
                      </div>
                    </>
                  );
                })()}
              </div>
            )}

          <div className="part-order-actions">
            {editingPartOrderId && (
              <button
                type="button"
                className="secondary-button"
                onClick={resetPartForm}
              >
                Zrušit úpravu
              </button>
            )}

            <button
              type="submit"
              className="primary-button"
              disabled={saving}
            >
              {saving
                ? "Ukládám…"
                : editingPartOrderId
                ? "💾 Uložit objednávku"
                : "🛒 Vytvořit požadavek na díl"}
            </button>
          </div>

        </form>

        <div className="part-orders-list">
          {partOrders.length === 0 ? (
            <div className="empty">Zatím není objednaný žádný díl.</div>
          ) : (
            partOrders.map((order) => {
              const total =
                order.cena_ks == null
                  ? null
                  : Number(order.cena_ks) * Number(order.mnozstvi || 1);

              return (
                <article key={order.id} className="part-order-card">
                  <div className="part-order-main">
                    <div className="part-order-top">
                      <div>
                        <span
                          className={`part-status status-${String(order.stav || "")
                            .normalize("NFD")
                            .replace(/[\\u0300-\\u036f]/g, "")
                            .replace(/\s+/g, "-")
                            .toLowerCase()}`}
                        >
                          {order.stav}
                        </span>
                        <span className="part-priority">
                          {order.priorita}
                        </span>
                      </div>
                      <time>{formatDate(order.updated_at || order.created_at)}</time>
                    </div>

                    <h3>{order.nazev_dilu}</h3>

                    <div className="part-order-meta">
                      <span><strong>Množství:</strong> {order.mnozstvi} ks</span>
                      {order.vuz && <span><strong>Vůz:</strong> {order.vuz}</span>}
                      {order.provozovna_id && (
                        <span>
                          <strong>Provozovna:</strong>{" "}
                          {workshopBranches.find(
                            (branch) =>
                              String(branch.id) ===
                              String(order.provozovna_id)
                          )?.kod || order.provozovna_id}
                        </span>
                      )}
                      {order.katalogove_cislo && (
                        <span><strong>Kat. č.:</strong> {order.katalogove_cislo}</span>
                      )}
                      {order.dodavatel && (
                        <span><strong>Dodavatel:</strong> {order.dodavatel}</span>
                      )}
                      {order.cena_ks != null && (
                        <span>
                          <strong>Cena:</strong>{" "}
                          {Number(order.cena_ks).toLocaleString("cs-CZ")} Kč/ks
                        </span>
                      )}
                      {total != null && (
                        <span>
                          <strong>Celkem:</strong>{" "}
                          {total.toLocaleString("cs-CZ")} Kč
                        </span>
                      )}
                    </div>

                    {order.poznamka && <p>{order.poznamka}</p>}

                    {order.odkaz && (
                      <a
                        className="part-order-link"
                        href={order.odkaz}
                        target="_blank"
                        rel="noreferrer"
                      >
                        🔗 Otevřít odkaz na díl
                      </a>
                    )}
                  </div>

                  {canEdit && (
                    <div className="part-order-admin">
                      <select
                        value={order.stav}
                        onChange={(e) =>
                          updatePartOrderStatus(order.id, e.target.value)
                        }
                      >
                        <option value="POŽADAVEK">Požadavek</option>
                        <option value="OBJEDNÁNO">Objednáno</option>
                        <option value="NA CESTĚ">Na cestě</option>
                        <option value="DORUČENO">Doručeno</option>
                        <option value="ZRUŠENO">Zrušeno</option>
                      </select>

                      <button
                        type="button"
                        className="secondary-button"
                        onClick={() => editPartOrder(order)}
                      >
                        ✏️ Upravit
                      </button>

                      <button
                        type="button"
                        className="delete-button"
                        onClick={() => deletePartOrder(order.id)}
                      >
                        Smazat
                      </button>
                    </div>
                  )}
                </article>
              );
            })
          )}
        </div>
      </section>

      <section className="panel workshop-feed">
        <div className="panel-section-head">
          <div>
            <span>PŘEHLED</span>
            <h2>Zprávy z dílny</h2>
          </div>
          <span className="workshop-count">{posts.length}</span>
        </div>

        {loading ? (
          <div className="empty">Načítám zprávy…</div>
        ) : posts.length === 0 ? (
          <div className="empty">
            V kanálu Dílna zatím není žádná zpráva.
          </div>
        ) : (
          <div className="workshop-posts">
            {posts.map((post) => {
              const author = profiles[String(post.created_by)];
              const editor = profiles[String(post.updated_by)];
              const changed =
                post.updated_at &&
                post.created_at &&
                new Date(post.updated_at).getTime() >
                  new Date(post.created_at).getTime() + 1000;

              return (
                <article
                  key={post.id}
                  className={`workshop-post ${
                    post.pripnuto ? "pinned" : ""
                  } priority-${String(post.priorita || "BĚŽNÁ")
                    .normalize("NFD")
                    .replace(/[\\u0300-\\u036f]/g, "")
                    .toLowerCase()}`}
                >
                  <div className="workshop-post-main">
                    <div className="workshop-post-topline">
                      <div className="workshop-post-badges">
                        {post.pripnuto && (
                          <span className="workshop-badge pinned">
                            📌 Připnuto
                          </span>
                        )}
                        <span
                          className={`workshop-badge priority ${String(
                            post.priorita || "BĚŽNÁ"
                          )
                            .normalize("NFD")
                            .replace(/[\\u0300-\\u036f]/g, "")
                            .toLowerCase()}`}
                        >
                          {post.priorita || "BĚŽNÁ"}
                        </span>
                      </div>

                      <time>{formatDate(post.updated_at || post.created_at)}</time>
                    </div>

                    <h3>{post.nadpis}</h3>
                    <p>{post.obsah}</p>

                    <footer>
                      <span>
                        Autor: <strong>{author?.jmeno || "Administrátor"}</strong>
                      </span>
                      {changed && (
                        <span>
                          Upravil: <strong>{editor?.jmeno || "Administrátor"}</strong>
                        </span>
                      )}
                    </footer>
                  </div>

                  {canEdit && (
                    <div className="workshop-post-actions">
                      <button
                        type="button"
                        className="secondary-button"
                        onClick={() => startEdit(post)}
                      >
                        ✏️ Upravit
                      </button>
                      <button
                        type="button"
                        className="delete-button"
                        onClick={() => deletePost(post.id)}
                      >
                        Smazat
                      </button>
                    </div>
                  )}
                </article>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
}


/* =========================================================
   ROZPOČET PROVOZOVEN
========================================================= */



function VehicleOrdersChannel({ user, role }) {
  const canEdit = canEditWorkshop(role);
  const [orders, setOrders] = useState([]);
  const [branches, setBranches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [form, setForm] = useState({
    provozovna_id: "",
    vyrobce: "",
    model: "",
    pocet: 1,
    cena_ks: "",
    dodavatel: "",
    termin_dodani: "",
    priorita: "BĚŽNÁ",
    stav: "POPTÁVKA",
    poznamka: "",
  });

  function resetForm() {
    setEditingId(null);
    setForm({
      provozovna_id: "",
      vyrobce: "",
      model: "",
      pocet: 1,
      cena_ks: "",
      dodavatel: "",
      termin_dodani: "",
      priorita: "BĚŽNÁ",
      stav: "POPTÁVKA",
      poznamka: "",
    });
  }

  async function loadData() {
    setLoading(true);
    setError("");

    const [
      { data: orderData, error: orderError },
      { data: branchData, error: branchError },
    ] = await Promise.all([
      supabase
        .from("workshop_vehicle_orders")
        .select(
          "id,provozovna_id,vyrobce,model,pocet,cena_ks,dodavatel,termin_dodani,priorita,stav,poznamka,created_by,updated_by,created_at,updated_at"
        )
        .order("created_at", { ascending: false }),
      supabase
        .from("provozovny")
        .select("id,kod,nazev")
        .order("kod", { ascending: true }),
    ]);

    if (orderError || branchError) {
      setError(
        orderError?.message ||
          branchError?.message ||
          "Nepodařilo se načíst objednávky vozů."
      );
      setLoading(false);
      return;
    }

    setOrders(orderData || []);
    setBranches(getMainProvozovny(branchData || []));
    setLoading(false);
  }

  useEffect(() => {
    loadData();

    const channel = supabase
      .channel("vehicle-orders-channel-live")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_vehicle_orders",
        },
        () => loadData()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  async function saveOrder(e) {
    e.preventDefault();

    if (!canEdit) return;

    if (!form.provozovna_id) {
      setError("Vyber provozovnu.");
      return;
    }

    if (!form.vyrobce.trim()) {
      setError("Vyplň výrobce vozu.");
      return;
    }

    if (!form.model.trim()) {
      setError("Vyplň typ / model vozu.");
      return;
    }

    const count = Math.max(1, Number(form.pocet) || 1);
    const price =
      String(form.cena_ks || "").trim() === ""
        ? null
        : Number(String(form.cena_ks).replace(",", "."));

    if (price !== null && (!Number.isFinite(price) || price < 0)) {
      setError("Cena za jeden vůz musí být platné nezáporné číslo.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      provozovna_id: Number(form.provozovna_id),
      vyrobce: form.vyrobce.trim(),
      model: form.model.trim(),
      pocet: count,
      cena_ks: price,
      dodavatel: form.dodavatel.trim() || null,
      termin_dodani: form.termin_dodani || null,
      priorita: form.priorita,
      stav: form.stav,
      poznamka: form.poznamka.trim() || null,
      updated_by: user.id,
      updated_at: new Date().toISOString(),
    };

    const result = editingId
      ? await supabase
          .from("workshop_vehicle_orders")
          .update(payload)
          .eq("id", editingId)
      : await supabase.from("workshop_vehicle_orders").insert({
          ...payload,
          stav: "POPTÁVKA",
          created_by: user.id,
        });

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editingId
        ? "Objednávka vozu byla upravena."
        : "Nová objednávka vozu byla vytvořena."
    );
    resetForm();
    await loadData();
    setSaving(false);
  }

  function startEdit(order) {
    if (!canEdit) return;

    setEditingId(order.id);
    setForm({
      provozovna_id: order.provozovna_id
        ? String(order.provozovna_id)
        : "",
      vyrobce: order.vyrobce || "",
      model: order.model || "",
      pocet: order.pocet || 1,
      cena_ks: order.cena_ks ?? "",
      dodavatel: order.dodavatel || "",
      termin_dodani: order.termin_dodani || "",
      priorita: order.priorita || "BĚŽNÁ",
      stav: order.stav || "POPTÁVKA",
      poznamka: order.poznamka || "",
    });

    window.setTimeout(() => {
      document
        .querySelector(".vehicle-orders-editor")
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 30);
  }

  async function updateStatus(id, stav) {
    if (!canEdit) return;

    const { error: statusError } = await supabase
      .from("workshop_vehicle_orders")
      .update({
        stav,
        updated_by: user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    if (statusError) {
      setError(statusError.message);
      return;
    }

    setSuccess("Stav objednávky vozu byl změněn.");
    await loadData();
  }

  async function deleteOrder(id) {
    if (!canEdit) return;

    if (!window.confirm("Opravdu chceš objednávku vozu smazat?")) {
      return;
    }

    const { error: deleteError } = await supabase
      .from("workshop_vehicle_orders")
      .delete()
      .eq("id", id);

    if (deleteError) {
      setError(deleteError.message);
      return;
    }

    if (editingId === id) resetForm();
    setSuccess("Objednávka vozu byla smazána.");
    await loadData();
  }

  function branchCode(id) {
    return (
      branches.find(
        (branch) => String(branch.id) === String(id)
      )?.kod || "-"
    );
  }

  function formatMoney(value) {
    if (value == null || value === "") return "—";

    return `${Number(value).toLocaleString("cs-CZ", {
      maximumFractionDigits: 2,
    })} Kč`;
  }

  function formatDate(value) {
    if (!value) return "—";

    return new Date(value).toLocaleDateString("cs-CZ", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    });
  }

  const activeOrders = orders.filter(
    (order) => !["DODÁNO", "ZRUŠENO"].includes(order.stav)
  );

  const totalVehicles = orders.reduce(
    (sum, order) => sum + Number(order.pocet || 0),
    0
  );

  const orderedValue = orders
    .filter((order) =>
      ["OBJEDNÁNO", "VE VÝROBĚ", "NA CESTĚ", "DODÁNO"].includes(order.stav)
    )
    .reduce(
      (sum, order) =>
        sum +
        Number(order.cena_ks || 0) *
          Number(order.pocet || 0),
      0
    );

  return (
    <div className="standard-page vehicle-orders-page">
      <header className="standard-page-head">
        <div>
          <span className="page-eyebrow">NÁKUP VOZIDEL</span>
          <h1>Objednávky vozů</h1>
          <p>
            Samostatný kanál pro evidenci nových objednávek vozidel.
            Přístup mají pouze administrátoři a dispečeři.
          </p>
        </div>

        <div className="access-pill edit">
          ADMIN + DISPEČER
        </div>
      </header>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      <div className="budget-summary-grid">
        <div className="budget-summary-card">
          <span>Objednávky</span>
          <strong>{orders.length}</strong>
        </div>

        <div className="budget-summary-card">
          <span>Aktivní objednávky</span>
          <strong>{activeOrders.length}</strong>
        </div>

        <div className="budget-summary-card">
          <span>Celkem vozů</span>
          <strong>{totalVehicles}</strong>
        </div>

        <div className="budget-summary-card">
          <span>Objednáno za</span>
          <strong>{formatMoney(orderedValue)}</strong>
        </div>
      </div>

      <form
        className="panel vehicle-orders-editor"
        onSubmit={saveOrder}
      >
        <div className="panel-section-head">
          <div>
            <span>
              {editingId ? "ÚPRAVA OBJEDNÁVKY" : "NOVÁ OBJEDNÁVKA"}
            </span>
            <h2>
              {editingId ? "Upravit objednávku vozu" : "Objednat nový vůz"}
            </h2>
          </div>

          {editingId && (
            <button
              type="button"
              className="secondary-button"
              onClick={resetForm}
            >
              Zrušit úpravu
            </button>
          )}
        </div>

        <div className="vehicle-order-grid">
          <label>
            <span>Provozovna *</span>
            <select
              value={form.provozovna_id}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  provozovna_id: e.target.value,
                }))
              }
            >
              <option value="">Vyber provozovnu</option>
              {branches.map((branch) => (
                <option key={branch.id} value={String(branch.id)}>
                  {branch.kod} · {branch.nazev}
                </option>
              ))}
            </select>
          </label>

          <label>
            <span>Výrobce *</span>
            <input
              value={form.vyrobce}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  vyrobce: e.target.value,
                }))
              }
              placeholder="Např. SOR, Iveco, Mercedes-Benz"
            />
          </label>

          <label>
            <span>Typ / model *</span>
            <input
              value={form.model}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  model: e.target.value,
                }))
              }
              placeholder="Např. NS 12, Crossway LE"
            />
          </label>

          <label>
            <span>Počet vozů</span>
            <input
              type="number"
              min="1"
              step="1"
              value={form.pocet}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  pocet: e.target.value,
                }))
              }
            />
          </label>

          <label>
            <span>Cena za vůz</span>
            <input
              inputMode="decimal"
              value={form.cena_ks}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  cena_ks: e.target.value,
                }))
              }
              placeholder="Kč"
            />
          </label>

          <label>
            <span>Dodavatel</span>
            <input
              value={form.dodavatel}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  dodavatel: e.target.value,
                }))
              }
              placeholder="Název dodavatele / výrobce"
            />
          </label>

          <label>
            <span>Termín dodání</span>
            <div className="vehicle-order-date-wrap">
              <input
                type="date"
                value={form.termin_dodani}
                onChange={(e) =>
                  setForm((old) => ({
                    ...old,
                    termin_dodani: e.target.value,
                  }))
                }
              />
            </div>
          </label>

          <label>
            <span>Priorita</span>
            <select
              value={form.priorita}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  priorita: e.target.value,
                }))
              }
            >
              <option value="BĚŽNÁ">Běžná</option>
              <option value="DŮLEŽITÁ">Důležitá</option>
              <option value="KRITICKÁ">Kritická</option>
            </select>
          </label>

          {editingId && (
            <label>
              <span>Stav</span>
              <select
                value={form.stav}
                onChange={(e) =>
                  setForm((old) => ({
                    ...old,
                    stav: e.target.value,
                  }))
                }
              >
                <option value="POPTÁVKA">Poptávka</option>
                <option value="SCHVÁLENO">Schváleno</option>
                <option value="OBJEDNÁNO">Objednáno</option>
                <option value="VE VÝROBĚ">Ve výrobě</option>
                <option value="NA CESTĚ">Na cestě</option>
                <option value="DODÁNO">Dodáno</option>
                <option value="ZRUŠENO">Zrušeno</option>
              </select>
            </label>
          )}

          <label className="vehicle-order-wide">
            <span>Poznámka</span>
            <textarea
              rows={4}
              value={form.poznamka}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  poznamka: e.target.value,
                }))
              }
              placeholder="Výbava, pohon, délka vozu, počet dveří, specifikace..."
            />
          </label>
        </div>

        <div className="part-order-actions">
          <button
            type="submit"
            className="primary-button"
            disabled={saving}
          >
            {saving
              ? "Ukládám…"
              : editingId
              ? "💾 Uložit změny"
              : "🚌 Vytvořit objednávku vozu"}
          </button>
        </div>
      </form>

      <section className="panel vehicle-orders-list-panel">
        <div className="panel-section-head">
          <div>
            <span>PŘEHLED</span>
            <h2>Objednané vozy</h2>
          </div>
          <span className="workshop-count">{orders.length}</span>
        </div>

        {loading ? (
          <div className="empty">Načítám objednávky vozů…</div>
        ) : orders.length === 0 ? (
          <div className="empty">
            Zatím není vytvořena žádná objednávka vozu.
          </div>
        ) : (
          <div className="vehicle-orders-list">
            {orders.map((order) => {
              const total =
                order.cena_ks == null
                  ? null
                  : Number(order.cena_ks) *
                    Number(order.pocet || 1);

              return (
                <article key={order.id} className="vehicle-order-card">
                  <div className="vehicle-order-card-main">
                    <div className="vehicle-order-card-top">
                      <div className="vehicle-order-badges">
                        <span className="branch-budget-code">
                          {branchCode(order.provozovna_id)}
                        </span>

                        <span
                          className={`vehicle-order-status status-${String(
                            order.stav || ""
                          )
                            .normalize("NFD")
                            .replace(/[\u0300-\u036f]/g, "")
                            .replace(/\s+/g, "-")
                            .toLowerCase()}`}
                        >
                          {order.stav}
                        </span>

                        <span className="part-priority">
                          {order.priorita}
                        </span>
                      </div>

                      {order.termin_dodani && (
                        <span className="vehicle-order-delivery">
                          Dodání: {formatDate(order.termin_dodani)}
                        </span>
                      )}
                    </div>

                    <h3>
                      {order.vyrobce} {order.model}
                    </h3>

                    <div className="vehicle-order-meta">
                      <span>
                        <strong>Počet:</strong> {order.pocet} ks
                      </span>

                      {order.dodavatel && (
                        <span>
                          <strong>Dodavatel:</strong> {order.dodavatel}
                        </span>
                      )}

                      {order.cena_ks != null && (
                        <span>
                          <strong>Cena / vůz:</strong>{" "}
                          {formatMoney(order.cena_ks)}
                        </span>
                      )}

                      {total != null && (
                        <span>
                          <strong>Celkem:</strong>{" "}
                          {formatMoney(total)}
                        </span>
                      )}
                    </div>

                    {order.poznamka && (
                      <p>{order.poznamka}</p>
                    )}
                  </div>

                  <div className="vehicle-order-card-actions">
                    <select
                      value={order.stav}
                      onChange={(e) =>
                        updateStatus(order.id, e.target.value)
                      }
                    >
                      <option value="POPTÁVKA">Poptávka</option>
                      <option value="SCHVÁLENO">Schváleno</option>
                      <option value="OBJEDNÁNO">Objednáno</option>
                      <option value="VE VÝROBĚ">Ve výrobě</option>
                      <option value="NA CESTĚ">Na cestě</option>
                      <option value="DODÁNO">Dodáno</option>
                      <option value="ZRUŠENO">Zrušeno</option>
                    </select>

                    <button
                      type="button"
                      className="secondary-button"
                      onClick={() => startEdit(order)}
                    >
                      ✏️ Upravit
                    </button>

                    <button
                      type="button"
                      className="delete-button"
                      onClick={() => deleteOrder(order.id)}
                    >
                      Smazat
                    </button>
                  </div>
                </article>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
}

function PartOrdersChannel({ user, role }) {
  const canEdit = canEditWorkshop(role);
  const [orders, setOrders] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [branches, setBranches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [form, setForm] = useState({
    nazev_dilu: "",
    katalogove_cislo: "",
    mnozstvi: 1,
    vuz: "",
    provozovna_id: "",
    dodavatel: "",
    odkaz: "",
    cena_ks: "",
    poznamka: "",
    priorita: "BĚŽNÁ",
    stav: "POŽADAVEK",
  });

  function resetForm() {
    setEditingId(null);
    setForm({
      nazev_dilu: "",
      katalogove_cislo: "",
      mnozstvi: 1,
      vuz: "",
      provozovna_id: "",
      dodavatel: "",
      odkaz: "",
      cena_ks: "",
      poznamka: "",
      priorita: "BĚŽNÁ",
      stav: "POŽADAVEK",
    });
  }

  async function loadData() {
    setLoading(true);
    setError("");

    const [
      { data: orderData, error: orderError },
      { data: vehicleData, error: vehicleError },
      { data: branchData, error: branchError },
    ] = await Promise.all([
      supabase
        .from("workshop_part_orders")
        .select(
          "id,nazev_dilu,katalogove_cislo,mnozstvi,vuz,provozovna_id,dodavatel,odkaz,cena_ks,poznamka,priorita,stav,created_by,updated_by,created_at,updated_at"
        )
        .order("created_at", { ascending: false }),
      supabase
        .from("vozy")
        .select("id,cislo,vyrobce,typ,spz,provozovna_id")
        .order("cislo", { ascending: true }),
      supabase
        .from("provozovny")
        .select("id,kod,nazev")
        .order("kod", { ascending: true }),
    ]);

    if (orderError || vehicleError || branchError) {
      setError(
        orderError?.message ||
          vehicleError?.message ||
          branchError?.message ||
          "Nepodařilo se načíst objednávky dílů."
      );
      setLoading(false);
      return;
    }

    setOrders(orderData || []);
    setVehicles(
      (vehicleData || []).sort((a, b) =>
        String(a.cislo || "").localeCompare(
          String(b.cislo || ""),
          "cs",
          { numeric: true, sensitivity: "base" }
        )
      )
    );
    setBranches(getMainProvozovny(branchData || []));
    setLoading(false);
  }

  useEffect(() => {
    loadData();

    const channel = supabase
      .channel("part-orders-channel-live")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_part_orders",
        },
        () => loadData()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  async function saveOrder(e) {
    e.preventDefault();

    if (!canEdit) return;

    if (!form.nazev_dilu.trim()) {
      setError("Vyplň název dílu.");
      return;
    }

    if (!form.provozovna_id) {
      setError("Vyber provozovnu.");
      return;
    }

    const quantity = Math.max(1, Number(form.mnozstvi) || 1);
    const price =
      String(form.cena_ks || "").trim() === ""
        ? null
        : Number(String(form.cena_ks).replace(",", "."));

    if (price !== null && (!Number.isFinite(price) || price < 0)) {
      setError("Cena za kus musí být platné nezáporné číslo.");
      return;
    }

    setSaving(true);
    setError("");
    setSuccess("");

    const payload = {
      nazev_dilu: form.nazev_dilu.trim(),
      katalogove_cislo: form.katalogove_cislo.trim() || null,
      mnozstvi: quantity,
      vuz: form.vuz.trim() || null,
      provozovna_id: Number(form.provozovna_id),
      dodavatel: form.dodavatel.trim() || null,
      odkaz: form.odkaz.trim() || null,
      cena_ks: price,
      poznamka: form.poznamka.trim() || null,
      priorita: form.priorita,
      stav: form.stav,
      updated_by: user.id,
      updated_at: new Date().toISOString(),
    };

    const result = editingId
      ? await supabase
          .from("workshop_part_orders")
          .update(payload)
          .eq("id", editingId)
      : await supabase.from("workshop_part_orders").insert({
          ...payload,
          created_by: user.id,
          stav: "POŽADAVEK",
        });

    if (result.error) {
      setError(result.error.message);
      setSaving(false);
      return;
    }

    setSuccess(
      editingId
        ? "Objednávka byla upravena."
        : "Požadavek na díl byl vytvořen."
    );
    resetForm();
    await loadData();
    setSaving(false);
  }

  function startEdit(order) {
    setEditingId(order.id);
    setForm({
      nazev_dilu: order.nazev_dilu || "",
      katalogove_cislo: order.katalogove_cislo || "",
      mnozstvi: order.mnozstvi || 1,
      vuz: order.vuz || "",
      provozovna_id: order.provozovna_id
        ? String(order.provozovna_id)
        : "",
      dodavatel: order.dodavatel || "",
      odkaz: order.odkaz || "",
      cena_ks: order.cena_ks ?? "",
      poznamka: order.poznamka || "",
      priorita: order.priorita || "BĚŽNÁ",
      stav: order.stav || "POŽADAVEK",
    });

    window.setTimeout(() => {
      document
        .querySelector(".part-orders-channel-editor")
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 30);
  }

  async function updateStatus(id, stav) {
    if (!canEdit) return;

    const { error: statusError } = await supabase
      .from("workshop_part_orders")
      .update({
        stav,
        updated_by: user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    if (statusError) {
      setError(statusError.message);
      return;
    }

    setSuccess("Stav objednávky byl změněn.");
    await loadData();
  }

  async function deleteOrder(id) {
    if (!canEdit) return;
    if (!window.confirm("Opravdu chceš objednávku smazat?")) return;

    const { error: deleteError } = await supabase
      .from("workshop_part_orders")
      .delete()
      .eq("id", id);

    if (deleteError) {
      setError(deleteError.message);
      return;
    }

    if (editingId === id) resetForm();
    setSuccess("Objednávka byla smazána.");
    await loadData();
  }

  function branchCode(id) {
    return (
      branches.find(
        (branch) => String(branch.id) === String(id)
      )?.kod || "-"
    );
  }

  function formatMoney(value) {
    if (value == null || value === "") return "—";
    return `${Number(value).toLocaleString("cs-CZ", {
      maximumFractionDigits: 2,
    })} Kč`;
  }

  const activeOrders = orders.filter(
    (order) => !["DORUČENO", "ZRUŠENO"].includes(order.stav)
  ).length;

  const orderedValue = orders
    .filter((order) =>
      ["OBJEDNÁNO", "NA CESTĚ", "DORUČENO"].includes(order.stav)
    )
    .reduce(
      (sum, order) =>
        sum +
        Number(order.cena_ks || 0) *
          Number(order.mnozstvi || 0),
      0
    );

  return (
    <div className="standard-page part-orders-channel">
      <header className="standard-page-head">
        <div>
          <span className="page-eyebrow">DÍLNA · NÁKUP</span>
          <h1>Objednávky dílů</h1>
          <p>
            Samostatný kanál pro objednávání dílů a materiálu.
            Objednané položky se automaticky propisují do rozpočtu
            zvolené provozovny.
          </p>
        </div>
        <div className="access-pill edit">
          ADMIN + DISPEČER
        </div>
      </header>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      <div className="budget-summary-grid">
        <div className="budget-summary-card">
          <span>Celkem objednávek</span>
          <strong>{orders.length}</strong>
        </div>
        <div className="budget-summary-card">
          <span>Aktivní</span>
          <strong>{activeOrders}</strong>
        </div>
        <div className="budget-summary-card">
          <span>Objednáno celkem</span>
          <strong>{formatMoney(orderedValue)}</strong>
        </div>
      </div>

      <form
        className="panel part-orders-channel-editor"
        onSubmit={saveOrder}
      >
        <div className="panel-section-head">
          <div>
            <span>{editingId ? "ÚPRAVA OBJEDNÁVKY" : "NOVÝ POŽADAVEK"}</span>
            <h2>
              {editingId ? "Upravit objednávku" : "Objednat díl"}
            </h2>
          </div>
          {editingId && (
            <button
              type="button"
              className="secondary-button"
              onClick={resetForm}
            >
              Zrušit úpravu
            </button>
          )}
        </div>

        <div className="part-order-grid">
          <label className="part-order-wide">
            <span>Název dílu *</span>
            <input
              value={form.nazev_dilu}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  nazev_dilu: e.target.value,
                }))
              }
              placeholder="Např. brzdové destičky"
            />
          </label>

          <label>
            <span>Katalogové číslo</span>
            <input
              value={form.katalogove_cislo}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  katalogove_cislo: e.target.value,
                }))
              }
              placeholder="OEM / SKU"
            />
          </label>

          <label>
            <span>Množství</span>
            <input
              type="number"
              min="1"
              step="1"
              value={form.mnozstvi}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  mnozstvi: e.target.value,
                }))
              }
            />
          </label>

          <label>
            <span>Vůz</span>
            <input
              list="part-orders-channel-vehicles"
              value={form.vuz}
              onChange={(e) => {
                const value = e.target.value;
                const selectedVehicle = vehicles.find(
                  (vehicle) =>
                    String(vehicle.cislo || "") === String(value || "")
                );

                setForm((old) => ({
                  ...old,
                  vuz: value,
                  provozovna_id:
                    selectedVehicle?.provozovna_id != null
                      ? String(selectedVehicle.provozovna_id)
                      : old.provozovna_id,
                }));
              }}
              placeholder="Napiš např. 332"
              autoComplete="off"
            />
            <datalist id="part-orders-channel-vehicles">
              {vehicles.map((vehicle) => (
                <option
                  key={vehicle.id}
                  value={String(vehicle.cislo || "")}
                >
                  {[vehicle.vyrobce, vehicle.typ, vehicle.spz]
                    .filter(Boolean)
                    .join(" · ")}
                </option>
              ))}
            </datalist>
          </label>

          <label>
            <span>Provozovna *</span>
            <select
              value={form.provozovna_id}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  provozovna_id: e.target.value,
                }))
              }
            >
              <option value="">Vyber provozovnu</option>
              {branches.map((branch) => (
                <option key={branch.id} value={String(branch.id)}>
                  {branch.kod} · {branch.nazev}
                </option>
              ))}
            </select>
          </label>

          <label>
            <span>Dodavatel</span>
            <input
              value={form.dodavatel}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  dodavatel: e.target.value,
                }))
              }
              placeholder="Název dodavatele"
            />
          </label>

          <label>
            <span>Cena / ks</span>
            <input
              inputMode="decimal"
              value={form.cena_ks}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  cena_ks: e.target.value,
                }))
              }
              placeholder="Kč"
            />
          </label>

          <label>
            <span>Priorita</span>
            <select
              value={form.priorita}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  priorita: e.target.value,
                }))
              }
            >
              <option value="BĚŽNÁ">Běžná</option>
              <option value="DŮLEŽITÁ">Důležitá</option>
              <option value="KRITICKÁ">Kritická</option>
            </select>
          </label>

          {editingId && (
            <label>
              <span>Stav</span>
              <select
                value={form.stav}
                onChange={(e) =>
                  setForm((old) => ({
                    ...old,
                    stav: e.target.value,
                  }))
                }
              >
                <option value="POŽADAVEK">Požadavek</option>
                <option value="OBJEDNÁNO">Objednáno</option>
                <option value="NA CESTĚ">Na cestě</option>
                <option value="DORUČENO">Doručeno</option>
                <option value="ZRUŠENO">Zrušeno</option>
              </select>
            </label>
          )}

          <label className="part-order-wide">
            <span>Odkaz</span>
            <input
              value={form.odkaz}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  odkaz: e.target.value,
                }))
              }
              placeholder="https://..."
            />
          </label>

          <label className="part-order-wide">
            <span>Poznámka</span>
            <textarea
              rows={3}
              value={form.poznamka}
              onChange={(e) =>
                setForm((old) => ({
                  ...old,
                  poznamka: e.target.value,
                }))
              }
              placeholder="Specifikace, důvod objednávky, termín..."
            />
          </label>
        </div>

        <div className="part-order-actions">
          <button
            type="submit"
            className="primary-button"
            disabled={saving}
          >
            {saving
              ? "Ukládám…"
              : editingId
              ? "💾 Uložit změny"
              : "🛒 Vytvořit objednávku"}
          </button>
        </div>
      </form>

      <section className="panel part-orders-channel-list">
        <div className="panel-section-head">
          <div>
            <span>PŘEHLED</span>
            <h2>Objednávky</h2>
          </div>
          <span className="workshop-count">{orders.length}</span>
        </div>

        {loading ? (
          <div className="empty">Načítám objednávky…</div>
        ) : orders.length === 0 ? (
          <div className="empty">Zatím není žádná objednávka.</div>
        ) : (
          <div className="part-orders-list">
            {orders.map((order) => {
              const total =
                order.cena_ks == null
                  ? null
                  : Number(order.cena_ks) *
                    Number(order.mnozstvi || 1);

              return (
                <article key={order.id} className="part-order-card">
                  <div className="part-order-main">
                    <div className="part-order-top">
                      <div>
                        <span
                          className={`part-status status-${String(order.stav || "")
                            .normalize("NFD")
                            .replace(/[\u0300-\u036f]/g, "")
                            .replace(/\s+/g, "-")
                            .toLowerCase()}`}
                        >
                          {order.stav}
                        </span>
                        <span className="part-priority">
                          {order.priorita}
                        </span>
                      </div>
                      <span className="branch-budget-code">
                        {branchCode(order.provozovna_id)}
                      </span>
                    </div>

                    <h3>{order.nazev_dilu}</h3>

                    <div className="part-order-meta">
                      <span>
                        <strong>Množství:</strong> {order.mnozstvi} ks
                      </span>
                      {order.vuz && (
                        <span>
                          <strong>Vůz:</strong> {order.vuz}
                        </span>
                      )}
                      {order.katalogove_cislo && (
                        <span>
                          <strong>Kat. č.:</strong> {order.katalogove_cislo}
                        </span>
                      )}
                      {order.dodavatel && (
                        <span>
                          <strong>Dodavatel:</strong> {order.dodavatel}
                        </span>
                      )}
                      {order.cena_ks != null && (
                        <span>
                          <strong>Cena:</strong> {formatMoney(order.cena_ks)}/ks
                        </span>
                      )}
                      {total != null && (
                        <span>
                          <strong>Celkem:</strong> {formatMoney(total)}
                        </span>
                      )}
                    </div>

                    {order.poznamka && <p>{order.poznamka}</p>}

                    {order.odkaz && (
                      <a
                        className="part-order-link"
                        href={order.odkaz}
                        target="_blank"
                        rel="noreferrer"
                      >
                        🔗 Otevřít odkaz
                      </a>
                    )}
                  </div>

                  <div className="part-order-admin">
                    <select
                      value={order.stav}
                      onChange={(e) =>
                        updateStatus(order.id, e.target.value)
                      }
                    >
                      <option value="POŽADAVEK">Požadavek</option>
                      <option value="OBJEDNÁNO">Objednáno</option>
                      <option value="NA CESTĚ">Na cestě</option>
                      <option value="DORUČENO">Doručeno</option>
                      <option value="ZRUŠENO">Zrušeno</option>
                    </select>

                    <button
                      type="button"
                      className="secondary-button"
                      onClick={() => startEdit(order)}
                    >
                      ✏️ Upravit
                    </button>

                    <button
                      type="button"
                      className="delete-button"
                      onClick={() => deleteOrder(order.id)}
                    >
                      Smazat
                    </button>
                  </div>
                </article>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
}

function getDkvFinancialEntries(orders, jobs) {
  return [
    ...orders.filter((order) => order.stav !== "Zrušená").map((order) => ({
      id: `objednavka-${order.id}`, date: order.datum, title: order.cislo_objednavky,
      description: order.popis, kind: "Objednávka", status: order.stav,
      amount: -Number(order.castka_kc || 0),
    })),
    ...jobs.filter((job) => ["Splněná", "Uhrazeno"].includes(job.stav)).map((job) => ({
      id: `zakazka-${job.id}`, date: job.datum, title: job.cislo_zakazky,
      description: job.popis, kind: "Zakázka", status: job.stav,
      amount: Number(job.prijem_kc || 0),
    })),
  ];
}

function getDkvBudgetTotals(initialAmount, orders, jobs) {
  const money = (value) => Math.round(Number(value || 0) * 100);
  const entries = getDkvFinancialEntries(orders, jobs);
  const expenses = entries.filter((entry) => entry.kind === "Objednávka")
    .reduce((sum, entry) => sum + money(-entry.amount), 0);
  const income = entries.filter((entry) => entry.kind === "Zakázka")
    .reduce((sum, entry) => sum + money(entry.amount), 0);
  return {
    expenses: expenses / 100,
    income: income / 100,
    remaining: (money(initialAmount) - expenses + income) / 100,
  };
}

function DkvBudget({ role }) {
  const canEdit = canEditBudget(role);
  const [budget, setBudget] = useState(0);
  const [draft, setDraft] = useState("0");
  const [orders, setOrders] = useState([]);
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function loadDkvBudget() {
    setLoading(true);
    const [budgetResult, orderResult, jobResult] = await Promise.all([
      supabase.from("dkv_lichkov_rozpocet").select("castka").eq("id", 1).maybeSingle(),
      supabase.from("dkv_lichkov_objednavky")
        .select("id,cislo_objednavky,datum,castka_kc,stav").order("datum", { ascending: false }),
      supabase.from("dkv_lichkov_prijmy")
        .select("id,cislo_zakazky,datum,prijem_kc,stav").order("datum", { ascending: false }),
    ]);
    const loadError = budgetResult.error || orderResult.error || jobResult.error;
    if (loadError) {
      setLoadFailed(true);
      setError(getDkvSaveError(loadError));
    } else {
      setLoadFailed(false);
      const amount = Number(budgetResult.data?.castka || 0);
      setBudget(amount);
      setDraft(String(amount));
      setOrders(orderResult.data || []);
      setJobs(jobResult.data || []);
      setError("");
    }
    setLoading(false);
  }

  useEffect(() => {
    loadDkvBudget();
    const channel = supabase.channel("dkv-budget-live");
    for (const table of ["dkv_lichkov_rozpocet", "dkv_lichkov_objednavky", "dkv_lichkov_prijmy"]) {
      channel.on("postgres_changes", { event: "*", schema: "public", table }, loadDkvBudget);
    }
    channel.subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  async function saveBudget() {
    if (!canEdit || saving) return;
    const raw = draft.trim().replace(",", ".");
    const amount = raw === "" ? 0 : Number(raw);
    if (raw !== "" && (!/^\d+(?:\.\d{1,2})?$/.test(raw) || amount > 9999999999.99)) {
      setError("Rozpočet musí být nezáporné číslo nejvýše na dvě desetinná místa.");
      return;
    }
    setSaving(true);
    setError("");
    setSuccess("");
    try {
      const { error: saveError } = await supabase.from("dkv_lichkov_rozpocet")
        .upsert({ id: 1, castka: amount, updated_at: new Date().toISOString() }, { onConflict: "id" });
      if (saveError) throw saveError;
      await loadDkvBudget();
      setSuccess("Rozpočet DKV Lichkov byl uložen.");
    } catch (saveError) {
      setError(getDkvSaveError(saveError));
    } finally {
      setSaving(false);
    }
  }

  const formatMoney = (value) => `${Number(value).toLocaleString("cs-CZ", {
    minimumFractionDigits: 0, maximumFractionDigits: 2,
  })} Kč`;
  const { expenses, income, remaining } = getDkvBudgetTotals(budget, orders, jobs);
  const activeOrders = orders.filter((order) => order.stav !== "Zrušená");
  const completedJobs = jobs.filter((job) => ["Splněná", "Uhrazeno"].includes(job.stav));

  return (
    <div className="standard-page budget-page">
      <header className="standard-page-head">
        <div>
          <span className="page-eyebrow">FINANCE DKV LICHKOV</span>
          <h1>Rozpočet DKV Lichkov</h1>
          <p>Objednávky se odečítají z rozpočtu. Příjem ze zakázky se přičte po označení zakázky jako Splněná. Již uhrazené zakázky se počítají také.</p>
        </div>
        <div className={`access-pill ${canEdit ? "edit" : "read"}`}>
          {canEdit ? "ADMIN · NASTAVENÍ ROZPOČTU" : "PŘEHLED ROZPOČTU"}
        </div>
      </header>

      {error && <div className="error-box" role="alert">{error}</div>}
      {success && <div className="success-box" role="status">{success}</div>}

      {loading ? <div className="panel empty">Načítám rozpočet DKV…</div> : loadFailed ? null : <>
        <div className="budget-summary-grid dkv-budget-summary">
          <div className="budget-summary-card"><span>Základní rozpočet</span><strong>{formatMoney(budget)}</strong></div>
          <div className="budget-summary-card"><span>Objednávky</span><strong>− {formatMoney(expenses)}</strong></div>
          <div className="budget-summary-card"><span>Splněné zakázky</span><strong>+ {formatMoney(income)}</strong></div>
          <div className="budget-summary-card"><span>Zbývá</span><strong className={remaining < 0 ? "negative" : ""}>{formatMoney(remaining)}</strong></div>
        </div>

        <section className="panel branch-budget-card">
          {canEdit && <div className="budget-edit-row">
            <label><span>Základní rozpočet DKV (Kč)</span><input inputMode="decimal" value={draft} onChange={(e) => setDraft(e.target.value)} /></label>
            <button type="button" className="primary-button" disabled={saving} onClick={saveBudget}>{saving ? "Ukládám…" : "Uložit rozpočet"}</button>
          </div>}

          <div className="budget-order-list">
            <div className="budget-order-list-head"><strong>Objednávky DKV</strong><span>{activeOrders.length}</span></div>
            {activeOrders.length === 0 ? <small>Žádné započítané objednávky.</small> : activeOrders.slice(0, 8).map((order) => <div key={order.id} className="budget-order-row">
              <div><strong>{order.cislo_objednavky}</strong><small>{order.stav} · {order.datum}</small></div>
              <strong>− {formatMoney(order.castka_kc || 0)}</strong>
            </div>)}
          </div>
          <div className="budget-order-list">
            <div className="budget-order-list-head"><strong>Splněné zakázky DKV</strong><span>{completedJobs.length}</span></div>
            {completedJobs.length === 0 ? <small>Žádné splněné zakázky.</small> : completedJobs.slice(0, 8).map((job) => <div key={job.id} className="budget-order-row">
              <div><strong>{job.cislo_zakazky}</strong><small>{job.stav} · {job.datum}</small></div>
              <strong>+ {formatMoney(job.prijem_kc)}</strong>
            </div>)}
          </div>
        </section>
      </>}
    </div>
  );
}

function BranchBudget({ role }) {
  const canEdit = canEditBudget(role);
  const [branches, setBranches] = useState([]);
  const [budgets, setBudgets] = useState([]);
  const [orders, setOrders] = useState([]);
  const [vehicleOrders, setVehicleOrders] = useState([]);
  const [budgetDrafts, setBudgetDrafts] = useState({});
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function loadBudgetData() {
    setLoading(true);
    setError("");

    const [
      { data: branchData, error: branchError },
      { data: budgetData, error: budgetError },
      { data: orderData, error: orderError },
      { data: vehicleOrderData, error: vehicleOrderError },
    ] = await Promise.all([
      supabase
        .from("provozovny")
        .select("id,kod,nazev")
        .order("kod", { ascending: true }),
      supabase
        .from("workshop_budgets")
        .select("id,provozovna_id,castka,updated_at"),
      supabase
        .from("workshop_part_orders")
        .select(
          "id,provozovna_id,nazev_dilu,mnozstvi,cena_ks,stav,created_at"
        )
        .in("stav", ["OBJEDNÁNO", "NA CESTĚ", "DORUČENO"]),
      supabase
        .from("workshop_vehicle_orders")
        .select(
          "id,provozovna_id,vyrobce,model,pocet,cena_ks,stav,created_at"
        )
        .in("stav", ["OBJEDNÁNO", "VE VÝROBĚ", "NA CESTĚ", "DODÁNO"]),
    ]);

    if (
      branchError ||
      budgetError ||
      orderError ||
      vehicleOrderError
    ) {
      setError(
        branchError?.message ||
          budgetError?.message ||
          orderError?.message ||
          vehicleOrderError?.message ||
          "Nepodařilo se načíst rozpočet."
      );
      setLoading(false);
      return;
    }

    const filteredBranches = getMainProvozovny(branchData || []);

    setBranches(filteredBranches);
    setBudgets(budgetData || []);
    setOrders(orderData || []);
    setVehicleOrders(vehicleOrderData || []);

    const drafts = {};
    filteredBranches.forEach((branch) => {
      const budget = (budgetData || []).find(
        (item) =>
          String(item.provozovna_id) === String(branch.id)
      );
      drafts[String(branch.id)] =
        budget?.castka != null ? String(budget.castka) : "";
    });
    setBudgetDrafts(drafts);
    setLoading(false);
  }

  useEffect(() => {
    loadBudgetData();

    const channel = supabase
      .channel("workshop-budget-live")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_part_orders",
        },
        () => loadBudgetData()
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_budgets",
        },
        () => loadBudgetData()
      )
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "workshop_vehicle_orders",
        },
        () => loadBudgetData()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  function partSpentForBranch(branchId) {
    return orders
      .filter(
        (order) =>
          String(order.provozovna_id) === String(branchId) &&
          order.cena_ks != null
      )
      .reduce(
        (sum, order) =>
          sum +
          Number(order.cena_ks || 0) *
            Number(order.mnozstvi || 0),
        0
      );
  }

  function vehicleSpentForBranch(branchId) {
    return vehicleOrders
      .filter(
        (order) =>
          String(order.provozovna_id) === String(branchId) &&
          order.cena_ks != null
      )
      .reduce(
        (sum, order) =>
          sum +
          Number(order.cena_ks || 0) *
            Number(order.pocet || 0),
        0
      );
  }

  function spentForBranch(branchId) {
    return (
      partSpentForBranch(branchId) +
      vehicleSpentForBranch(branchId)
    );
  }

  function formatMoney(value) {
    return `${Number(value || 0).toLocaleString("cs-CZ", {
      maximumFractionDigits: 2,
    })} Kč`;
  }

  async function saveBudget(branchId) {
    if (!canEdit) return;

    const raw = String(
      budgetDrafts[String(branchId)] || ""
    )
      .trim()
      .replace(",", ".");

    const amount = raw === "" ? 0 : Number(raw);

    if (!Number.isFinite(amount) || amount < 0) {
      setError("Rozpočet musí být platné nezáporné číslo.");
      return;
    }

    setSavingId(branchId);
    setError("");
    setSuccess("");

    const { error: saveError } = await supabase
      .from("workshop_budgets")
      .upsert(
        {
          provozovna_id: Number(branchId),
          castka: amount,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "provozovna_id" }
      );

    if (saveError) {
      setError(saveError.message);
      setSavingId(null);
      return;
    }

    setSuccess("Rozpočet provozovny byl uložen.");
    await loadBudgetData();
    setSavingId(null);
  }

  const totalBudget = branches.reduce((sum, branch) => {
    const budget = budgets.find(
      (item) =>
        String(item.provozovna_id) === String(branch.id)
    );
    return sum + Number(budget?.castka || 0);
  }, 0);

  const totalSpent = branches.reduce(
    (sum, branch) => sum + spentForBranch(branch.id),
    0
  );

  return (
    <div className="standard-page budget-page">
      <header className="standard-page-head">
        <div>
          <span className="page-eyebrow">FINANCE DÍLNY</span>
          <h1>Rozpočet provozoven</h1>
          <p>
            Objednané díly i nové vozy se automaticky odečítají z rozpočtu
            příslušné provozovny. U vozů se počítá cena za vůz × počet kusů.
          </p>
        </div>

        <div className={`access-pill ${canEdit ? "edit" : "read"}`}>
          {canEdit
            ? "ADMIN · NASTAVENÍ ROZPOČTU"
            : "DISPEČER · PŘEHLED"}
        </div>
      </header>

      {error && <div className="error-box">{error}</div>}
      {success && <div className="success-box">{success}</div>}

      <div className="budget-summary-grid">
        <div className="budget-summary-card">
          <span>Celkový rozpočet</span>
          <strong>{formatMoney(totalBudget)}</strong>
        </div>
        <div className="budget-summary-card">
          <span>Čerpáno</span>
          <strong>{formatMoney(totalSpent)}</strong>
        </div>
        <div className="budget-summary-card">
          <span>Zbývá</span>
          <strong>{formatMoney(totalBudget - totalSpent)}</strong>
        </div>
      </div>

      {loading ? (
        <div className="panel empty">Načítám rozpočty…</div>
      ) : (
        <div className="budget-branches">
          {branches.map((branch) => {
            const budget = budgets.find(
              (item) =>
                String(item.provozovna_id) === String(branch.id)
            );
            const budgetAmount = Number(budget?.castka || 0);
            const partSpent = partSpentForBranch(branch.id);
            const vehicleSpent = vehicleSpentForBranch(branch.id);
            const spent = partSpent + vehicleSpent;
            const remaining = budgetAmount - spent;
            const ratio =
              budgetAmount > 0
                ? Math.min(100, (spent / budgetAmount) * 100)
                : 0;

            const branchOrders = orders
              .filter(
                (order) =>
                  String(order.provozovna_id) === String(branch.id)
              )
              .sort(
                (a, b) =>
                  new Date(b.created_at).getTime() -
                  new Date(a.created_at).getTime()
              );

            const branchVehicleOrders = vehicleOrders
              .filter(
                (order) =>
                  String(order.provozovna_id) === String(branch.id)
              )
              .sort(
                (a, b) =>
                  new Date(b.created_at).getTime() -
                  new Date(a.created_at).getTime()
              );

            return (
              <section key={branch.id} className="panel branch-budget-card">
                <div className="branch-budget-head">
                  <div>
                    <span className="branch-budget-code">{branch.kod}</span>
                    <h2>{branch.nazev}</h2>
                  </div>
                  <div className="branch-budget-remaining">
                    <span>Zbývá</span>
                    <strong className={remaining < 0 ? "negative" : ""}>
                      {formatMoney(remaining)}
                    </strong>
                  </div>
                </div>

                <div className="branch-budget-numbers budget-five">
                  <div>
                    <span>Rozpočet</span>
                    <strong>{formatMoney(budgetAmount)}</strong>
                  </div>
                  <div>
                    <span>Díly</span>
                    <strong>{formatMoney(partSpent)}</strong>
                  </div>
                  <div>
                    <span>Vozy</span>
                    <strong>{formatMoney(vehicleSpent)}</strong>
                  </div>
                  <div>
                    <span>Čerpáno celkem</span>
                    <strong>{formatMoney(spent)}</strong>
                  </div>
                  <div>
                    <span>Využití</span>
                    <strong>
                      {budgetAmount > 0
                        ? `${ratio.toFixed(0)} %`
                        : "—"}
                    </strong>
                  </div>
                </div>

                <div className="budget-progress">
                  <span
                    style={{ width: `${ratio}%` }}
                    className={ratio >= 100 ? "over" : ""}
                  />
                </div>

                {canEdit && (
                  <div className="budget-edit-row">
                    <label>
                      <span>Výše rozpočtu</span>
                      <input
                        inputMode="decimal"
                        value={
                          budgetDrafts[String(branch.id)] ?? ""
                        }
                        onChange={(e) =>
                          setBudgetDrafts((old) => ({
                            ...old,
                            [String(branch.id)]: e.target.value,
                          }))
                        }
                        placeholder="0"
                      />
                    </label>

                    <button
                      type="button"
                      className="primary-button"
                      disabled={savingId === branch.id}
                      onClick={() => saveBudget(branch.id)}
                    >
                      {savingId === branch.id
                        ? "Ukládám…"
                        : "Uložit rozpočet"}
                    </button>
                  </div>
                )}

                <div className="budget-order-list vehicle-budget-orders">
                  <div className="budget-order-list-head">
                    <strong>🚌 Objednané vozy</strong>
                    <span>{branchVehicleOrders.length}</span>
                  </div>

                  {branchVehicleOrders.length === 0 ? (
                    <small>Žádné objednané vozy.</small>
                  ) : (
                    branchVehicleOrders.slice(0, 8).map((order) => (
                      <div key={order.id} className="budget-order-row">
                        <div>
                          <strong>
                            {order.vyrobce} {order.model}
                          </strong>
                          <small>
                            {order.pocet} ks · {order.stav}
                          </small>
                        </div>
                        <strong>
                          {formatMoney(
                            Number(order.cena_ks || 0) *
                              Number(order.pocet || 0)
                          )}
                        </strong>
                      </div>
                    ))
                  )}
                </div>

                <div className="budget-order-list">
                  <div className="budget-order-list-head">
                    <strong>🛒 Objednané díly</strong>
                    <span>{branchOrders.length}</span>
                  </div>

                  {branchOrders.length === 0 ? (
                    <small>Žádné objednané díly.</small>
                  ) : (
                    branchOrders.slice(0, 8).map((order) => (
                      <div key={order.id} className="budget-order-row">
                        <div>
                          <strong>{order.nazev_dilu}</strong>
                          <small>
                            {order.mnozstvi} ks · {order.stav}
                          </small>
                        </div>
                        <strong>
                          {formatMoney(
                            Number(order.cena_ks || 0) *
                              Number(order.mnozstvi || 0)
                          )}
                        </strong>
                      </div>
                    ))
                  )}
                </div>
              </section>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* =========================================================
   DKV LICHKOV – EVIDENCE KOLEJOVÝCH VOZIDEL
========================================================= */

const emptyTrain = {
  evidencni_cislo: "",
  druh: "Lokomotiva",
  rada: "",
  trakce: "Dieselová",
  vyrobce: "",
  rok_vyroby: "",
  domovske_depo: "Lichkov",
  stav: "Provozní",
  posledni_prohlidka: "",
  pristi_prohlidka: "",
  poznamka: "",
};

function getDkvSaveError(error) {
  if (error?.code === "23505") return "Toto evidenční číslo už je v DKV Lichkov zapsané.";
  if (error?.code === "42P01" || error?.code === "PGRST205")
    return "Databázová tabulka DKV Lichkov ještě neexistuje. Spusť přiložený SQL skript v Supabase.";
  if (error?.code === "42501" || /row-level security|permission denied/i.test(error?.message || ""))
    return "Záznamy DKV může měnit jen role DKV Lichkov admin nebo Administrátor. Zkontroluj přidělené role a SQL pravidla.";
  if (error?.code === "PGRST116")
    return "Záznam nebyl nalezen nebo pro něj chybí oprávnění UPDATE. Spusť SQL opravu pro úpravy vozidel DKV.";
  return error?.message || "Uložení se nepodařilo. Zkus to znovu.";
}

const DKV_MODULES = {
  objednavky: {
    title: "Objednávky lokomotiv",
    table: "dkv_lichkov_objednavky",
    fields: [
      { name: "cislo_objednavky", label: "Číslo objednávky", required: true },
      { name: "datum", label: "Datum objednávky", type: "date", required: true },
      { name: "evidencni_cislo", label: "Lokomotiva", required: true, train: true },
      { name: "objednatel", label: "Objednatel", required: true },
      { name: "popis", label: "Předmět objednávky", type: "textarea", required: true },
      { name: "stav", label: "Stav", options: ["Nová", "Potvrzená", "Probíhá", "Dokončená", "Zrušená"] },
      { name: "castka_kc", label: "Výdaj z rozpočtu (Kč)", type: "number", min: 0, step: "0.01", required: true },
      { name: "poznamka", label: "Poznámka", type: "textarea" },
    ],
  },
  prijmy: {
    title: "Zakázky a příjmy",
    table: "dkv_lichkov_prijmy",
    fields: [
      { name: "cislo_zakazky", label: "Číslo zakázky", required: true },
      { name: "datum", label: "Datum zakázky", type: "date", required: true },
      { name: "objednatel", label: "Objednatel", required: true },
      { name: "popis", label: "Popis", type: "textarea" },
      { name: "prijem_kc", label: "Příjem po splnění (Kč)", type: "number", min: 0, step: "0.01", required: true },
      { name: "stav", label: "Stav zakázky", options: ["Rozpracovaná", "Splněná", "Očekává se", "Uhrazeno"] },
      { name: "poznamka", label: "Poznámka", type: "textarea" },
    ],
  },
  smeny: {
    title: "Směny a zápisy směn",
    table: "dkv_lichkov_smeny",
    fields: [
      { name: "datum", label: "Datum směny", type: "date", required: true },
      { name: "zamestnanec", label: "Zaměstnanec", required: true },
      { name: "evidencni_cislo", label: "Lokomotiva", train: true },
      { name: "zacatek", label: "Začátek", type: "time", required: true },
      { name: "misto_nastupu", label: "Místo nástupu" },
      { name: "konec", label: "Konec", type: "time" },
      { name: "misto_ukonceni", label: "Místo ukončení" },
      { name: "kilometry", label: "Ujeté kilometry", type: "number", min: 0, step: "0.1" },
      { name: "spotreba_litry", label: "Spotřeba (l)", type: "number", min: 0, step: "0.1" },
      { name: "stav", label: "Stav směny", options: ["Plánovaná", "Probíhá", "Uzavřená"] },
      { name: "poznamka", label: "Zápis směny", type: "textarea" },
    ],
  },
  poruchy: {
    title: "Zápis poruch",
    table: "dkv_lichkov_poruchy",
    fields: [
      { name: "datum", label: "Datum zjištění", type: "date", required: true },
      { name: "evidencni_cislo", label: "Lokomotiva", required: true, train: true },
      { name: "nazev", label: "Název poruchy", required: true },
      { name: "popis", label: "Popis poruchy", type: "textarea", required: true },
      { name: "zavaznost", label: "Závažnost", options: ["Běžná", "Vážná", "Odstavuje vozidlo"] },
      { name: "stav", label: "Stav", options: ["Nahlášená", "V řešení", "Opravená"] },
      { name: "poznamka", label: "Poznámka k řešení", type: "textarea" },
    ],
  },
};

function DkvRecords({ kind, editable, trains }) {
  const config = DKV_MODULES[kind];
  const empty = () => Object.fromEntries(config.fields.map((field) => [
    field.name,
    field.options?.[0] || (field.type === "date" && field.name === "datum" ? localDateIso() : ""),
  ]));
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState(empty);
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function loadRows() {
    setLoading(true);
    const { data, error: loadError } = await supabase
      .from(config.table).select("*").order("datum", { ascending: false });
    if (loadError) setError(getDkvSaveError(loadError));
    else setRows(data || []);
    setLoading(false);
  }

  useEffect(() => {
    setRows([]);
    setForm(empty());
    setEditingId(null);
    setShowForm(false);
    setError("");
    setSuccess("");
    loadRows();
  }, [kind]);

  function closeForm() {
    setShowForm(false);
    setEditingId(null);
    setForm(empty());
  }

  async function save(event) {
    event.preventDefault();
    if (!editable || saving) return;
    setError("");
    setSuccess("");
    const payload = {};
    for (const field of config.fields) {
      const raw = String(form[field.name] ?? "").trim();
      if (field.required && !raw) {
        setError(`Vyplň pole „${field.label}“.`);
        return;
      }
      if (field.type === "number" && raw) {
        const number = Number(raw);
        if (!Number.isFinite(number) || number < (field.min ?? 0)) {
          setError(`Pole „${field.label}“ musí být nezáporné číslo.`);
          return;
        }
        payload[field.name] = number;
      } else {
        payload[field.name] = raw || null;
      }
    }
    setSaving(true);
    const result = editingId
      ? await supabase.from(config.table).update(payload).eq("id", editingId).select("id").single()
      : await supabase.from(config.table).insert(payload).select("id").single();
    setSaving(false);
    if (result.error || !result.data?.id) {
      setError(getDkvSaveError(result.error));
      return;
    }
    closeForm();
    setSuccess(editingId ? "Záznam byl upraven." : "Záznam byl přidán.");
    await loadRows();
  }

  async function remove(row) {
    if (!editable || !window.confirm("Smazat tento záznam?")) return;
    setError("");
    const { data, error: deleteError } = await supabase.from(config.table)
      .delete().eq("id", row.id).select("id").single();
    if (deleteError || !data?.id) {
      setError(getDkvSaveError(deleteError));
      return;
    }
    if (editingId === row.id) closeForm();
    setSuccess("Záznam byl smazán.");
    await loadRows();
  }

  function showValue(field, value) {
    if (value === null || value === undefined || value === "") return "—";
    if (field.type === "date") return new Date(`${value}T12:00:00`).toLocaleDateString("cs-CZ");
    if (field.type === "number") return `${Number(value).toLocaleString("cs-CZ")} ${field.name.endsWith("_kc") ? "Kč" : field.name === "spotreba_litry" ? "l" : field.name === "kilometry" ? "km" : ""}`.trim();
    return String(value);
  }

  return (
    <div className="panel dkv-records">
      <div className="users-toolbar">
        <div><h2>{config.title} ({rows.length})</h2><p className="muted">{editable ? "Záznamy DKV Lichkov" : "Přehled záznamů DKV Lichkov"}</p></div>
        {editable && <button type="button" className="primary-button" onClick={() => {
          if (showForm && !editingId) closeForm();
          else { setEditingId(null); setForm(empty()); setShowForm(true); setError(""); }
        }}>{showForm && !editingId ? "Zavřít" : "+ Přidat záznam"}</button>}
      </div>
      {kind === "objednavky" && <p className="muted">Cena objednávky se odečte z rozpočtu DKV. Zrušená objednávka se nezapočítává.</p>}
      {kind === "prijmy" && <p className="muted">Příjem se přičte do rozpočtu DKV, jakmile má zakázka stav Splněná. Dříve uložený stav Uhrazeno se započítává také.</p>}
      {error && !showForm && <div className="error-box" role="alert">{error}</div>}
      {success && <div className="success-box" role="status">{success}</div>}

      {editable && showForm && <div className="crud-form">
        <h3>{editingId ? "Upravit záznam" : "Nový záznam"}</h3>
        <form onSubmit={save} noValidate>
          <div className="form-grid">
            {config.fields.map((field) => <div key={field.name} className={field.type === "textarea" ? "dkv-wide" : ""}>
              <label htmlFor={`dkv-${kind}-${field.name}`}>{field.label}{field.required ? " *" : ""}</label>
              {field.options ? <select id={`dkv-${kind}-${field.name}`} value={form[field.name] ?? ""} onChange={(e) => setForm((old) => ({ ...old, [field.name]: e.target.value }))}>
                {field.options.map((option) => <option key={option}>{option}</option>)}
              </select> : field.type === "textarea" ? <textarea id={`dkv-${kind}-${field.name}`} rows="3" maxLength={2000} value={form[field.name] ?? ""} onChange={(e) => setForm((old) => ({ ...old, [field.name]: e.target.value }))} /> : <input
                id={`dkv-${kind}-${field.name}`} type={field.type || "text"} min={field.min} step={field.step} maxLength={field.type === "number" ? undefined : 150}
                list={field.train ? "dkv-train-numbers" : undefined}
                value={field.type === "time" ? String(form[field.name] ?? "").slice(0, 5) : (form[field.name] ?? "")}
                onChange={(e) => setForm((old) => ({ ...old, [field.name]: e.target.value }))}
              />}
            </div>)}
          </div>
          <datalist id="dkv-train-numbers">{trains.map((train) => <option key={train.id} value={train.evidencni_cislo} />)}</datalist>
          {error && <div className="error-box" role="alert">{error}</div>}
          <div className="form-buttons"><button type="submit" className="primary-button" disabled={saving}>{saving ? "Ukládání..." : "Uložit"}</button><button type="button" className="secondary-button" onClick={closeForm}>Zrušit</button></div>
        </form>
      </div>}

      {loading ? <div className="empty">Načítání záznamů...</div> : rows.length === 0 ? <div className="empty">Zatím žádné záznamy.</div> : <div className="dkv-list">
        {rows.map((row) => <article className="dkv-card" key={row.id}>
          <div className="dkv-card-details">{config.fields.map((field) => <div key={field.name} className={field.type === "textarea" ? "dkv-wide" : ""}>
            <small>{field.label}</small><strong>{showValue(field, row[field.name])}</strong>
          </div>)}</div>
          {editable && <div className="form-buttons"><button type="button" className="secondary-button" onClick={() => { setEditingId(row.id); setForm(Object.fromEntries(config.fields.map((field) => [field.name, row[field.name] ?? ""]))); setShowForm(true); setError(""); setSuccess(""); }}>Upravit</button><button type="button" className="delete-button" onClick={() => remove(row)}>Smazat</button></div>}
        </article>)}
      </div>}
    </div>
  );
}

const DKV_WEEKDAYS = ["Po", "Út", "St", "Čt", "Pá", "So", "Ne"];

function nextDkvShiftDate(shift, today = localDateIso()) {
  if (shift.stav !== "Aktivní") return null;
  const base = new Date(`${today}T12:00:00`);
  for (let offset = 0; offset < 90; offset++) {
    const day = new Date(base);
    day.setDate(base.getDate() + offset);
    const date = localDateIso(day);
    if (date < shift.platnost_od || (shift.platnost_do && date > shift.platnost_do)) continue;
    if ((shift.dny_v_tydnu || []).includes(day.getDay() || 7)) return date;
  }
  return null;
}

function DkvConsists({ editable, trains }) {
  const empty = () => ({ oznaceni: "", linka: "", vychozi_stanice: "", cilova_stanice: "", vozy: [{ evidencni_cislo: "", typ: "Lokomotiva" }], poznamka: "" });
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState(empty);
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function load() {
    setLoading(true);
    const { data, error: loadError } = await supabase.from("dkv_lichkov_soupravy").select("*").order("oznaceni");
    if (loadError) setError(getDkvSaveError(loadError));
    else { setRows(data || []); setError(""); }
    setLoading(false);
  }
  useEffect(() => { load(); }, []);
  function close() { setShowForm(false); setEditingId(null); setForm(empty()); }
  function change(name, value) { setForm((old) => ({ ...old, [name]: value })); }
  function changeVehicle(index, name, value) {
    setForm((old) => ({ ...old, vozy: old.vozy.map((item, i) => i === index ? { ...item, [name]: value } : item) }));
  }
  function moveVehicle(index, direction) {
    setForm((old) => {
      const next = [...old.vozy];
      const other = index + direction;
      if (other < 0 || other >= next.length) return old;
      [next[index], next[other]] = [next[other], next[index]];
      return { ...old, vozy: next };
    });
  }

  async function save(event) {
    event.preventDefault();
    if (!editable || saving) return;
    setError(""); setSuccess("");
    const vehicles = form.vozy.map((item) => ({
      evidencni_cislo: String(item.evidencni_cislo ?? "").trim(),
      typ: String(item.typ ?? "").trim() || "Jiné",
    }));
    if (!form.oznaceni.trim() || !vehicles.length || vehicles.some((item) => !item.evidencni_cislo)) {
      setError("Vyplň označení soupravy a číslo každého vozidla."); return;
    }
    if (vehicles.length > 30 || vehicles.some((item) => item.evidencni_cislo.length > 150)) {
      setError("Souprava může mít nejvýše 30 vozidel; číslo každého může mít nejvýše 150 znaků."); return;
    }
    const payload = {
      oznaceni: form.oznaceni.trim(), linka: form.linka.trim() || null,
      vychozi_stanice: form.vychozi_stanice.trim() || null,
      cilova_stanice: form.cilova_stanice.trim() || null,
      vozy: vehicles, poznamka: form.poznamka.trim() || null,
    };
    setSaving(true);
    try {
      const result = editingId
        ? await supabase.from("dkv_lichkov_soupravy").update(payload).eq("id", editingId).select("id").single()
        : await supabase.from("dkv_lichkov_soupravy").insert(payload).select("id").single();
      if (result.error || !result.data?.id) throw result.error || new Error("Soupravu se nepodařilo uložit.");
      close(); await load(); setSuccess("Souprava byla uložena.");
    } catch (saveError) { setError(saveError?.code === "23505" ? "Souprava s tímto označením už existuje." : getDkvSaveError(saveError)); }
    finally { setSaving(false); }
  }

  async function remove(row) {
    if (!editable || !window.confirm(`Smazat soupravu ${row.oznaceni}?`)) return;
    const { data, error: deleteError } = await supabase.from("dkv_lichkov_soupravy").delete().eq("id", row.id).select("id").single();
    if (deleteError || !data?.id) { setError(deleteError?.code === "23503" ? "Souprava je přiřazena pravidelné směně. Nejdřív změň přiřazení směny." : getDkvSaveError(deleteError)); return; }
    if (editingId === row.id) close();
    await load(); setSuccess("Souprava byla smazána.");
  }

  return <div className="panel dkv-records">
    <div className="users-toolbar"><div><h2>Soupravy pro strojvedoucí ({rows.length})</h2><p className="muted">Pořadí vozidel určuje skutečné řazení soupravy.</p></div>
      {editable && <button type="button" className="primary-button" onClick={() => { if (showForm && !editingId) close(); else { setEditingId(null); setForm(empty()); setShowForm(true); setError(""); } }}>{showForm && !editingId ? "Zavřít" : "+ Přidat soupravu"}</button>}
    </div>
    {success && <div className="success-box" role="status">{success}</div>}
    {error && !showForm && <div className="error-box" role="alert">{error}</div>}
    {editable && showForm && <div className="crud-form"><h3>{editingId ? "Upravit soupravu" : "Nová souprava"}</h3><form onSubmit={save} noValidate>
      <div className="form-grid">
        <div><label htmlFor="dkv-consist-name">Označení soupravy *</label><input id="dkv-consist-name" value={form.oznaceni} onChange={(e) => change("oznaceni", e.target.value)} maxLength={150} /></div>
        <div><label htmlFor="dkv-consist-line">Linka / spoj</label><input id="dkv-consist-line" value={form.linka} onChange={(e) => change("linka", e.target.value)} maxLength={150} /></div>
        <div><label htmlFor="dkv-consist-start">Výchozí stanice</label><input id="dkv-consist-start" value={form.vychozi_stanice} onChange={(e) => change("vychozi_stanice", e.target.value)} maxLength={150} /></div>
        <div><label htmlFor="dkv-consist-end">Cílová stanice</label><input id="dkv-consist-end" value={form.cilova_stanice} onChange={(e) => change("cilova_stanice", e.target.value)} maxLength={150} /></div>
      </div>
      <h4>Řazení vozidel</h4>
      <datalist id="dkv-consist-trains">{trains.map((train) => <option key={train.id} value={train.evidencni_cislo} />)}</datalist>
      {form.vozy.map((item, index) => <div className="dkv-consist-editor-row" key={index}>
        <strong>{index + 1}.</strong>
        <input aria-label={`Číslo vozidla ${index + 1}`} list="dkv-consist-trains" value={item.evidencni_cislo} onChange={(e) => changeVehicle(index, "evidencni_cislo", e.target.value)} placeholder="Číslo vozidla *" maxLength={150} />
        <select aria-label={`Druh vozidla ${index + 1}`} value={item.typ} onChange={(e) => changeVehicle(index, "typ", e.target.value)}>{["Lokomotiva", "Motorová jednotka", "Elektrická jednotka", "Osobní vůz", "Nákladní vůz", "Jiné"].map((type) => <option key={type}>{type}</option>)}</select>
        <button type="button" className="secondary-button" disabled={index === 0} onClick={() => moveVehicle(index, -1)} aria-label={`Posunout vozidlo ${index + 1} nahoru`}>↑</button>
        <button type="button" className="secondary-button" disabled={index === form.vozy.length - 1} onClick={() => moveVehicle(index, 1)} aria-label={`Posunout vozidlo ${index + 1} dolů`}>↓</button>
        <button type="button" className="delete-button" onClick={() => change("vozy", form.vozy.filter((_, i) => i !== index))} aria-label={`Odebrat vozidlo ${index + 1}`}>×</button>
      </div>)}
      <button type="button" className="secondary-button" disabled={form.vozy.length >= 30} onClick={() => change("vozy", [...form.vozy, { evidencni_cislo: "", typ: "Osobní vůz" }])}>+ Přidat vozidlo do soupravy</button>
      <div className="dkv-plan-note"><label htmlFor="dkv-consist-note">Pokyny pro strojvedoucí</label><textarea id="dkv-consist-note" rows="3" maxLength={2000} value={form.poznamka} onChange={(e) => change("poznamka", e.target.value)} /></div>
      {error && <div className="error-box" role="alert">{error}</div>}
      <div className="form-buttons"><button type="submit" className="primary-button" disabled={saving}>{saving ? "Ukládání…" : "Uložit soupravu"}</button><button type="button" className="secondary-button" onClick={close}>Zrušit</button></div>
    </form></div>}
    {loading ? <div className="empty">Načítání souprav…</div> : rows.length === 0 ? <div className="empty">Zatím nejsou vytvořené soupravy.</div> : <div className="dkv-list">{rows.map((row) => <article className="dkv-card" key={row.id}>
      <div className="dkv-card-head"><strong>{row.oznaceni}</strong><span>{row.linka || "Souprava"}</span></div>
      <p>{row.vychozi_stanice || "—"} → {row.cilova_stanice || "—"}</p>
      <ol className="dkv-consist-vehicles">{(Array.isArray(row.vozy) ? row.vozy : []).map((item, index) => <li key={`${index}-${item.evidencni_cislo}`}>{item.typ}: <strong>{item.evidencni_cislo}</strong></li>)}</ol>
      {row.poznamka && <p className="dkv-note">{row.poznamka}</p>}
      {editable && <div className="form-buttons"><button type="button" className="secondary-button" onClick={() => { setEditingId(row.id); setForm({ oznaceni: row.oznaceni || "", linka: row.linka || "", vychozi_stanice: row.vychozi_stanice || "", cilova_stanice: row.cilova_stanice || "", vozy: Array.isArray(row.vozy) ? row.vozy.map((item) => ({ evidencni_cislo: item.evidencni_cislo || "", typ: item.typ || "Jiné" })) : [], poznamka: row.poznamka || "" }); setShowForm(true); setError(""); setSuccess(""); }}>Upravit</button><button type="button" className="delete-button" onClick={() => remove(row)}>Smazat</button></div>}
    </article>)}</div>}
  </div>;
}

function DkvRecurringShifts({ editable }) {
  const empty = () => ({ nazev: "", strojvedouci: "", souprava_id: "", dny_v_tydnu: [1, 2, 3, 4, 5], platnost_od: localDateIso(), platnost_do: "", zacatek: "", konec: "", misto_nastupu: "", misto_ukonceni: "", stav: "Aktivní", poznamka: "" });
  const [rows, setRows] = useState([]);
  const [consists, setConsists] = useState([]);
  const [form, setForm] = useState(empty);
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  async function load() {
    setLoading(true);
    const [shiftResult, consistResult] = await Promise.all([
      supabase.from("dkv_lichkov_pravidelne_smeny").select("*").order("platnost_od", { ascending: false }),
      supabase.from("dkv_lichkov_soupravy").select("id,oznaceni,vozy,linka").order("oznaceni"),
    ]);
    const loadError = shiftResult.error || consistResult.error;
    if (loadError) setError(getDkvSaveError(loadError));
    else { setRows(shiftResult.data || []); setConsists(consistResult.data || []); setError(""); }
    setLoading(false);
  }
  useEffect(() => { load(); }, []);
  function close() { setShowForm(false); setEditingId(null); setForm(empty()); }
  function change(name, value) { setForm((old) => ({ ...old, [name]: value })); }

  async function save(event) {
    event.preventDefault();
    if (!editable || saving) return;
    setError(""); setSuccess("");
    const payload = {
      nazev: form.nazev.trim(), strojvedouci: form.strojvedouci.trim(),
      souprava_id: form.souprava_id || null,
      dny_v_tydnu: [...form.dny_v_tydnu].sort((a, b) => a - b),
      platnost_od: form.platnost_od, platnost_do: form.platnost_do || null,
      zacatek: form.zacatek, konec: form.konec,
      misto_nastupu: form.misto_nastupu.trim(), misto_ukonceni: form.misto_ukonceni.trim(),
      stav: form.stav, poznamka: form.poznamka.trim() || null,
    };
    if (!payload.nazev || !payload.strojvedouci || !payload.platnost_od || !payload.zacatek || !payload.konec || !payload.misto_nastupu || !payload.misto_ukonceni) {
      setError("Vyplň název, strojvedoucího, platnost, časy a místa nástupu i ukončení."); return;
    }
    if (!payload.dny_v_tydnu.length) { setError("Vyber alespoň jeden den v týdnu."); return; }
    if (payload.platnost_do && payload.platnost_do < payload.platnost_od) { setError("Konec platnosti musí být po začátku platnosti."); return; }
    setSaving(true);
    try {
      const result = editingId
        ? await supabase.from("dkv_lichkov_pravidelne_smeny").update(payload).eq("id", editingId).select("id").single()
        : await supabase.from("dkv_lichkov_pravidelne_smeny").insert(payload).select("id").single();
      if (result.error || !result.data?.id) throw result.error || new Error("Směnu se nepodařilo uložit.");
      close(); await load(); setSuccess("Pravidelná směna byla uložena.");
    } catch (saveError) { setError(getDkvSaveError(saveError)); }
    finally { setSaving(false); }
  }

  async function remove(row) {
    if (!editable || !window.confirm(`Smazat pravidelnou směnu ${row.nazev}?`)) return;
    const { data, error: deleteError } = await supabase.from("dkv_lichkov_pravidelne_smeny").delete().eq("id", row.id).select("id").single();
    if (deleteError || !data?.id) { setError(getDkvSaveError(deleteError)); return; }
    if (editingId === row.id) close();
    await load(); setSuccess("Pravidelná směna byla smazána.");
  }

  return <div className="panel dkv-records">
    <div className="users-toolbar"><div><h2>Pravidelné směny ({rows.length})</h2><p className="muted">Opakují se ve vybrané dny a po dobu platnosti. Zápis skutečného průběhu směny je v záložce Směny.</p></div>
      {editable && <button type="button" className="primary-button" onClick={() => { if (showForm && !editingId) close(); else { setEditingId(null); setForm(empty()); setShowForm(true); setError(""); } }}>{showForm && !editingId ? "Zavřít" : "+ Přidat pravidelnou směnu"}</button>}
    </div>
    {success && <div className="success-box" role="status">{success}</div>}
    {error && !showForm && <div className="error-box" role="alert">{error}</div>}
    {editable && showForm && <div className="crud-form"><h3>{editingId ? "Upravit pravidelnou směnu" : "Nová pravidelná směna"}</h3><form onSubmit={save} noValidate>
      <div className="form-grid">
        <div><label htmlFor="dkv-shift-name">Název / spoj *</label><input id="dkv-shift-name" maxLength={150} value={form.nazev} onChange={(e) => change("nazev", e.target.value)} placeholder="Osobní doprava 1" /></div>
        <div><label htmlFor="dkv-shift-driver">Strojvedoucí *</label><input id="dkv-shift-driver" maxLength={150} value={form.strojvedouci} onChange={(e) => change("strojvedouci", e.target.value)} /></div>
        <div><label htmlFor="dkv-shift-consist">Přidělená souprava</label><select id="dkv-shift-consist" value={form.souprava_id} onChange={(e) => change("souprava_id", e.target.value)}><option value="">Bez soupravy</option>{consists.map((item) => <option key={item.id} value={item.id}>{item.oznaceni}{item.linka ? ` · ${item.linka}` : ""}</option>)}</select></div>
        <div><label htmlFor="dkv-shift-status">Stav</label><select id="dkv-shift-status" value={form.stav} onChange={(e) => change("stav", e.target.value)}><option>Aktivní</option><option>Pozastavená</option></select></div>
        <div><label htmlFor="dkv-shift-from">Platnost od *</label><input id="dkv-shift-from" type="date" value={form.platnost_od} onChange={(e) => change("platnost_od", e.target.value)} /></div>
        <div><label htmlFor="dkv-shift-to">Platnost do</label><input id="dkv-shift-to" type="date" value={form.platnost_do} onChange={(e) => change("platnost_do", e.target.value)} /></div>
        <div><label htmlFor="dkv-shift-time-start">Nástup *</label><input id="dkv-shift-time-start" type="time" value={form.zacatek} onChange={(e) => change("zacatek", e.target.value)} /></div>
        <div><label htmlFor="dkv-shift-time-end">Konec *</label><input id="dkv-shift-time-end" type="time" value={form.konec} onChange={(e) => change("konec", e.target.value)} /></div>
        <div><label htmlFor="dkv-shift-place-start">Místo nástupu *</label><input id="dkv-shift-place-start" maxLength={150} value={form.misto_nastupu} onChange={(e) => change("misto_nastupu", e.target.value)} /></div>
        <div><label htmlFor="dkv-shift-place-end">Místo ukončení *</label><input id="dkv-shift-place-end" maxLength={150} value={form.misto_ukonceni} onChange={(e) => change("misto_ukonceni", e.target.value)} /></div>
        <fieldset className="dkv-wide dkv-days"><legend>Dny v týdnu *</legend>{DKV_WEEKDAYS.map((label, index) => { const day = index + 1; return <label key={day}><input type="checkbox" checked={form.dny_v_tydnu.includes(day)} onChange={() => change("dny_v_tydnu", form.dny_v_tydnu.includes(day) ? form.dny_v_tydnu.filter((item) => item !== day) : [...form.dny_v_tydnu, day])} />{label}</label>; })}</fieldset>
        <div className="dkv-wide"><label htmlFor="dkv-shift-note">Poznámka</label><textarea id="dkv-shift-note" rows="3" maxLength={2000} value={form.poznamka} onChange={(e) => change("poznamka", e.target.value)} /></div>
      </div>
      {error && <div className="error-box" role="alert">{error}</div>}
      <div className="form-buttons"><button type="submit" className="primary-button" disabled={saving}>{saving ? "Ukládání…" : "Uložit pravidelnou směnu"}</button><button type="button" className="secondary-button" onClick={close}>Zrušit</button></div>
    </form></div>}
    {loading ? <div className="empty">Načítání pravidelných směn…</div> : rows.length === 0 ? <div className="empty">Zatím nejsou naplánované pravidelné směny.</div> : <div className="dkv-list">{rows.map((row) => {
      const consist = consists.find((item) => item.id === row.souprava_id);
      const nextDate = nextDkvShiftDate(row);
      return <article className="dkv-card" key={row.id}>
        <div className="dkv-card-head"><strong>{row.nazev}</strong><span>{row.stav}</span></div>
        <div className="dkv-card-details">
          <div><small>Strojvedoucí</small><strong>{row.strojvedouci}</strong></div>
          <div><small>Dny</small><strong>{(row.dny_v_tydnu || []).map((day) => DKV_WEEKDAYS[day - 1]).join(", ")}</strong></div>
          <div><small>Čas</small><strong>{String(row.zacatek).slice(0, 5)} – {String(row.konec).slice(0, 5)}</strong></div>
          <div><small>Nástup → konec</small><strong>{row.misto_nastupu} → {row.misto_ukonceni}</strong></div>
          <div><small>Platnost</small><strong>{row.platnost_od} – {row.platnost_do || "dále"}</strong></div>
          <div><small>Nejbližší směna</small><strong>{nextDate ? new Date(`${nextDate}T12:00:00`).toLocaleDateString("cs-CZ") : "Není v příštích 90 dnech"}</strong></div>
        </div>
        {consist && <div className="dkv-shift-consist"><strong>Souprava: {consist.oznaceni}</strong><ol className="dkv-consist-vehicles">{(Array.isArray(consist.vozy) ? consist.vozy : []).map((item, index) => <li key={`${index}-${item.evidencni_cislo}`}>{item.typ}: <strong>{item.evidencni_cislo}</strong></li>)}</ol></div>}
        {row.poznamka && <p className="dkv-note">{row.poznamka}</p>}
        {editable && <div className="form-buttons"><button type="button" className="secondary-button" onClick={() => { setEditingId(row.id); setForm({ nazev: row.nazev || "", strojvedouci: row.strojvedouci || "", souprava_id: row.souprava_id || "", dny_v_tydnu: row.dny_v_tydnu || [], platnost_od: row.platnost_od || "", platnost_do: row.platnost_do || "", zacatek: String(row.zacatek || "").slice(0, 5), konec: String(row.konec || "").slice(0, 5), misto_nastupu: row.misto_nastupu || "", misto_ukonceni: row.misto_ukonceni || "", stav: row.stav || "Aktivní", poznamka: row.poznamka || "" }); setShowForm(true); setError(""); setSuccess(""); }}>Upravit</button><button type="button" className="delete-button" onClick={() => remove(row)}>Smazat</button></div>}
      </article>;
    })}</div>}
  </div>;
}

function DkvLichkov({ role }) {
  const editable = canEditDkv(role);
  const [section, setSection] = useState("vozidla");
  const [trains, setTrains] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyTrain);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("Vše");

  async function loadTrains() {
    setLoading(true);
    const { data, error: loadError } = await supabase
      .from("dkv_lichkov_vozidla")
      .select("*")
      .order("evidencni_cislo", { ascending: true });
    if (loadError) {
      setError(getDkvSaveError(loadError));
      setTrains([]);
    } else {
      setTrains(data || []);
    }
    setLoading(false);
  }

  useEffect(() => {
    loadTrains();
  }, []);

  function change(field, value) {
    setForm((old) => ({ ...old, [field]: value }));
  }

  function beginEdit(train) {
    if (!editable) return;
    setEditingId(train.id);
    setForm({
      ...emptyTrain,
      ...train,
      rada: train.rada ?? "",
      vyrobce: train.vyrobce ?? "",
      rok_vyroby: train.rok_vyroby ?? "",
      posledni_prohlidka: train.posledni_prohlidka || "",
      pristi_prohlidka: train.pristi_prohlidka || "",
      poznamka: train.poznamka ?? "",
    });
    setShowForm(true);
    setError("");
    setSuccess("");
  }

  function closeForm() {
    setShowForm(false);
    setEditingId(null);
    setForm(emptyTrain);
  }

  async function saveTrain(event) {
    event.preventDefault();
    if (!editable) return;
    if (saving) return;
    setError("");
    setSuccess("");
    if (
      form.posledni_prohlidka &&
      form.pristi_prohlidka &&
      form.pristi_prohlidka < form.posledni_prohlidka
    ) {
      setError("Příští prohlídka nemůže předcházet poslední prohlídce.");
      return;
    }

    const payload = {
      evidencni_cislo: String(form.evidencni_cislo ?? "").trim(),
      druh: form.druh,
      rada: String(form.rada ?? "").trim() || null,
      trakce: form.trakce,
      vyrobce: String(form.vyrobce ?? "").trim() || null,
      rok_vyroby: form.rok_vyroby == null || form.rok_vyroby === "" ? null : Number(form.rok_vyroby),
      domovske_depo: String(form.domovske_depo ?? "").trim(),
      stav: form.stav,
      posledni_prohlidka: form.posledni_prohlidka || null,
      pristi_prohlidka: form.pristi_prohlidka || null,
      poznamka: String(form.poznamka ?? "").trim() || null,
    };
    if (!payload.evidencni_cislo || !payload.domovske_depo) {
      setError("Vyplň evidenční číslo a domovské depo.");
      return;
    }
    if (payload.rok_vyroby !== null &&
        (!Number.isInteger(payload.rok_vyroby) || payload.rok_vyroby < 1800 || payload.rok_vyroby > 2100)) {
      setError("Rok výroby musí být celé číslo od 1800 do 2100.");
      return;
    }

    setSaving(true);
    try {
      const result = editingId
        ? await supabase.from("dkv_lichkov_vozidla").update(payload).eq("id", editingId).select("id").single()
        : await supabase.from("dkv_lichkov_vozidla").insert(payload).select("id").single();
      if (result.error || !result.data?.id) {
        setError(getDkvSaveError(result.error));
        return;
      }
      setSuccess(editingId ? "Záznam byl upraven." : "Kolejové vozidlo bylo přidáno.");
      closeForm();
      await loadTrains();
    } catch (saveError) {
      setError(getDkvSaveError(saveError));
    } finally {
      setSaving(false);
    }
  }

  async function deleteTrain(train) {
    if (!editable) return;
    if (!window.confirm(`Smazat vozidlo ${train.evidencni_cislo}?`)) return;
    setError("");
    setSuccess("");
    const { data: deleted, error: deleteError } = await supabase
      .from("dkv_lichkov_vozidla")
      .delete()
      .eq("id", train.id)
      .select("id")
      .single();
    if (deleteError || !deleted?.id) {
      setError(getDkvSaveError(deleteError));
      return;
    }
    if (editingId === train.id) closeForm();
    setSuccess("Záznam byl smazán.");
    await loadTrains();
  }

  const visibleTrains = trains.filter((train) => {
    const text = `${train.evidencni_cislo} ${train.rada || ""} ${train.vyrobce || ""} ${train.domovske_depo}`.toLocaleLowerCase("cs");
    return (statusFilter === "Vše" || train.stav === statusFilter) &&
      text.includes(search.trim().toLocaleLowerCase("cs"));
  });

  return (
    <div className="dkv-page">
      <div className="topbar">
        <div>
          <h1>DKV Lichkov</h1>
          <p>Evidence lokomotiv, jednotek a železničních vozů</p>
        </div>
        <div className="profile-badge">{getRoleName(role)}</div>
      </div>

      <nav className="dkv-tabs" aria-label="Agenda DKV Lichkov">
        {[["vozidla", "Lokomotivy a vozy"], ["objednavky", "Objednávky lokomotiv"], ["prijmy", "Zakázky a příjmy"], ["smeny", "Směny"], ["pravidelne_smeny", "Pravidelné směny"], ["soupravy", "Soupravy"], ["poruchy", "Poruchy"]].map(([key, label]) => (
          <button type="button" key={key} className={section === key ? "active" : ""} aria-current={section === key ? "page" : undefined} onClick={() => setSection(key)}>{label}</button>
        ))}
      </nav>

      {section === "soupravy" ? <DkvConsists editable={editable} trains={trains} /> : section === "pravidelne_smeny" ? <DkvRecurringShifts editable={editable} /> : section !== "vozidla" ? <DkvRecords key={section} kind={section} editable={editable} trains={trains} /> : <>

      {error && !showForm && <div className="error-box" role="alert">{error}</div>}
      {success && <div className="success-box" role="status">{success}</div>}

      <div className="panel">
        <div className="users-toolbar">
          <div><h2>Kolejová vozidla ({trains.length})</h2><p className="muted">{editable ? "Správa vozového parku DKV Lichkov." : "Přehled vozového parku DKV Lichkov."}</p></div>
          {editable && <button type="button" className="primary-button" onClick={() => {
            if (showForm && !editingId) closeForm();
            else { setEditingId(null); setForm(emptyTrain); setShowForm(true); setError(""); }
          }}>{showForm && !editingId ? "Zavřít" : "+ Přidat vozidlo"}</button>}
        </div>

        {editable && showForm && (
          <div className="crud-form">
            <h3>{editingId ? "Upravit kolejové vozidlo" : "Přidat kolejové vozidlo"}</h3>
            <form onSubmit={saveTrain} noValidate>
              <div className="form-grid">
                <div><label htmlFor="dkv-number">Evidenční číslo *</label><input id="dkv-number" value={form.evidencni_cislo} onChange={(e) => change("evidencni_cislo", e.target.value)} placeholder="např. 754 012-3" required maxLength={50} /></div>
                <div><label htmlFor="dkv-kind">Druh vozidla</label><select id="dkv-kind" value={form.druh} onChange={(e) => change("druh", e.target.value)}>{["Lokomotiva", "Motorová jednotka", "Elektrická jednotka", "Osobní vůz", "Nákladní vůz", "Jiné"].map((item) => <option key={item}>{item}</option>)}</select></div>
                <div><label htmlFor="dkv-class">Řada</label><input id="dkv-class" value={form.rada} onChange={(e) => change("rada", e.target.value)} placeholder="např. 754" maxLength={50} /></div>
                <div><label htmlFor="dkv-traction">Trakce</label><select id="dkv-traction" value={form.trakce} onChange={(e) => change("trakce", e.target.value)}>{["Dieselová", "Elektrická", "Bez vlastního pohonu", "Jiná"].map((item) => <option key={item}>{item}</option>)}</select></div>
                <div><label htmlFor="dkv-maker">Výrobce</label><input id="dkv-maker" value={form.vyrobce} onChange={(e) => change("vyrobce", e.target.value)} maxLength={120} /></div>
                <div><label htmlFor="dkv-year">Rok výroby</label><input id="dkv-year" type="number" min="1800" max="2100" value={form.rok_vyroby} onChange={(e) => change("rok_vyroby", e.target.value)} /></div>
                <div><label htmlFor="dkv-depot">Domovské depo *</label><input id="dkv-depot" value={form.domovske_depo} onChange={(e) => change("domovske_depo", e.target.value)} required maxLength={120} /></div>
                <div><label htmlFor="dkv-status">Stav</label><select id="dkv-status" value={form.stav} onChange={(e) => change("stav", e.target.value)}>{["Provozní", "V opravě", "Odstavené", "Mimo provoz"].map((item) => <option key={item}>{item}</option>)}</select></div>
                <div><label htmlFor="dkv-last-check">Poslední prohlídka</label><input id="dkv-last-check" type="date" value={form.posledni_prohlidka} onChange={(e) => change("posledni_prohlidka", e.target.value)} /></div>
                <div><label htmlFor="dkv-next-check">Příští prohlídka</label><input id="dkv-next-check" type="date" value={form.pristi_prohlidka} onChange={(e) => change("pristi_prohlidka", e.target.value)} /></div>
                <div className="dkv-wide"><label htmlFor="dkv-note">Poznámka</label><textarea id="dkv-note" rows="3" maxLength={2000} value={form.poznamka} onChange={(e) => change("poznamka", e.target.value)} /></div>
              </div>
              {error && <div className="error-box" role="alert">{error}</div>}
              <div className="form-buttons"><button type="submit" className="primary-button" disabled={saving}>{saving ? "Ukládání..." : "Uložit"}</button><button type="button" className="secondary-button" onClick={closeForm}>Zrušit</button></div>
            </form>
          </div>
        )}

        <div className="dkv-filters">
          <label htmlFor="dkv-search">Hledat vozidlo</label>
          <input id="dkv-search" type="search" placeholder="Číslo, řada, výrobce nebo depo" value={search} onChange={(e) => setSearch(e.target.value)} />
          <label htmlFor="dkv-filter">Stav</label>
          <select id="dkv-filter" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>{["Vše", "Provozní", "V opravě", "Odstavené", "Mimo provoz"].map((item) => <option key={item}>{item}</option>)}</select>
        </div>

        {loading ? <div className="empty">Načítání vozidel...</div> : visibleTrains.length === 0 ? <div className="empty">{trains.length ? "Žádné vozidlo neodpovídá filtru." : "Zatím nejsou zapsaná žádná kolejová vozidla."}</div> : (
          <div className="dkv-list">{visibleTrains.map((train) => (
            <article className="dkv-card" key={train.id}>
              <div className="dkv-card-head"><strong>{train.evidencni_cislo}</strong><span>{train.stav}</span></div>
              <div className="dkv-card-details">
                <div><small>Druh / řada</small><strong>{train.druh}{train.rada ? ` · ${train.rada}` : ""}</strong></div>
                <div><small>Trakce</small><strong>{train.trakce}</strong></div>
                <div><small>Výrobce / rok</small><strong>{train.vyrobce || "—"}{train.rok_vyroby ? ` · ${train.rok_vyroby}` : ""}</strong></div>
                <div><small>Domovské depo</small><strong>{train.domovske_depo}</strong></div>
                <div><small>Poslední prohlídka</small><strong>{train.posledni_prohlidka ? new Date(`${train.posledni_prohlidka}T12:00:00`).toLocaleDateString("cs-CZ") : "—"}</strong></div>
                <div><small>Příští prohlídka</small><strong>{train.pristi_prohlidka ? new Date(`${train.pristi_prohlidka}T12:00:00`).toLocaleDateString("cs-CZ") : "—"}</strong></div>
              </div>
              {train.poznamka && <p className="dkv-note">{train.poznamka}</p>}
              {editable && <div className="form-buttons"><button type="button" className="secondary-button" onClick={() => beginEdit(train)}>Upravit</button><button type="button" className="delete-button" onClick={() => deleteTrain(train)}>Smazat</button></div>}
            </article>
          ))}</div>
        )}
      </div>
      </>}
    </div>
  );
}

const DASHBOARD_IMAGES = [
  "/dashboard/dashboard-1.webp",
  "/dashboard/dashboard-2.webp",
  "/dashboard/dashboard-3.webp",
  "/dashboard/dashboard-4.webp",
  "/dashboard/dashboard-5.webp",
  "/dashboard/dashboard-6.webp",
  "/dashboard/dashboard-7.webp",
  "/dashboard/dashboard-8.webp",
  "/dashboard/dashboard-9.webp",
  "/dashboard/dashboard-10.webp",
];

/* POP: self-contained training UI. Existing Supabase auth and business tables are unchanged. */
